    fn message(id: &str, is_me: bool, content: &str) -> Message {
        Message {
            id: id.to_string(),
            sender: if is_me { "Me" } else { "AI" }.to_string(),
            content: content.to_string(),
            sent_at: SystemTime::UNIX_EPOCH,
            finished_at: None,
            run_timing: None,
            reply_source: None,
            is_me,
            reply_preview: None,
            reply_to_id: None,
            reply_is_me: false,
            parts: Vec::new(),
            run_id: None,
            hidden: false,
        }
    }

    fn replying_to(mut message: Message, quoted: &Message) -> Message {
        message.reply_to_id = Some(quoted.id.clone());
        message.reply_preview = Some(quoted.content.clone());
        message.reply_is_me = quoted.is_me;
        message
    }

    /// The whole point: "what am I replying to?" must arrive with the quote, because the server
    /// answers from the array the app sends and nothing else.
    #[test]
    fn a_reply_reaches_the_coworker_as_a_quote_ahead_of_its_own_words() {
        let bot = message("m1", false, "The build is green.");
        let reply = replying_to(message("m2", true, "what am I replying to?"), &bot);
        let sent = agui_messages(&[bot, reply]);
        assert_eq!(sent.len(), 2);
        assert_eq!(
            sent[1].content,
            "[Replying to your earlier message: \"The build is green.\"]\n\nwhat am I replying to?"
        );
        let quote = sent[1].reply_to.as_ref().expect("the field is filled too");
        assert_eq!(quote.message_id, "m1");
        assert_eq!(quote.preview, "The build is green.");
        assert!(!quote.is_me);
    }

    #[test]
    fn stream_paint_coalesces_text_and_flushes_on_a_card() {
        let t0 = Instant::now();
        let text = vec![ChatPart::Text("hi".into())];
        let sig = stream_part_sig(&text);
        assert!(
            stream_paint_due(None, t0, (0, 0), sig),
            "the first token paints"
        );
        assert!(
            !stream_paint_due(Some(t0), t0, sig, sig),
            "another token in the same 16ms does not notify"
        );
        assert!(
            stream_paint_due(Some(t0), t0 + Duration::from_millis(16), sig, sig),
            "text flushes at ~60Hz"
        );
        let card = crate::opengrok::UserFormSpec::parse(
            &serde_json::json!({
                "entryId": "e1",
                "formRequest": {
                    "title": "Login",
                    "fields": [{"id": "p", "label": "Password", "type": "password", "required": true}]
                }
            }),
            None,
        )
        .unwrap();
        let with_form = vec![ChatPart::Text("hi".into()), ChatPart::UserForm(card)];
        let form_sig = stream_part_sig(&with_form);
        assert_ne!(sig, form_sig);
        assert!(
            stream_paint_due(Some(t0), t0, sig, form_sig),
            "a user-form card paints immediately"
        );
    }

    #[test]
    fn replying_to_your_own_message_is_told_apart_from_replying_to_the_bot() {
        let mine = message("m1", true, "remind me at five");
        let reply = replying_to(message("m2", true, "make that six"), &mine);
        let sent = agui_messages(&[mine, reply]);
        assert_eq!(
            sent[1].content,
            "[Replying to their own earlier message: \"remind me at five\"]\n\nmake that six"
        );
        assert!(sent[1].reply_to.as_ref().expect("a quote").is_me);
    }

    /// A reply to a long answer names it, it does not replay it.
    #[test]
    fn a_long_quote_is_clipped() {
        let bot = message("m1", false, &"x".repeat(REPLY_QUOTE_CHARS + 50));
        let reply = replying_to(message("m2", true, "go on"), &bot);
        let sent = agui_messages(&[bot, reply]);
        let quote = sent[1].reply_to.as_ref().expect("a quote");
        assert_eq!(quote.preview.chars().count(), REPLY_QUOTE_CHARS + 1);
        assert!(quote.preview.ends_with('…'));
    }

    /// A message can be deleted after it was answered; the preview saved with the reply is what
    /// is left of it.
    #[test]
    fn a_quote_whose_message_is_gone_falls_back_to_the_saved_preview() {
        let mut reply = message("m2", true, "why?");
        reply.reply_to_id = Some("deleted".to_string());
        reply.reply_preview = Some("The build is green.".to_string());
        let sent = agui_messages(&[reply]);
        assert_eq!(
            sent[0].content,
            "[Replying to your earlier message: \"The build is green.\"]\n\nwhy?"
        );
    }

    /// The app's own words about a turn are not a turn: sending them back would have the model
    /// answering a line nobody said.
    #[test]
    fn the_apps_status_lines_are_never_sent_back_as_the_coworkers_words() {
        let thread = vec![
            message("m1", true, "hi"),
            message("m2", false, EMPTY_TURN_NOTE),
            message("m3", true, "still there?"),
            message("m4", false, "OpenGrok: the model returned no text"),
            message("m5", false, "[took a screenshot of my screen]"),
        ];
        let sent = agui_messages(&thread);
        let kept: Vec<&str> = sent.iter().map(|m| m.content.as_str()).collect();
        assert_eq!(
            kept,
            vec!["hi", "still there?", "[took a screenshot of my screen]"]
        );
    }

    /// A user-form card's typed values — especially a password — must never become the
    /// next turn's AG-UI `content`. The card lives in `parts`; `content` is the prose.
    #[test]
    fn user_form_values_never_enter_agui_content() {
        let spec = crate::opengrok::UserFormSpec::parse(
            &serde_json::json!({
                "entryId": "entry-pw",
                "formRequest": {
                    "title": "Google password",
                    "fields": [{
                        "id": "password",
                        "label": "Password",
                        "type": "password",
                        "required": true,
                        "value": "s3cret-pass"
                    }]
                }
            }),
            None,
        )
        .expect("a card");
        assert!(spec.fields[0].prefill.is_none());
        let mut bot = message("m1", false, "I'll sign you in.");
        bot.parts = vec![ChatPart::UserForm(spec)];
        let sent = agui_messages(&[bot]);
        assert_eq!(sent.len(), 1);
        assert_eq!(sent[0].content, "I'll sign you in.");
        assert!(
            !sent[0].content.contains("s3cret-pass"),
            "password leaked into AguiMessage.content: {}",
            sent[0].content
        );
        let dump = format!("{sent:?}");
        assert!(
            !dump.contains("s3cret-pass"),
            "password in Debug of messages: {dump}"
        );
        let mut values = crate::opengrok::UserFormValues::default();
        values.by_id.insert("password".into(), "s3cret-pass".into());
        let body = crate::opengrok::submit_request_body("e_form", "cw_1", &values, false);
        assert_eq!(body["values"]["password"], "s3cret-pass");
        assert_eq!(body["entryId"], "e_form");
        assert_ne!(body["entryId"], "mock-form-1");
        assert!(
            !sent[0].content.contains("s3cret-pass"),
            "submit values must not leak into AguiMessage.content"
        );
        let official = crate::opengrok::UserFormSpec::from_custom_event(&serde_json::json!({
            "type": "CUSTOM",
            "name": "run-awaiting-approval",
            "callId": "mock-form-1",
            "reason": "user-form",
            "entryId": "e_form",
            "arguments": {
                "title": "Google password",
                "fields": [{
                    "id": "password",
                    "label": "Password",
                    "type": "password",
                    "required": true
                }]
            }
        }))
        .expect("d12fffc card");
        assert_eq!(official.entry_id, "e_form");
        assert_eq!(official.call_id, "mock-form-1");
        let rest = crate::opengrok::submit_request_body(&official.entry_id, "cw_1", &values, false);
        assert_eq!(rest["entryId"], official.entry_id);
        assert_ne!(rest["entryId"], official.call_id);
        assert_eq!(
            crate::opengrok::user_form_action_from_http(404, &serde_json::Value::Null),
            crate::opengrok::UserFormActionReply::MissingRoute
        );
    }

    #[test]
    fn paint_settle_collapses_the_same_call_id_twin() {
        let call_twin = crate::opengrok::UserFormSpec::from_tool_args(
            &serde_json::json!({
                "formRequest": {
                    "title": "Google account",
                    "fields": [
                        {"id": "email", "label": "Email", "type": "email", "required": true},
                        {"id": "password", "label": "Password", "type": "password", "required": true}
                    ]
                }
            }),
            "call-9",
        )
        .unwrap();
        let entry = crate::opengrok::UserFormSpec::from_custom_event(&serde_json::json!({
            "type": "CUSTOM",
            "name": "run-awaiting-approval",
            "callId": "call-9",
            "entryId": "e_form",
            "reason": "user-form",
            "arguments": {
                "title": "Google account",
                "fields": [
                    {"id": "email", "label": "Email", "type": "email", "required": true},
                    {"id": "password", "label": "Password", "type": "password", "required": true}
                ]
            }
        }))
        .unwrap();
        let otp = crate::opengrok::UserFormSpec::from_custom_event(&serde_json::json!({
            "type": "CUSTOM",
            "name": "run-awaiting-approval",
            "callId": "call-otp",
            "entryId": "e_otp",
            "reason": "user-form",
            "arguments": {
                "title": "Enter the code",
                "fields": [{"id": "otp", "label": "Code", "type": "otp", "required": true}]
            }
        }))
        .unwrap();
        let mut bot = message("m1", false, "");
        bot.parts = vec![
            ChatPart::UserForm(call_twin),
            ChatPart::UserForm(entry),
            ChatPart::UserForm(otp),
        ];
        let mut state = AppState::new();
        state.conversations.push(thread("cw_1", vec![bot]));
        state.active_conversation_id = Some("cw_1".into());

        state.paint_user_form_resolution("e_form", FormResolution::Submitted);

        let open = state.open_user_forms();
        assert!(
            open.iter().all(|spec| spec.call_id != "call-9"),
            "call twin must not stay unresolved: {open:?}"
        );
        assert_eq!(open.len(), 1);
        assert_eq!(open[0].entry_id, "e_otp");

        let fresh = crate::opengrok::UserFormSpec::from_tool_args(
            &serde_json::json!({
                "formRequest": {
                    "title": "Google account",
                    "fields": [
                        {"id": "email", "label": "Email", "type": "email", "required": true}
                    ]
                }
            }),
            "call-9",
        )
        .unwrap();
        let grafted = state.graft_user_forms(vec![ChatPart::UserForm(fresh)]);
        match grafted.as_slice() {
            [ChatPart::UserForm(spec)] => {
                assert_eq!(spec.effective_resolution(), Some(FormResolution::Submitted));
                assert!(!spec.is_unresolved());
            }
            other => panic!("expected grafted settle, got {other:?}"),
        }
    }

    /// A row of Settings → Logins, as the vault lists it.
    fn saved_login(
        id: &str,
        origin: &str,
        username: &str,
        kind: &str,
    ) -> crate::site_login::SiteLoginRecord {
        crate::site_login::SiteLoginRecord {
            id: id.into(),
            origin: origin.into(),
            username: username.into(),
            label: String::new(),
            kind: kind.into(),
            notes: String::new(),
            last_used_at_ms: None,
            created_at: "2026-09-30T10:00:00+00:00".into(),
            updated_at: "2026-09-30T10:00:00+00:00".into(),
        }
    }

    /// A card the Bot raised on Google's sign-in page, with the fields given.
    fn google_card(entry_id: &str, fields: serde_json::Value) -> crate::opengrok::UserFormSpec {
        crate::opengrok::UserFormSpec::parse(
            &json!({
                "entryId": entry_id,
                "formRequest": {
                    "title": "Google sign-in",
                    "domain": "accounts.google.com",
                    "liveHost": "accounts.google.com",
                    "fields": fields
                }
            }),
            None,
        )
        .expect("form")
    }

    /// The ids of the saved logins a card offers, in the order it lists them.
    fn offered(state: &AppState, spec: &crate::opengrok::UserFormSpec) -> Vec<String> {
        state
            .saved_logins_for_form(spec)
            .into_iter()
            .map(|row| row.id)
            .collect()
    }

    /// The owner's report: Google asked for the email alone, the Bot raised a card with one
    /// "Email or phone" field, and the card offered nothing, although a login for google.com
    /// was saved. A card had to hold a name and a password to take a login, and neither page of
    /// a two-step sign-in holds both. Each page now offers the site's password logins, found
    /// from accounts.google.com under the google.com they were saved as; another site's logins
    /// and a passkey are not offered, and a sign-up still takes nothing.
    #[test]
    fn both_pages_of_a_two_step_sign_in_offer_the_sites_saved_logins() {
        let mut state = AppState::new();
        state.site_logins = vec![
            saved_login("sl_fb", "facebook.com", "ada@example.com", "password"),
            saved_login("sl_ada", "google.com", "ada@example.com", "password"),
            saved_login("sl_key", "google.com", "ada@example.com", "passkey"),
        ];
        state.site_logins_ready = true;
        let email = google_card(
            "e_email",
            json!([{"id": "email", "label": "Email or phone", "type": "email", "required": true}]),
        );
        assert_eq!(offered(&state, &email), ["sl_ada"]);
        let password = google_card(
            "e_password",
            json!([{"id": "password", "label": "Enter your password", "type": "password", "required": true}]),
        );
        assert_eq!(offered(&state, &password), ["sl_ada"]);
        let sign_up = google_card(
            "e_sign_up",
            json!([
                {"id": "email", "label": "Email", "type": "email", "required": true},
                {"id": "password", "label": "Password", "type": "password", "required": true},
                {"id": "confirm", "label": "Confirm password", "type": "password", "required": true}
            ]),
        );
        assert!(offered(&state, &sign_up).is_empty());
    }

    /// The password page does not ask who is signing in; the name page before it did. Once a
    /// saved login's name has gone into the name page, the password page in the same thread
    /// offers that login first, so the person is not left to remember which account they chose.
    /// Another thread's sign-in to the same site is its own, and a name typed by hand on a later
    /// name page is not the earlier pick's, so that pick stops leading. Each page is sent its
    /// half of the login and nothing else.
    #[test]
    fn the_password_page_offers_first_the_login_picked_on_the_name_page() {
        let mut state = AppState::new();
        state.site_logins = vec![
            saved_login("sl_ada", "google.com", "ada@example.com", "password"),
            saved_login("sl_bea", "google.com", "bea@example.com", "password"),
        ];
        state.site_logins_ready = true;
        let email_field =
            json!([{"id": "email", "label": "Email or phone", "type": "email", "required": true}]);
        let password_field = json!([
            {"id": "password", "label": "Enter your password", "type": "password", "required": true}
        ]);
        let email = google_card("e_email", email_field.clone());
        let password = google_card("e_password", password_field.clone());
        let elsewhere = google_card("e_elsewhere", password_field);
        let mut sign_in = message("m1", false, "");
        sign_in.parts = vec![
            ChatPart::UserForm(email),
            ChatPart::UserForm(password.clone()),
        ];
        let mut other = message("m2", false, "");
        other.parts = vec![ChatPart::UserForm(elsewhere.clone())];
        state.conversations.push(thread("cw_1", vec![sign_in]));
        state.conversations.push(thread("cw_2", vec![other]));
        assert_eq!(
            offered(&state, &password),
            ["sl_ada", "sl_bea"],
            "nothing picked yet: the vault's own order"
        );

        // Touch ID passed for bea on the name page; Continue sends her name, and only it.
        state.saved_login_use.insert(
            "e_email".into(),
            crate::site_login::SavedLoginUse::NameReady {
                login_id: "sl_bea".into(),
                username: "bea@example.com".into(),
            },
        );
        let mut sent = crate::opengrok::UserFormValues::default();
        assert!(state.fold_held_saved_login("e_email", &mut sent));
        assert_eq!(
            sent.by_id,
            std::collections::HashMap::from([("email".to_string(), "bea@example.com".to_string())])
        );
        assert_eq!(
            state
                .saved_login_use
                .get("e_email")
                .and_then(crate::site_login::SavedLoginUse::filling_id),
            Some("sl_bea"),
            "sent as a saved login, which keeps it off a shared computer and stamps its use"
        );
        assert_eq!(offered(&state, &password), ["sl_bea", "sl_ada"]);
        assert_eq!(
            offered(&state, &elsewhere),
            ["sl_ada", "sl_bea"],
            "another thread's sign-in"
        );

        // Her password, picked on the password page, is sent alone.
        state.saved_login_use.insert(
            "e_password".into(),
            crate::site_login::SavedLoginUse::Ready {
                login_id: "sl_bea".into(),
                username: "bea@example.com".into(),
                password: "s3cret-pass".into(),
            },
        );
        let mut sent = crate::opengrok::UserFormValues::default();
        assert!(state.fold_held_saved_login("e_password", &mut sent));
        assert_eq!(
            sent.by_id,
            std::collections::HashMap::from([("password".to_string(), "s3cret-pass".to_string())])
        );

        // Signing in again later, with a name typed by hand: bea no longer leads.
        let mut again = message("m3", false, "");
        again.parts = vec![ChatPart::UserForm(google_card("e_email_2", email_field))];
        state.conversations[0].messages.push(again);
        let mut typed = crate::opengrok::UserFormValues::default();
        typed.by_id.insert("email".into(), "ada@example.com".into());
        assert!(state.fold_held_saved_login("e_email_2", &mut typed));
        assert_eq!(offered(&state, &password), ["sl_ada", "sl_bea"]);
    }

    /// A driver finds each page's saved logins where a person does, by the ids the one-page
    /// login card uses: a `user-form-use-saved-{card}-{login}` row per login on the name page
    /// and on the password page, the password page's in the order the card lists them. A
    /// click on one is a pick of that login on that card.
    #[cfg(feature = "agent")]
    #[test]
    fn a_driver_picks_a_saved_login_on_either_page_of_a_two_step_sign_in() {
        use crate::agent::{Command, NativeChatHost};
        use gpui_agent::prelude::{AgentHost, Op};
        let mut state = AppState::new();
        state.auth_status = super::AuthStatus::SignedIn;
        state.account = serde_json::from_value(json!({
            "id": "acct_1",
            "email": "ada@example.com"
        }))
        .ok();
        state.coworkers.push(bob());
        state.site_logins = vec![
            saved_login("sl_ada", "google.com", "ada@example.com", "password"),
            saved_login("sl_bea", "google.com", "bea@example.com", "password"),
        ];
        state.site_logins_ready = true;
        let mut sign_in = message("m1", false, "");
        sign_in.parts = vec![
            ChatPart::UserForm(google_card(
                "e_email",
                json!([{"id": "email", "label": "Email or phone", "type": "email", "required": true}]),
            )),
            ChatPart::UserForm(google_card(
                "e_password",
                json!([{"id": "password", "label": "Enter your password", "type": "password", "required": true}]),
            )),
        ];
        state.conversations.push(thread("cw_1", vec![sign_in]));
        state.active_conversation_id = Some("cw_1".into());
        state
            .name_page_picks
            .insert(("cw_1".into(), "google.com".into()), "sl_bea".into());
        let mut host = NativeChatHost::from_app(&state);
        let tree = host.snapshot();
        let rows = |card: &str| -> Vec<String> {
            tree.find(&format!("user-form-{card}"))
                .map(|node| {
                    node.children
                        .iter()
                        .map(|child| child.id.clone())
                        .filter(|id| id.starts_with("user-form-use-saved-"))
                        .collect()
                })
                .unwrap_or_default()
        };
        assert_eq!(
            rows("e_email"),
            [
                "user-form-use-saved-e_email-sl_ada",
                "user-form-use-saved-e_email-sl_bea"
            ]
        );
        assert_eq!(
            rows("e_password"),
            [
                "user-form-use-saved-e_password-sl_bea",
                "user-form-use-saved-e_password-sl_ada"
            ]
        );
        host.dispatch(&Op::click("user-form-use-saved-e_password-sl_bea"))
            .unwrap();
        assert!(matches!(
            host.take_command(),
            Some(Command::UserFormUseSaved { card_key, login_id })
                if card_key == "e_password" && login_id == "sl_bea"
        ));
    }

