    /// All of these are the app talking, whether painted now or read back from an older build's
    /// rows.
    #[test]
    fn a_status_line_is_told_from_something_the_coworker_said() {
        assert!(is_status_line(EMPTY_TURN_NOTE));
        assert!(is_status_line(STOPPED_TURN_NOTE));
        assert!(is_status_line(STOP_UNSENT_NOTE));
        assert!(is_status_line("OpenGrok: the run failed"));
        assert!(!is_status_line("OpenGrok is a server."));
        assert!(!is_status_line("[took a screenshot of my screen]"));
        assert!(is_tool_standin("[took a screenshot of my screen]"));
        assert!(!is_tool_standin("The build is green."));
    }

    // The patch reconciliation, apart from the app: what the roster holds for a coworker once
    // the server has answered.
    use super::{Coworker, CoworkerPatch, CoworkerSource, apply_patch, settle_patch};

    fn bob() -> Coworker {
        Coworker {
            id: "cw_1".to_string(),
            name: "Bob".to_string(),
            model: "xai/grok-4.6@sub".to_string(),
            role: Some("Research".to_string()),
            title: Some("Analyst".to_string()),
            avatar_shape: Some("circle".to_string()),
            avatar_color: Some("blue".to_string()),
            updated_at_ms: 17,
            hidden_from_sidebar: false,
            box_id: None,
            effort: Some("high".to_string()),
            visibility: Some("private".to_string()),
            source: CoworkerSource::NotKept,
        }
    }

    /// The roster took the new name before the server was asked. The server answered without a
    /// word about the name — which is what a route that quietly drops the field does — so the
    /// new name was never stored, and the roster must not go on showing it.
    #[test]
    fn a_rename_the_server_never_echoed_does_not_stay_on_the_roster() {
        let before = bob();
        let patch = CoworkerPatch {
            name: Some("Roberta".to_string()),
            title: Some("Analyst".to_string()),
            role: Some("Research".to_string()),
            ..Default::default()
        };
        let mut roster = before.clone();
        apply_patch(&mut roster, &patch);
        assert_eq!(roster.name, "Roberta", "the click is answered at once");

        let echo = Coworker {
            name: String::new(),
            ..before.clone()
        };
        settle_patch(&mut roster, &patch, Some(&echo), &before);
        assert_eq!(
            roster.name, "Bob",
            "an answer that says nothing about the name leaves the stored name standing"
        );
    }

    /// The same, for a server that answers with the name it kept rather than with no name at
    /// all: the echo is the truth even when it is the old value.
    #[test]
    fn the_servers_echo_wins_over_what_the_app_sent() {
        let before = bob();
        let patch = CoworkerPatch {
            name: Some("Roberta".to_string()),
            ..Default::default()
        };
        let mut roster = before.clone();
        apply_patch(&mut roster, &patch);
        settle_patch(&mut roster, &patch, Some(&before), &before);
        assert_eq!(roster.name, "Bob");
    }

    /// Nothing was stored, so nothing the patch asked for may be left behind — including the
    /// fields the app had already written into the roster to look quick.
    #[test]
    fn a_refused_patch_leaves_the_roster_as_it_was() {
        let before = bob();
        let patch = CoworkerPatch {
            name: Some("Roberta".to_string()),
            title: Some(String::new()),
            role: Some("Marketing".to_string()),
            ..Default::default()
        };
        let mut roster = before.clone();
        apply_patch(&mut roster, &patch);
        assert_eq!(roster.title, None, "the click is answered at once");

        settle_patch(&mut roster, &patch, None, &before);
        assert_eq!(roster, before);
    }

    /// A field the patch never mentioned is none of the reconciliation's business, which is
    /// what keeps a server that answers with half a coworker from blanking the other half.
    #[test]
    fn a_field_outside_the_patch_is_left_alone() {
        let before = bob();
        let patch = CoworkerPatch {
            model: Some("xai/grok-4.7@sub".to_string()),
            ..Default::default()
        };
        let mut roster = before.clone();
        apply_patch(&mut roster, &patch);
        let echo = Coworker {
            id: "cw_1".to_string(),
            name: String::new(),
            model: "xai/grok-4.7@sub".to_string(),
            role: None,
            title: None,
            avatar_shape: None,
            avatar_color: None,
            updated_at_ms: 0,
            hidden_from_sidebar: false,
            box_id: None,
            effort: None,
            visibility: None,
            source: CoworkerSource::NotKept,
        };
        settle_patch(&mut roster, &patch, Some(&echo), &before);
        assert_eq!(roster.model, "xai/grok-4.7@sub");
        assert_eq!(roster.name, "Bob", "a partial answer blanks nothing else");
        assert_eq!(roster.title.as_deref(), Some("Analyst"));
        assert_eq!(roster.updated_at_ms, 17);
        assert_eq!(roster.effort.as_deref(), Some("high"));
    }

    /// Clearing is the one thing an answer with nothing in it confirms: the avatar the person
    /// reset stays reset rather than coming back on the next frame.
    #[test]
    fn a_cleared_field_stays_cleared_when_the_server_echoes_nothing() {
        let before = bob();
        let patch = CoworkerPatch {
            avatar_shape: Some(String::new()),
            avatar_color: Some(String::new()),
            ..Default::default()
        };
        let mut roster = before.clone();
        apply_patch(&mut roster, &patch);
        let echo = Coworker {
            avatar_shape: None,
            avatar_color: None,
            ..before.clone()
        };
        settle_patch(&mut roster, &patch, Some(&echo), &before);
        assert_eq!(roster.avatar_shape, None);
        assert_eq!(roster.avatar_color, None);
    }

    /// An effort is the server's once it answers: the word it echoed, even when that is not the
    /// word sent (a server that dropped it echoes none, and the settings go back to saying so),
    /// and the word from before when it refused.
    #[test]
    fn an_effort_settles_on_the_servers_word() {
        let before = bob();
        let patch = CoworkerPatch {
            effort: Some("max".to_string()),
            ..Default::default()
        };
        let mut roster = before.clone();
        apply_patch(&mut roster, &patch);
        assert_eq!(roster.effort(), "max", "the pick is answered at once");

        let mut stored = roster.clone();
        let echo = Coworker {
            effort: Some("max".to_string()),
            ..before.clone()
        };
        settle_patch(&mut stored, &patch, Some(&echo), &before);
        assert_eq!(stored.effort(), "max");

        let mut dropped = roster.clone();
        let echo = Coworker {
            effort: None,
            ..before.clone()
        };
        settle_patch(&mut dropped, &patch, Some(&echo), &before);
        assert_eq!(dropped.effort, None, "the server said it keeps none");

        settle_patch(&mut roster, &patch, None, &before);
        assert_eq!(roster, before);
    }

    /// A change in the model picker is the roster's the moment it is made, door, model and
    /// effort together, so both of the picker's places follow the click at once; the server's
    /// echo then has the last word on each, and a refusal puts all three back.
    #[test]
    fn a_pick_is_the_rosters_at_once_and_the_servers_word_settles_it() {
        let before = bob();
        let patch = CoworkerPatch {
            source: Some(InferenceKind::LocalProxy),
            model: Some("gpt-6-luna--fast".to_string()),
            effort: Some("max".to_string()),
            ..Default::default()
        };
        let mut roster = before.clone();
        apply_patch(&mut roster, &patch);
        assert_eq!(
            (
                &roster.source,
                roster.model.as_str(),
                roster.effort.as_deref()
            ),
            (
                &CoworkerSource::Kind(InferenceKind::LocalProxy),
                "gpt-6-luna--fast",
                Some("max")
            )
        );
        let echo = Coworker {
            source: CoworkerSource::AccountDefault,
            model: "gpt-6-luna--fast".to_string(),
            effort: Some("max".to_string()),
            ..before.clone()
        };
        let mut kept = roster.clone();
        settle_patch(&mut kept, &patch, Some(&echo), &before);
        assert_eq!(
            kept.source,
            CoworkerSource::AccountDefault,
            "the server's word on the door, even where it is not the one sent"
        );
        settle_patch(&mut roster, &patch, None, &before);
        assert_eq!(roster, before, "refused: all three go back");
    }

    // ---- A turn survives looking away -------------------------------------------------------

    fn at(mut message: Message, at_ms: u64) -> Message {
        message.sent_at = SystemTime::UNIX_EPOCH + Duration::from_millis(at_ms);
        message
    }

    /// A reply already on disk, which is to say a run this thread can account for.
    fn from_run(id: &str, content: &str, run_id: &str, at_ms: u64) -> Message {
        let mut message = at(message(id, false, content), at_ms);
        message.run_id = Some(run_id.to_string());
        message
    }

    fn thread(id: &str, messages: Vec<Message>) -> Conversation {
        Conversation {
            id: id.to_string(),
            title: id.to_string(),
            created_at: String::new(),
            updated_at: String::new(),
            messages,
            unread_count: 0,
            origin: None,
        }
    }

    fn ids(messages: &[Message]) -> Vec<&str> {
        messages.iter().map(|message| message.id.as_str()).collect()
    }

    /// A row as the local database hands it back.
    fn row(id: &str, role: &str, content: &str) -> ChatMessage {
        ChatMessage {
            id: id.to_string(),
            session_id: "cw_1".to_string(),
            role: role.to_string(),
            content: content.to_string(),
            created_at: "2026-09-17 10:00:00".to_string(),
            model: None,
            provider: None,
            reply_to_id: None,
            reply_preview: None,
            reply_is_me: None,
            run_id: None,
            deleted_at: None,
            finished_at: None,
            run_timing: None,
            inference_source: None,
            parts: Vec::new(),
        }
    }

    fn in_flight() -> LiveTurn {
        LiveTurn {
            run_id: "run_1".to_string(),
            message_id: "m_live".to_string(),
            persisting: false,
        }
    }

    /// One turn's frames as the server kept them: some words, a tool that took a picture of the
    /// box's screen, more words. The picture arrives base64 inside the frame, because that is
    /// how a frame carries one, and decoding it is part of what the two paths have to agree on.
    fn turn_frames() -> Vec<serde_json::Value> {
        use base64::Engine as _;
        let png = base64::engine::general_purpose::STANDARD.encode(b"png-one");
        vec![
            serde_json::json!({ "type": "RUN_STARTED", "threadId": "cw_1", "runId": "run_1" }),
            serde_json::json!({
                "type": "TEXT_MESSAGE_CONTENT", "messageId": "m1", "delta": "Opening YouTube "
            }),
            serde_json::json!({
                "type": "TEXT_MESSAGE_CONTENT", "messageId": "m1", "delta": "on my box."
            }),
            serde_json::json!({
                "type": "TOOL_CALL_START", "toolCallId": "c1", "toolCallName": "computer"
            }),
            serde_json::json!({ "type": "TOOL_CALL_END", "toolCallId": "c1" }),
            serde_json::json!({
                "type": "TOOL_CALL_RESULT",
                "toolCallId": "c1",
                "content": "screenshot of the 1280x800 screen attached",
                "image": { "mime": "image/png", "base64": png, "width": 1280, "height": 800 }
            }),
            serde_json::json!({
                "type": "TEXT_MESSAGE_CONTENT", "messageId": "m2", "delta": "It is open."
            }),
            serde_json::json!({ "type": "RUN_FINISHED", "runId": "run_1" }),
        ]
    }

    fn thread_run(
        run_id: &str,
        status: &str,
        started_at_ms: i64,
        events: &[serde_json::Value],
    ) -> ThreadRun {
        ThreadRun {
            run_id: run_id.to_string(),
            status: status.to_string(),
            started_at_ms,
            updated_at_ms: started_at_ms,
            failure: None,
            events: events.to_vec(),
        }
    }

    /// The turn as the stream painted it: every frame pushed as it arrived, the feed repainted
    /// from a snapshot each time, and the closing the end of the stream gives it.
    fn watched_live(events: &[serde_json::Value]) -> (String, Vec<ChatPart>) {
        let mut assembler = TurnAssembler::default();
        for event in events {
            assembler.push_event(event);
            let _ = assembler.snapshot();
        }
        assembler.finish();
        assembler.snapshot()
    }

    /// The bug the person reported, in the place it happens: switching bots mid-turn reloaded
    /// the thread from a database that does not yet have the reply, and the bubble and every
    /// picture under it went with it.
    #[test]
    fn a_thread_with_a_turn_in_flight_is_not_reloaded_out_from_under_it() {
        let mut conversation = thread(
            "cw_1",
            vec![
                at(message("m_ask", true, "open youtube"), 1_000),
                at(message("m_live", false, "Opening YouTube "), 2_000),
            ],
        );
        // What SQLite has: the person's message and nothing else. The reply is not written down
        // until the turn ends, so the persisted set is a subset of what is on screen.
        let rows = vec![row("db_ask", "user", "open youtube")];

        assert!(
            !apply_reload(&mut conversation, Some(&in_flight()), rows.clone()),
            "a thread in the middle of a turn refuses the rows"
        );
        assert_eq!(ids(&conversation.messages), vec!["m_ask", "m_live"]);
        assert_eq!(
            conversation.messages[1].content, "Opening YouTube ",
            "the bubble being filled in is still the one being filled in"
        );

        assert!(
            apply_reload(&mut conversation, None, rows),
            "with no turn in flight the rows are taken, which is what every other reload is"
        );
        assert_eq!(ids(&conversation.messages), vec!["db_ask"]);
    }

    #[test]
    fn a_turn_ending_belongs_to_the_run_that_still_holds_the_thread() {
        assert_eq!(turn_ending(Some(&in_flight()), "run_1"), TurnEnding::Ours);
    }

    #[test]
    fn a_turn_ending_stands_down_when_another_run_holds_the_thread_or_the_reply_is_being_saved() {
        let later = LiveTurn {
            run_id: "run_2".to_string(),
            ..in_flight()
        };
        assert_eq!(turn_ending(Some(&later), "run_1"), TurnEnding::Superseded);
        let saving = LiveTurn {
            persisting: true,
            ..in_flight()
        };
        assert_eq!(turn_ending(Some(&saving), "run_1"), TurnEnding::Superseded);
    }

    /// The thread was let go while this run's stream was still open — the person pressed stop,
    /// or (until 21 Sep 2026) a resync read the server's 404 for a run it had not recorded yet
    /// as "never started". Nobody else will end the line the run started, so its ending still
    /// has to clear it, or the thread says "working" until the app is restarted.
    #[test]
    fn a_turn_let_go_while_its_stream_was_open_still_ends_its_own_line() {
        assert_eq!(turn_ending(None, "run_1"), TurnEnding::Orphaned);
    }

    fn a_form() -> UiSpec {
        UiSpec::Form(FormSpec {
            title: Some("QA collapse remasure".into()),
            prompt: Some("Enter a label.".into()),
            fields: vec![FormField {
                id: "label".into(),
                label: "Label".into(),
                options: vec![],
            }],
            submit: "Submit".into(),
        })
    }

    /// A turn that answered with a form and no words was saved as its stand-in line alone —
    /// `saved_parts` dropped every `Ui` part — so the thread showed "[used form]" the moment it
    /// was read back from the database: on the next visit, and forever after a restart.
    #[test]
    fn a_wordless_form_turn_is_saved_with_its_form_and_comes_back_as_one() {
        let saved = saved_parts(&[ChatPart::Ui(a_form())]);
        assert_eq!(saved.len(), 1, "the form is written down: {saved:?}");
        assert!(matches!(saved[0], MessagePart::Ui { .. }), "{saved:?}");
        assert_eq!(
            restored_parts("[showed you a form]", saved),
            vec![ChatPart::Ui(a_form())]
        );
    }

    /// The frames of the run behind the Vamos "hi" of 21 Sep 2026: a `form` tool call, its
    /// arguments in pieces, no words. Read back off the server it has to be a form again, and
    /// the line it leaves for the model has to say so.
    #[test]
    fn a_form_only_run_replays_as_a_form_with_a_line_that_says_so() {
        let events = vec![
            serde_json::json!({"type":"RUN_STARTED","runId":"run_f","threadId":"cw_1"}),
            serde_json::json!({"type":"TOOL_CALL_START","toolCallId":"call_1","toolCallName":"form"}),
            serde_json::json!({"type":"TOOL_CALL_ARGS","toolCallId":"call_1","delta":"{\"title\":\"QA collapse remasure\",\"prompt\":\"Enter a label.\","}),
            serde_json::json!({"type":"TOOL_CALL_ARGS","toolCallId":"call_1","delta":"\"submit\":\"Submit\",\"fields\":[{\"id\":\"label\",\"label\":\"Label\",\"options\":[]}] }"}),
            serde_json::json!({"type":"TOOL_CALL_END","toolCallId":"call_1"}),
            serde_json::json!({"type":"TOOL_CALL_RESULT","toolCallId":"call_1","content":"rendered"}),
            serde_json::json!({"type":"RUN_FINISHED","runId":"run_f"}),
        ];
        let (plain, parts) = reply_from_replay(&events, "finished");
        assert_eq!(parts, vec![ChatPart::Ui(a_form())]);
        assert_eq!(
            replayed_ending(&events, "finished", None, &plain).as_deref(),
            Some("[showed you a form]")
        );
    }

    /// "The last one, if it isn't mine" was the whole of the old rule, and everything that
    /// touches the list breaks it — after which the run fills in a bubble belonging to something
    /// else, which reads exactly like the run having stopped.
    #[test]
    fn a_run_finds_its_bubble_after_the_thread_moved_underneath_it() {
        let mut conversations = vec![
            thread("cw_other", vec![message("m_live", false, "another bot")]),
            thread(
                "cw_1",
                vec![
                    at(message("m_ask", true, "open youtube"), 1_000),
                    at(message("m_live", false, ""), 2_000),
                ],
            ),
        ];
        // A permission card, a reload, a recovered older reply: each of these makes some other
        // row the last one.
        conversations[1]
            .messages
            .push(at(message("m_card", false, "may I?"), 3_000));
        conversations[1]
            .messages
            .insert(0, at(message("m_older", false, "yesterday"), 100));

        let found = streaming_message_mut(&mut conversations, "cw_1", "m_live")
            .expect("the bubble the turn was given");
        found.content = "Opening YouTube on my box.".to_string();
        assert_eq!(
            conversations[1].messages[2].content, "Opening YouTube on my box.",
            "the words went where the run's own bubble had drifted to"
        );
        assert_eq!(
            conversations[1].messages[3].content, "may I?",
            "and nowhere near the row that happens to be last"
        );

        assert_eq!(
            conversations[0].messages[0].content, "another bot",
            "and not into the thread the person switched to, which holds a row under the very \
             same id — the thread is looked up first, and only then the row"
        );

        conversations[1].messages.retain(|m| m.id != "m_live");
        assert!(
            streaming_message_mut(&mut conversations, "cw_1", "m_live").is_none(),
            "a bubble that is genuinely gone is written nowhere at all"
        );
    }

    /// The two paths must not drift. A turn watched live and the same turn read back off the
    /// server have to come to the same bubbles and the same pictures, or "where was I?" and
    /// "what happened?" are two different answers and the person has to pick one to believe.
    #[test]
    fn a_turn_read_back_off_the_server_comes_to_what_the_same_turn_watched_live_came_to() {
        let events = turn_frames();
        let (live_plain, live_parts) = watched_live(&events);
        let (replayed_plain, replayed_parts) = reply_from_replay(&events, "finished");

        assert_eq!(replayed_plain, live_plain);
        assert_eq!(shape(&replayed_parts), shape(&live_parts));
        assert!(
            shape(&live_parts)
                .iter()
                .any(|part| part.starts_with("shot c1 1280x800")),
            "the picture is in the turn, or this proves nothing about pictures"
        );
        assert_eq!(saved_parts(&replayed_parts), saved_parts(&live_parts));
        assert!(
            saved_parts(&replayed_parts)
                .iter()
                .any(|part| matches!(part, crate::services::database::MessagePart::Screenshot { call_id, .. } if call_id == "c1")),
            "the turn-end pin is kept: {:?}",
            saved_parts(&replayed_parts)
        );
    }

    /// A turn that thought, said a word, took two steps (one of which failed) and said what it
    /// found, in the frames the server sends for it.
    fn step_frames() -> Vec<serde_json::Value> {
        vec![
            json!({"type":"RUN_STARTED","threadId":"cw_1","runId":"run_s"}),
            json!({"type":"REASONING_MESSAGE_START","messageId":"msg_run_s_1"}),
            json!({"type":"REASONING_MESSAGE_CONTENT","messageId":"msg_run_s_1","delta":"Size the archive before reading its index."}),
            json!({"type":"REASONING_MESSAGE_END","messageId":"msg_run_s_1"}),
            json!({"type":"TEXT_MESSAGE_START","messageId":"msg_run_s_2","role":"assistant"}),
            json!({"type":"TEXT_MESSAGE_CONTENT","messageId":"msg_run_s_2","delta":"Let me look."}),
            json!({"type":"TEXT_MESSAGE_END","messageId":"msg_run_s_2"}),
            json!({"type":"TOOL_CALL_START","toolCallId":"c1","toolCallName":"shell"}),
            json!({"type":"TOOL_CALL_ARGS","toolCallId":"c1","delta":"{\"command\":\"du -sh /srv/archive\"}"}),
            json!({"type":"TOOL_CALL_END","toolCallId":"c1"}),
            json!({"type":"TOOL_CALL_RESULT","toolCallId":"c1","content":"4.0G\t/srv/archive","ok":true}),
            json!({"type":"TOOL_CALL_START","toolCallId":"c2","toolCallName":"read_file"}),
            json!({"type":"TOOL_CALL_ARGS","toolCallId":"c2","delta":"{\"path\":\"/srv/archive/INDEX\"}"}),
            json!({"type":"TOOL_CALL_END","toolCallId":"c2"}),
            json!({"type":"TOOL_CALL_RESULT","toolCallId":"c2","content":"permission denied","ok":false}),
            json!({"type":"TEXT_MESSAGE_START","messageId":"msg_run_s_3","role":"assistant"}),
            json!({"type":"TEXT_MESSAGE_CONTENT","messageId":"msg_run_s_3","delta":"The archive is four gigabytes; its index would not open."}),
            json!({"type":"TEXT_MESSAGE_END","messageId":"msg_run_s_3"}),
            json!({"type":"RUN_FINISHED","threadId":"cw_1","runId":"run_s"}),
        ]
    }

    /// Steps and thoughts come to the same parts whether the turn was watched as it ran or
    /// read back off the server afterwards, and are saved the same either way.
    #[test]
    fn a_run_watched_live_and_replayed_has_the_same_steps() {
        let events = step_frames();
        let (live_plain, live_parts) = watched_live(&events);
        let (replayed_plain, replayed_parts) = reply_from_replay(&events, "finished");
        assert_eq!(replayed_parts, live_parts);
        assert_eq!(replayed_plain, live_plain);
        assert_eq!(
            shape(&live_parts),
            vec![
                "thought Size the archive before reading its index.".to_string(),
                "text Let me look.".to_string(),
                "step c1 shell {\"command\":\"du -sh /srv/archive\"} Some(\"4.0G\\t/srv/archive\") Some(true)".to_string(),
                "step c2 read_file {\"path\":\"/srv/archive/INDEX\"} Some(\"permission denied\") Some(false)".to_string(),
                "text The archive is four gigabytes; its index would not open.".to_string(),
            ]
        );
        assert_eq!(saved_parts(&replayed_parts), saved_parts(&live_parts));
    }

    /// A turn's steps and thoughts are written down with its words and come back from the
    /// database as they were, a step that never came back included.
    #[tokio::test]
    async fn steps_and_reasoning_survive_sqlite() {
        let db = test_db().await;
        db.ensure_session("s1", "Steps").await.expect("a session");
        let parts = vec![
            ChatPart::Reasoning("Size the archive first.".into()),
            ChatPart::Text("Let me look.".into()),
            ChatPart::Step(crate::opengrok::StepSpec {
                call_id: "c1".into(),
                tool: "shell".into(),
                arguments: "{\"command\":\"du -sh /srv/archive\"}".into(),
                result: Some("4.0G\t/srv/archive".into()),
                ok: Some(true),
                // Timed as it happened: nothing can time it again once the turn is over.
                took_ms: Some(1234),
            }),
            ChatPart::Step(crate::opengrok::StepSpec {
                call_id: "c2".into(),
                tool: "read_file".into(),
                arguments: "{\"path\":\"/srv/archive/INDEX\"}".into(),
                result: None,
                ok: None,
                took_ms: None,
            }),
            ChatPart::Text("The archive is four gigabytes.".into()),
        ];
        db.save_message(
            "m1",
            "s1",
            "assistant",
            "Let me look.\n\nThe archive is four gigabytes.",
            None,
            None,
            None,
            &saved_parts(&parts),
            Some("run_s"),
            false,
            SaveStamp::at(SystemTime::UNIX_EPOCH),
        )
        .await
        .expect("the turn is saved");
        let rows = db.get_messages("s1").await.expect("the thread reopens");
        assert_eq!(rows.len(), 1);
        assert_eq!(
            restored_parts(&rows[0].content, rows[0].parts.clone()),
            parts
        );
    }

    /// A part of a kind this build does not know — one a later build wrote — is left out, and
    /// the rest of the message reads as it did. A message with nothing else is its words.
    #[tokio::test]
    async fn an_unknown_part_kind_is_dropped_not_fatal() {
        let db = test_db().await;
        db.ensure_session("s1", "Steps").await.expect("a session");
        let parts = vec![
            ChatPart::Text("Before.".into()),
            ChatPart::Step(crate::opengrok::StepSpec {
                call_id: "c1".into(),
                tool: "shell".into(),
                arguments: "{\"command\":\"ls\"}".into(),
                result: Some("a.txt".into()),
                ok: Some(true),
                took_ms: None,
            }),
            ChatPart::Text("After.".into()),
        ];
        for (id, content, saved) in [
            ("m1", "Before.\n\nAfter.", saved_parts(&parts)),
            ("m2", "Just words.", Vec::new()),
        ] {
            db.save_message(
                id,
                "s1",
                "assistant",
                content,
                None,
                None,
                None,
                &saved,
                None,
                false,
                SaveStamp::at(SystemTime::UNIX_EPOCH),
            )
            .await
            .expect("saved");
        }
        for (id, ord) in [("m1", 3), ("m2", 0)] {
            sqlx::query(
                "INSERT INTO chat_message_parts (message_id, ord, kind, text) VALUES (?, ?, 'future-kind', 'drawn by a later build')",
            )
            .bind(id)
            .bind(ord)
            .execute(&db.pool())
            .await
            .expect("a later build's part");
        }
        let rows = db.get_messages("s1").await.expect("the thread still reads");
        let restored: Vec<Vec<ChatPart>> = rows
            .iter()
            .map(|row| restored_parts(&row.content, row.parts.clone()))
            .collect();
        assert_eq!(
            restored,
            vec![parts, vec![ChatPart::Text("Just words.".into())]]
        );
    }

    /// A reply's words are its words: what its tools were given and gave back, and what it
    /// thought, stay out of what is sent back as the thread's history and what is copied or
    /// read aloud from it. The words either side of a step are two things said.
    #[test]
    fn the_words_sent_back_and_copied_exclude_steps() {
        let (plain, parts) = reply_from_replay(&step_frames(), "finished");
        let mut reply = message("m2", false, &plain);
        reply.parts = parts;
        assert_eq!(
            reply.content,
            "Let me look.\n\nThe archive is four gigabytes; its index would not open."
        );
        let sent = agui_messages(&[
            message("m1", true, "how big is the archive?"),
            reply.clone(),
        ]);
        assert_eq!(sent[1].content, reply.content);
        for kept_out in [
            "du -sh",
            "4.0G",
            "INDEX",
            "permission denied",
            "Size the archive",
            "Running",
            "Reading",
        ] {
            assert!(
                !sent[1].content.contains(kept_out),
                "{kept_out:?} is not the coworker's words: {:?}",
                sent[1].content
            );
        }
        assert!(reply.has_text_body() && reply.has_visible_body());
    }

    /// A turn that called four tools whose arguments carry what the approval card keeps off
    /// it: a login recipe's password, a link's token, a key typed on the screen, and a
    /// plugin's key and the coworker id the server fills in.
    fn secret_frames() -> (Vec<serde_json::Value>, Vec<&'static str>) {
        let typed = format!("sk-live-{}", "a1".repeat(24));
        let mut frames = vec![json!({"type":"RUN_STARTED","threadId":"cw_1","runId":"run_k"})];
        for (id, tool, arguments) in [
            (
                "c1",
                "run_recipe",
                json!({"recipe": "Gmail login", "values": {"password": "hunter2-horse-battery"}}),
            ),
            (
                "c2",
                "open_url",
                json!({"url": "https://example.com/inbox?token=tok_live_q8x7#settings"}),
            ),
            ("c3", "computer", json!({"action": "type", "text": typed})),
            (
                "c4",
                "gmail.api.send",
                json!({"to": "bo@example.com", "api_key": "plugin-key-9f8e7d", "coworkerId": "cw_1"}),
            ),
        ] {
            frames.push(json!({"type":"TOOL_CALL_START","toolCallId":id,"toolCallName":tool}));
            frames.push(
                json!({"type":"TOOL_CALL_ARGS","toolCallId":id,"delta":arguments.to_string()}),
            );
            frames.push(json!({"type":"TOOL_CALL_END","toolCallId":id}));
            frames.push(
                json!({"type":"TOOL_CALL_RESULT","toolCallId":id,"content":"done","ok":true}),
            );
        }
        frames.push(json!({"type":"TEXT_MESSAGE_CONTENT","messageId":"m1","delta":"Signed in."}));
        frames.push(json!({"type":"RUN_FINISHED","threadId":"cw_1","runId":"run_k"}));
        let secrets = vec![
            "hunter2-horse-battery",
            "tok_live_q8x7",
            "token=",
            "a1a1a1a1a1a1",
            "plugin-key-9f8e7d",
            "\"cw_1\"",
        ];
        (frames, secrets)
    }

    /// What the approval card keeps off a call is kept off its step on disk and on the row the
    /// thread shows when it is opened again: the database never holds it.
    #[tokio::test]
    async fn a_steps_secrets_stay_off_the_database_and_the_opened_row() {
        let (frames, secrets) = secret_frames();
        let (plain, parts) = reply_from_replay(&frames, "finished");
        let (content, saved) = reply_to_keep(&plain, &parts).expect("a reply with words");
        let db = test_db().await;
        keep_reply(
            &db,
            "cw_1",
            "Hex",
            "m_reply",
            &content,
            &saved,
            Some("run_k"),
            false,
            SaveStamp::at(SystemTime::UNIX_EPOCH),
        )
        .await
        .expect("written down");
        let rows: Vec<(String, Option<String>)> =
            sqlx::query_as("SELECT kind, text FROM chat_message_parts ORDER BY ord")
                .fetch_all(&db.pool())
                .await
                .expect("the part rows");
        assert_eq!(rows.iter().filter(|(kind, _)| kind == "step").count(), 4);
        for (kind, text) in &rows {
            for secret in &secrets {
                assert!(
                    !text.as_deref().unwrap_or("").contains(secret),
                    "{secret:?} on disk in a {kind} row: {text:?}"
                );
            }
        }
        let restored = restored_message(db.get_messages("cw_1").await.expect("reopened").remove(0));
        for part in &restored.parts {
            if let ChatPart::Step(step) = part {
                let opened = format!(
                    "{} {} {:?}",
                    step.label(),
                    step.arguments,
                    step.shown_arguments()
                );
                for secret in &secrets {
                    assert!(!opened.contains(secret), "{secret:?} opened: {opened}");
                }
            }
        }

        // A row an earlier build wrote with the arguments as they came is held to the same
        // rules when it is read back, and a thought to the same size.
        let raw = restored_parts(
            "",
            vec![
                MessagePart::Step {
                    call_id: "c1".into(),
                    spec: json!({
                        "tool": "run_recipe",
                        "arguments": "{\"recipe\":\"Gmail login\",\"values\":{\"password\":\"hunter2-horse-battery\"}}",
                        "result": "done",
                        "ok": true
                    })
                    .to_string(),
                },
                MessagePart::Reasoning("思".repeat(3_500)),
            ],
        );
        match raw.as_slice() {
            [ChatPart::Step(step), ChatPart::Reasoning(thought)] => {
                assert_eq!(step.arguments, "{\"recipe\":\"Gmail login\"}");
                assert!(thought.text.len() < "思".repeat(3_500).len());
                assert_eq!(
                    &crate::opengrok::capped(&thought.text),
                    &thought.text,
                    "read back already kept to the cap"
                );
                assert!(thought.text.ends_with('…'));
            }
            other => panic!("expected a step and a thought, got {other:?}"),
        }
    }

    /// A run that failed after its tools ran, and said nothing before it did, comes back from
    /// the database with its steps and the line saying why it failed — and that line is still
    /// the app's, never history the coworker is sent.
    #[tokio::test]
    async fn a_wordless_failed_run_keeps_its_steps_and_its_line_after_reload() {
        let mut frames = step_frames();
        frames.retain(|frame| {
            let kind = frame["type"].as_str().unwrap_or("");
            !kind.starts_with("TEXT_MESSAGE")
                && !kind.starts_with("REASONING")
                && kind != "RUN_FINISHED"
        });
        frames.push(json!({"type":"RUN_ERROR","message":"the model gateway went away"}));
        let (plain, parts) = reply_from_replay(&frames, "failed");
        let content = replayed_ending(
            &frames,
            "failed",
            Some("the model gateway went away"),
            &plain,
        )
        .unwrap_or(plain);
        assert_eq!(content, "OpenGrok: the model gateway went away");
        let (content, saved) =
            reply_to_keep(&content, &parts).expect("the steps are worth writing down");
        let db = test_db().await;
        keep_reply(
            &db,
            "cw_1",
            "Hex",
            "m_failed",
            &content,
            &saved,
            Some("run_s"),
            false,
            SaveStamp::at(SystemTime::UNIX_EPOCH),
        )
        .await
        .expect("written down");

        let restored = restored_message(db.get_messages("cw_1").await.expect("reopened").remove(0));
        assert_eq!(restored.parts, parts, "its steps");
        assert!(
            restored
                .parts
                .iter()
                .all(|part| matches!(part, ChatPart::Step(_))),
            "the line is not saved as words: {:?}",
            restored.parts
        );
        assert!(is_status_line(&restored.content), "its red line");
        assert!(
            agui_messages(&[message("m_ask", true, "how big?"), restored])
                .iter()
                .all(|sent| sent.role == "user"),
            "the app's line is never sent back as the coworker's"
        );
    }

    /// A reply that did something and said nothing — the one a stop leaves when it lands
    /// between two tool calls — is written down with the steps it took.
    #[tokio::test]
    async fn a_reply_of_only_steps_is_written_down() {
        let parts = vec![ChatPart::Step(crate::opengrok::StepSpec {
            call_id: "c1".into(),
            tool: "shell".into(),
            arguments: "{\"command\":\"du -sh /srv/archive\"}".into(),
            result: Some("4.0G\t/srv/archive".into()),
            ok: Some(true),
            took_ms: None,
        })];
        let (content, saved) = reply_to_keep("", &parts).expect("the step is worth keeping");
        let db = test_db().await;
        keep_reply(
            &db,
            "cw_1",
            "Hex",
            "m_stopped",
            &content,
            &saved,
            Some("run_s"),
            false,
            SaveStamp::at(SystemTime::UNIX_EPOCH),
        )
        .await
        .expect("written down");
        let restored = restored_message(db.get_messages("cw_1").await.expect("reopened").remove(0));
        assert_eq!(restored.parts, parts);
        assert_eq!(restored.run_id.as_deref(), Some("run_s"));
        // A turn that never left is still never written down: it is offered again instead.
        assert!(reply_to_keep(TURN_UNREACHED_NOTE, &parts).is_none());
        assert!(reply_to_keep(TURN_SIGNED_OUT_NOTE, &parts).is_none());
        // Nor is a line of the app's own with nothing done under it.
        assert!(reply_to_keep("OpenGrok: the model gateway went away", &[]).is_none());
    }

    /// Reconciling is a diff, not a rebuild: a run the thread already has a reply for was built
    /// from these very frames, and saying it again would put the same turn in twice.
    #[test]
    fn reconciling_takes_only_the_runs_the_thread_cannot_account_for() {
        let events = turn_frames();
        let runs = vec![
            thread_run("run_1", "finished", 1_000, &events),
            thread_run("run_2", "finished", 5_000, &events),
            thread_run("run_3", "running", 9_000, &events[..3]),
        ];
        let messages = vec![
            at(message("m_ask", true, "open youtube"), 900),
            from_run("m_run1", "Opening YouTube on my box.", "run_1", 1_100),
            at(message("m_ask2", true, "again"), 4_900),
        ];

        let missing = missing_replies(&messages, &runs);
        assert_eq!(
            missing
                .iter()
                .map(|reply| reply.run_id.as_str())
                .collect::<Vec<_>>(),
            vec!["run_2", "run_3"],
            "oldest first, and run_1 is already written down"
        );
        assert!(
            !missing[0].live,
            "a run that ended is one to show and write down"
        );
        assert!(
            missing[1].live,
            "a run still going is one to re-attach to, which is how a restart mid-turn recovers"
        );
        assert!(
            shape(&missing[0].parts)
                .iter()
                .any(|part| part.starts_with("shot c1 ")),
            "a recovered turn brings its pictures back with it"
        );

        // Nothing missing is the ordinary case, and it must cost the thread nothing.
        let settled = vec![
            from_run("m_run1", "…", "run_1", 1_100),
            from_run("m_run2", "…", "run_2", 5_100),
            from_run("m_run3", "…", "run_3", 9_100),
        ];
        assert!(missing_replies(&settled, &runs).is_empty());
    }

    /// Every thread the build in the person's hands wrote has replies that cannot say which run
    /// they came out of. On one of those a finished run and an already-saved one look the same,
    /// and guessing would put the last few turns into the transcript twice.
    #[test]
    fn a_thread_that_can_name_no_run_takes_only_the_one_still_going() {
        let events = turn_frames();
        let runs = vec![
            thread_run("run_1", "finished", 1_000, &events),
            thread_run("run_2", "finished", 5_000, &events),
            thread_run("run_3", "running", 9_000, &events[..3]),
        ];
        // What an older build left behind: replies with no run id on them at all.
        let legacy = vec![
            at(message("m_ask", true, "open youtube"), 900),
            at(
                message("m_said", false, "Opening YouTube on my box."),
                1_100,
            ),
            at(message("m_ask2", true, "again"), 4_900),
            at(message("m_said2", false, "Open again."), 5_100),
        ];
        let missing = missing_replies(&legacy, &runs);
        assert_eq!(
            missing
                .iter()
                .map(|reply| reply.run_id.as_str())
                .collect::<Vec<_>>(),
            vec!["run_3"],
            "the finished runs are left alone; only the one that cannot already be here is taken"
        );

        // One reply that names its run is all it takes: from there the diff is exact again, and
        // the runs before it are behind the thread's knowledge rather than missing from it.
        let mut named = legacy.clone();
        named[3].run_id = Some("run_2".to_string());
        assert_eq!(
            missing_replies(&named, &runs)
                .iter()
                .map(|reply| reply.run_id.as_str())
                .collect::<Vec<_>>(),
            vec!["run_3"],
            "run_1 is older than a run the thread can name, so its reply is older still"
        );
    }

    /// A run can be started and die before it says anything. A blank bubble in the transcript is
    /// worse than the absence of one.
    #[test]
    fn a_run_that_said_nothing_at_all_is_not_grafted_as_an_empty_bubble() {
        let silent = vec![serde_json::json!({
            "type": "RUN_STARTED", "threadId": "cw_1", "runId": "run_9"
        })];
        let runs = vec![thread_run("run_9", "running", 1_000, &silent)];
        assert!(missing_replies(&[], &runs).is_empty());
    }

    /// The thread is in the order things were said, and a reply that arrives late is still a
    /// reply to the message that asked for it.
    #[test]
    fn a_recovered_reply_goes_back_where_it_happened_rather_than_on_the_end() {
        let mut messages = vec![
            at(message("m_ask", true, "open youtube"), 1_000),
            at(message("m_ask2", true, "and close it"), 5_000),
        ];
        let reply = RecoveredReply {
            run_id: "run_1".to_string(),
            content: "Opening.".to_string(),
            parts: vec![ChatPart::Text("Opening.".to_string())],
            live: false,
            started_at: SystemTime::UNIX_EPOCH + Duration::from_millis(2_000),
            finished_at: Some(SystemTime::UNIX_EPOCH + Duration::from_millis(8_000)),
            run_timing: None,
            reply_source: None,
            plan_failure: None,
        };

        let id = graft_reply(&mut messages, &reply);
        assert_eq!(
            ids(&messages),
            vec!["m_ask", id.as_str(), "m_ask2"],
            "after the message that asked for it, before whatever was said next"
        );
        assert_eq!(
            messages[1].run_id.as_deref(),
            Some("run_1"),
            "and it says which run it came out of, so the next reconcile leaves it alone"
        );
    }

    /// The frames a replay opens a run with for one message the person sent (opengrok-server
    /// `with_prompt_frames`): its id, `role: user`, and the words in one delta.
    fn persons_frames(id: &str, words: &str) -> Vec<serde_json::Value> {
        vec![
            json!({"type": "TEXT_MESSAGE_START", "messageId": id, "role": "user"}),
            json!({"type": "TEXT_MESSAGE_CONTENT", "messageId": id, "delta": words}),
            json!({"type": "TEXT_MESSAGE_END", "messageId": id}),
        ]
    }

    /// A finished run as the replay gives it: the person's messages its prompt held, in order,
    /// then the coworker's answer.
    fn answered_run(
        run_id: &str,
        started_at_ms: i64,
        prompt: &[(&str, &str)],
        answer: &str,
    ) -> ThreadRun {
        let mut events = vec![json!({"type": "RUN_STARTED", "runId": run_id})];
        for (id, words) in prompt {
            events.extend(persons_frames(id, words));
        }
        events.extend([
            json!({"type": "TEXT_MESSAGE_START", "messageId": format!("{run_id}-a"), "role": "assistant"}),
            json!({"type": "TEXT_MESSAGE_CONTENT", "messageId": format!("{run_id}-a"), "delta": answer}),
            json!({"type": "TEXT_MESSAGE_END", "messageId": format!("{run_id}-a")}),
            json!({"type": "RUN_FINISHED", "runId": run_id}),
        ]);
        thread_run(run_id, "finished", started_at_ms, &events)
    }

    fn by_disk_order(messages: &[Message]) -> Vec<&str> {
        let mut sorted: Vec<&Message> = messages.iter().collect();
        sorted.sort_by(|a, b| a.sent_at.cmp(&b.sent_at).then_with(|| a.id.cmp(&b.id)));
        sorted
            .into_iter()
            .map(|message| message.id.as_str())
            .collect()
    }

    /// A thread that holds the coworker's replies and not the person's messages (one rebuilt
    /// before questions were drawn, or a question row that never reached the disk) gets them
    /// back from the replay, even though no reply is missing. Each goes on its own millisecond
    /// before its reply, in the order it was said, whatever its id.
    #[test]
    fn a_thread_that_has_the_answers_gets_back_the_questions() {
        let messages = vec![
            from_run("0-reply-1", "Two meetings.", "run_1", 2_000),
            from_run("0-reply-2", "Done.", "run_2", 5_000),
        ];
        let runs = vec![
            answered_run(
                "run_1",
                1_990,
                &[("client-q1", "What is on my calendar?")],
                "Two meetings.",
            ),
            answered_run(
                "run_2",
                4_990,
                &[
                    ("client-b", "Move the first one."),
                    ("client-a", "And tell Sam."),
                ],
                "Done.",
            ),
        ];
        assert!(
            missing_replies(&messages, &runs).is_empty(),
            "no reply is missing, so this is only about the person's side"
        );

        let questions = missing_questions(&messages, &runs, &HashSet::new());
        let drawn: Vec<(&str, u128)> = questions
            .iter()
            .map(|question| {
                let at = question
                    .said_at
                    .duration_since(SystemTime::UNIX_EPOCH)
                    .unwrap();
                (question.id.as_str(), at.as_millis())
            })
            .collect();
        assert_eq!(
            drawn,
            vec![
                ("client-q1", 1_999),
                ("client-b", 4_998),
                ("client-a", 4_999)
            ],
            "each question once, with the run it opened, just before this thread's own reply"
        );

        let mut thread = messages.clone();
        graft_questions(&mut thread, &questions);
        let order = vec![
            "client-q1",
            "0-reply-1",
            "client-b",
            "client-a",
            "0-reply-2",
        ];
        assert_eq!(ids(&thread), order);
        assert_eq!(
            by_disk_order(&thread),
            order,
            "the same once read back from disk, where a tie would go by id"
        );
        assert!(thread[0].is_me && thread[0].run_id.is_none());
        assert_eq!(thread[0].content, "What is on my calendar?");

        assert!(
            missing_questions(&thread, &runs, &HashSet::new()).is_empty(),
            "and a second look draws nothing twice"
        );
    }

    /// The device a message was typed on holds it under the id it was sent with and gets nothing
    /// twice. A run with no reply here, or one the person hid, brings back no question. A turn
    /// that asked two things brings both back, in the order they were asked, even when it is the
    /// only run there is.
    #[test]
    fn a_question_comes_back_only_where_its_answer_is_shown_and_it_is_not() {
        let run = answered_run(
            "run_9",
            8_990,
            &[("client-z", "First this."), ("client-q9", "Then this.")],
            "Sure.",
        );
        let runs = [run];

        let typed_here = vec![
            at(message("client-z", true, "First this."), 7_000),
            at(message("client-q9", true, "Then this."), 8_000),
            from_run("0-reply-9", "Sure.", "run_9", 9_000),
        ];
        assert!(missing_questions(&typed_here, &runs, &HashSet::new()).is_empty());

        let answer_only = vec![from_run("0-reply-9", "Sure.", "run_9", 9_000)];
        let ids_drawn = |questions: Vec<RecoveredQuestion>| -> Vec<String> {
            questions.into_iter().map(|question| question.id).collect()
        };
        let questions = missing_questions(&answer_only, &runs, &HashSet::new());
        let mut thread = answer_only.clone();
        graft_questions(&mut thread, &questions);
        assert_eq!(
            ids_drawn(questions),
            vec!["client-z", "client-q9"],
            "both things the turn asked, not only the last"
        );
        let order = vec!["client-z", "client-q9", "0-reply-9"];
        assert_eq!(ids(&thread), order);
        assert_eq!(by_disk_order(&thread), order);

        assert!(missing_questions(&[], &runs, &HashSet::new()).is_empty());
        let hidden: HashSet<&str> = ["run_9"].into_iter().collect();
        assert!(missing_questions(&answer_only, &runs, &hidden).is_empty());
        let mut hidden_here = answer_only.clone();
        hidden_here[0].hidden = true;
        assert!(missing_questions(&hidden_here, &runs, &HashSet::new()).is_empty());
    }

    /// On a device that never held the turn, the reply is recovered first and the question is
    /// then put in above it, both from the same replay.
    #[test]
    fn a_recovered_turn_brings_its_question_with_it() {
        let runs = vec![answered_run(
            "run_1",
            2_000,
            &[("client-q1", "What is on my calendar?")],
            "Two meetings.",
        )];
        let mut thread: Vec<Message> = Vec::new();
        for reply in missing_replies(&thread, &runs) {
            graft_reply(&mut thread, &reply);
        }
        let questions = missing_questions(&thread, &runs, &HashSet::new());
        graft_questions(&mut thread, &questions);
        assert_eq!(by_disk_order(&thread), ids(&thread));
        assert_eq!(thread.len(), 2);
        assert_eq!(thread[0].id, "client-q1");
        assert_eq!(thread[1].run_id.as_deref(), Some("run_1"));
    }

    /// A recovered question is written only where no row has its id. The id is whatever the
    /// server sent, and ids are unique across threads: a second write, or an id that names some
    /// other row, must not change that row's words or take its pieces.
    #[tokio::test]
    async fn a_recovered_question_never_writes_over_a_row_that_has_its_id() {
        let db = test_db().await;
        db.ensure_session("s1", "one").await.unwrap();
        db.ensure_session("s2", "two").await.unwrap();
        db.save_message(
            "taken",
            "s1",
            "assistant",
            "Already here.",
            None,
            None,
            None,
            &saved_parts(&[ChatPart::Text("Already here.".to_string())]),
            Some("run_1"),
            false,
            SaveStamp::at(SystemTime::UNIX_EPOCH),
        )
        .await
        .unwrap();
        let parts_before = db.get_messages("s1").await.unwrap()[0].parts.clone();

        let said_at = SystemTime::UNIX_EPOCH + Duration::from_millis(1_999);
        assert!(
            !db.keep_recovered_question("taken", "s2", "A replay's words.", said_at)
                .await
                .unwrap()
        );
        let rows = db.get_messages("s1").await.unwrap();
        assert_eq!(rows[0].content, "Already here.");
        assert_eq!(rows[0].role, "assistant");
        assert_eq!(rows[0].parts, parts_before, "its pieces are still there");
        assert!(db.get_messages("s2").await.unwrap().is_empty());

        assert!(
            db.keep_recovered_question("client-q1", "s2", "What is on my calendar?", said_at)
                .await
                .unwrap()
        );
        assert!(
            !db.keep_recovered_question("client-q1", "s2", "Something else.", said_at)
                .await
                .unwrap()
        );
        let rows = db.get_messages("s2").await.unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].role, "user");
        assert_eq!(rows[0].content, "What is on my calendar?");
        assert_eq!(rows[0].created_at, "1970-01-01 00:00:01.999");
    }

    /// A routine's instruction in its thread says it is the routine's: the replay draws it where
    /// the person's words go, under the run's `{runId}-prompt` id. The person's own reply in the
    /// same thread, and the same id on the bot's own chat, are left as they are.
    #[test]
    fn a_routines_instruction_is_labelled_as_the_routines() {
        let prompt = message("run_01a0-prompt", true, "write the weekly report");
        let reply = message("client-q1", true, "and next week too");
        let mut routine = thread("sch_1", vec![prompt.clone(), reply.clone()]);
        routine.origin = Some(super::ThreadOrigin {
            word: "schedule".into(),
            routine_name: "Weekly".into(),
            coworker_id: "cw_1".into(),
        });
        assert_eq!(
            super::routine_instruction_caption(&routine, &prompt).as_deref(),
            Some("Instruction from Weekly")
        );
        assert!(super::routine_instruction_caption(&routine, &reply).is_none());
        let bots_chat = thread("cw_1", vec![prompt.clone()]);
        assert!(super::routine_instruction_caption(&bots_chat, &prompt).is_none());
        let from_the_bot = message("run_01a0-prompt", false, "…");
        assert!(super::routine_instruction_caption(&routine, &from_the_bot).is_none());
    }

    /// The open bot, one saved routine and one draft, the way the Computer pane leaves them.
    fn with_routines() -> AppState {
        let mut state = AppState::new();
        state.coworkers = vec![hired("cw_1", 1)];
        state.active_coworker_id = Some("cw_1".into());
        state.active_conversation_id = Some("cw_1".into());
        state.conversations.push(thread("cw_1", Vec::new()));
        let saved = super::routine_from_schedule(
            serde_json::from_value(serde_json::json!({
                "id": "sch_1", "coworkerId": "cw_1", "kind": "cron", "cron": "0 0 9 * * 1",
                "prompt": "write the weekly report", "name": "Weekly", "active": true
            }))
            .unwrap(),
        );
        let mut draft = saved.clone();
        draft.id = "draft-1".into();
        draft.saved = None;
        state.routines.insert("cw_1".into(), vec![saved, draft]);
        state
    }

    /// What can be opened as a routine's thread: a routine the server has, of the open bot.
    /// Not a draft, not another bot's routine, and never an id some bot's chat or an ordinary
    /// thread already answers to, which would mix two transcripts under one id.
    #[test]
    fn only_a_saved_routine_of_the_open_bot_opens_as_its_thread() {
        let mut state = with_routines();
        let origin = state
            .routine_thread_origin("sch_1")
            .expect("a saved routine");
        assert_eq!(origin.coworker_id, "cw_1");
        assert_eq!(origin.routine_name, "Weekly");
        assert_eq!(origin.word, "schedule");
        assert!(state.routine_thread_origin("draft-1").is_none());
        assert!(state.routine_thread_origin("sch_nope").is_none());
        assert!(
            state.routine_thread_origin("cw_1").is_none(),
            "a bot's own chat"
        );

        state.conversations.push(thread("sch_1", Vec::new()));
        assert!(
            state.routine_thread_origin("sch_1").is_none(),
            "an ordinary thread already under that id"
        );
        state.conversations.pop();
        state.coworkers.push(hired("sch_1", 2));
        assert!(
            state.routine_thread_origin("sch_1").is_none(),
            "an id that is some bot's"
        );
    }

    /// A routine's thread is somewhere of its own: the header names it, back and forward keep
    /// it apart from the bot's own chat, nothing about it is written to this Mac's database, and
    /// a form answered there is answered as the bot's, not as the schedule's.
    #[test]
    fn a_routines_thread_is_a_place_apart_from_the_bots_chat() {
        let mut state = with_routines();
        let mut card = message("m_card", false, "");
        card.parts = vec![ChatPart::UserForm(parked_form())];
        let mut routine = thread("sch_1", vec![card]);
        routine.origin = state.routine_thread_origin("sch_1");
        state.conversations.push(routine);

        assert!(state.active_thread_origin().is_none());
        assert_eq!(state.nav_location().thread_id, None, "the bot's own chat");
        assert!(state.keeps_on_disk("cw_1"));

        state.active_conversation_id = Some("sch_1".into());
        assert_eq!(
            state
                .active_thread_origin()
                .map(|o| o.routine_name.as_str()),
            Some("Weekly")
        );
        assert_eq!(state.nav_location().thread_id.as_deref(), Some("sch_1"));
        assert_eq!(state.nav_location().coworker_id.as_deref(), Some("cw_1"));
        assert!(
            !state.keeps_on_disk("sch_1"),
            "rebuilt from the server each time, never a row of its own"
        );

        let (entry, _, thread_id, agent_id) = state
            .user_form_context(parked_form().card_key())
            .expect("the card is on the routine's thread");
        assert_eq!(entry, "e_form");
        assert_eq!(thread_id, "sch_1", "the card is on the routine's thread");
        assert_eq!(agent_id, "cw_1", "and it is the bot's card to answer");
    }

    /// The history icon swaps a routine's fields for its runs and back, and the next routine to
    /// open, or the same one opened again, opens on its fields.
