    // ---- When to run: the wakes, and the wake editor ----------------------------------------

    /// The open bot with one saved routine (Sundays at nine, by the server's numbering), one
    /// draft with no wake yet, and one webhook routine.
    fn with_wakes() -> AppState {
        let mut state = with_routines();
        let rows = state.routines.get_mut("cw_1").expect("the bot's routines");
        if let Some(draft) = rows.iter_mut().find(|row| row.id == "draft-1") {
            draft.triggers.clear();
            draft.name.clear();
            draft.instruction.clear();
        }
        rows.push(super::routine_from_schedule(
            serde_json::from_value(serde_json::json!({
                "id": "sch_hook", "coworkerId": "cw_1", "kind": "webhook", "cron": null,
                "prompt": "Deal with it", "name": "Hook", "active": true,
                "webhook": { "url": "u", "key": "k", "header": "h" }
            }))
            .unwrap(),
        ));
        state.computer_view = super::ComputerView::Editor {
            id: Some("sch_1".into()),
        };
        state
    }

    /// The server keeps one wake per routine: + adds the first and is dead once there is one,
    /// and 🗑 never takes a routine's only wake, which is what deleting the routine is for.
    #[test]
    fn a_routine_has_one_wake_and_keeps_it() {
        let state = with_wakes();
        let routine = |id: &str| {
            state
                .coworker_routines("cw_1")
                .iter()
                .find(|row| row.id == id)
                .cloned()
                .unwrap()
        };
        assert!(
            AppState::can_add_wake(&routine("draft-1")),
            "a draft gets its first"
        );
        assert!(
            !AppState::can_add_wake(&routine("sch_1")),
            "one per routine"
        );
        assert!(!AppState::can_add_wake(&routine("sch_hook")));
        assert!(
            !AppState::can_remove_wake(&routine("sch_1")),
            "its only wake stays"
        );
        assert!(!AppState::can_remove_wake(&routine("sch_hook")));
    }

    /// Each tab of the wake editor writes the line the server takes for what it shows, and says
    /// it in words under it: the editor opens on the routine's own wake, every pick changes only
    /// the editor, and Save puts it on the routine.
    #[gpui_kit::test]
    fn each_tab_writes_its_line_and_says_what_was_picked(cx: &mut gpui_kit::TestAppContext) {
        use super::{WakeBox, WakeSaved, WakeTab};
        use gpui_kit::AppContext as _;
        let app = cx.new(|_| with_wakes());
        app.update(cx, |state, cx| {
            let line = |state: &AppState| match state.routine_wake_editor.as_ref().unwrap().picked()
            {
                Ok(super::NewTrigger::Schedule(spec)) => spec.to_cron().unwrap(),
                other => panic!("not a schedule: {other:?}"),
            };
            let summary = |state: &AppState| state.routine_wake_editor.as_ref().unwrap().summary();

            state.open_wake_editor("sch_1", Some(0), cx);
            let editor = state.routine_wake_editor.as_ref().unwrap();
            assert_eq!(
                editor.tab,
                WakeTab::Weekly,
                "the server's `0 0 9 * * 1` is Sundays"
            );
            assert_eq!(
                (editor.hour.as_str(), editor.minute.as_str(), editor.pm),
                ("9", "00", false)
            );
            assert_eq!(line(state), "0 9 * * SUN");

            // Every
            state.pick_wake_tab(WakeTab::Every, cx);
            state.set_wake_box(WakeBox::Every, "15".into(), true, cx);
            state.set_wake_unit(super::ScheduleUnit::Minutes, cx);
            assert_eq!(line(state), "*/15 * * * *");
            assert_eq!(summary(state), "Every 15 minutes");
            state.step_wake_box(WakeBox::Every, false, cx);
            assert_eq!(state.routine_wake_editor.as_ref().unwrap().every, "14");
            state.set_wake_unit(super::ScheduleUnit::Hours, cx);
            state.set_wake_box(WakeBox::Every, "6".into(), true, cx);
            assert_eq!(line(state), "0 */6 * * *");
            assert_eq!(summary(state), "Every 6 hours");

            // Daily, typed and stepped
            state.pick_wake_tab(WakeTab::Daily, cx);
            state.set_wake_box(WakeBox::Hour, "7".into(), true, cx);
            state.set_wake_box(WakeBox::Minute, "30".into(), true, cx);
            state.set_wake_pm(true, cx);
            assert_eq!(line(state), "30 19 * * *");
            assert_eq!(summary(state), "Every day at 7:30 PM");
            state.step_wake_box(WakeBox::Hour, true, cx);
            state.step_wake_box(WakeBox::Minute, true, cx);
            let editor = state.routine_wake_editor.as_ref().unwrap();
            assert_eq!((editor.hour.as_str(), editor.minute.as_str()), ("8", "35"));
            assert_eq!(line(state), "35 20 * * *");

            // Weekly keeps the day it had, and takes months.
            state.pick_wake_tab(WakeTab::Weekly, cx);
            assert_eq!(line(state), "35 20 * * SUN", "the day carries over");
            state.toggle_wake_weekday(6, cx);
            assert_eq!(line(state), "35 20 * * SUN,SAT");
            assert_eq!(summary(state), "Weekends at 8:35 PM");
            state.toggle_wake_weekday(0, cx);
            state.toggle_wake_month(1, cx);
            state.toggle_wake_month(3, cx);
            assert_eq!(line(state), "35 20 * 1,3 SAT");
            assert_eq!(summary(state), "Every Saturday at 8:35 PM, in Jan and Mar");

            // Monthly
            state.pick_wake_tab(WakeTab::Monthly, cx);
            state.toggle_wake_date(15, cx);
            assert_eq!(line(state), "35 20 1,15 1,3 *");
            assert_eq!(
                summary(state),
                "Monthly on the 1st and 15th at 8:35 PM, in Jan and Mar"
            );

            // Cron: five fields, said in words, with the server's next run or its refusal.
            state.pick_wake_tab(WakeTab::Cron, cx);
            assert_eq!(
                line(state),
                "35 20 1,15 1,3 *",
                "it starts from the line it was"
            );
            state.set_wake_box(WakeBox::Cron, "0 9 * * MON-FRI".into(), true, cx);
            assert_eq!(summary(state), "Weekdays at 9:00 AM");
            let now = chrono::Utc::now();
            let status = state.routine_wake_editor.as_ref().unwrap().status(now);
            assert!(status.can_save() && status.next.is_some(), "{status:?}");
            state.set_wake_box(WakeBox::Cron, "0 9 * * 1-5".into(), true, cx);
            let status = state.routine_wake_editor.as_ref().unwrap().status(now);
            assert!(status.numbered_weekdays, "the note says how they count");
            assert_eq!(
                status.summary, "Weekdays at 9:00 AM",
                "standard cron's 1-5 (#331)"
            );
            assert!(status.can_save() && status.next.is_some(), "{status:?}");
            for refused in ["0 9 * * 8", "@every 1h", "0 9 * *"] {
                state.set_wake_box(WakeBox::Cron, refused.into(), true, cx);
                let status = state.routine_wake_editor.as_ref().unwrap().status(now);
                assert!(!status.can_save(), "{refused}: {status:?}");
            }

            // A routine that is a schedule cannot become a webhook.
            state.pick_wake_tab(WakeTab::Webhook, cx);
            assert_eq!(
                state.routine_wake_editor.as_ref().unwrap().tab,
                WakeTab::Cron
            );

            // Save puts it on the routine.
            state.set_wake_box(WakeBox::Cron, "0 9 * * MON-FRI".into(), true, cx);
            assert_eq!(
                state.save_wake("Weekly".into(), "write the weekly report".into(), cx),
                WakeSaved::Changed
            );
            assert!(state.routine_wake_editor.is_none());
            let row = state.routine_mut("cw_1", "sch_1").unwrap();
            assert_eq!(row.triggers[0].label(), "Weekdays at 9:00 AM");
        });
    }

    /// A box that is not a time is no time, which the editor says, rather than an older time the
    /// box no longer shows; Save waits for one. Cancel leaves the routine as it was.
    #[gpui_kit::test]
    fn a_box_that_is_not_a_time_is_said_and_cancel_changes_nothing(
        cx: &mut gpui_kit::TestAppContext,
    ) {
        use super::{WakeBox, WakeSaved, WakeTab};
        use gpui_kit::AppContext as _;
        let app = cx.new(|_| with_wakes());
        app.update(cx, |state, cx| {
            state.open_wake_editor("sch_1", Some(0), cx);
            state.pick_wake_tab(WakeTab::Daily, cx);
            state.set_wake_box(WakeBox::Hour, "13".into(), true, cx);
            let status = state
                .routine_wake_editor
                .as_ref()
                .unwrap()
                .status(chrono::Utc::now());
            assert!(
                status
                    .error
                    .as_deref()
                    .is_some_and(|why| why.contains("time of day")),
                "{status:?}"
            );
            assert_eq!(
                state.save_wake("Weekly".into(), "write the weekly report".into(), cx),
                WakeSaved::Nothing
            );
            assert!(
                state.routine_wake_editor.is_some(),
                "still open, saying why"
            );

            state.close_wake_editor(cx);
            assert_eq!(
                state.routine_mut("cw_1", "sch_1").unwrap().triggers[0].label(),
                "Every Sunday at 9:00 AM",
                "nothing picked reached the routine"
            );
        });
    }

    /// A webhook routine's ✎ shows the webhook, and stays one; a draft's + may be either, and
    /// Save on a draft makes the routine, with the name and instruction typed for it.
    #[gpui_kit::test]
    fn a_webhook_stays_one_and_a_drafts_first_wake_makes_it(cx: &mut gpui_kit::TestAppContext) {
        use super::{WakeSaved, WakeTab};
        use gpui_kit::AppContext as _;
        let app = cx.new(|_| with_wakes());
        app.update(cx, |state, cx| {
            state.open_wake_editor("sch_hook", Some(0), cx);
            let editor = state.routine_wake_editor.as_ref().unwrap();
            assert_eq!(editor.tab, WakeTab::Webhook);
            assert!(!editor.tab_open(WakeTab::Daily));
            assert_eq!(editor.summary(), "When a webhook fires");
            assert_eq!(
                state.save_wake("Hook".into(), "Deal with it".into(), cx),
                WakeSaved::Closed
            );

            state.open_wake_editor("draft-1", None, cx);
            let editor = state.routine_wake_editor.as_ref().unwrap();
            assert!(WakeTab::ALL.into_iter().all(|tab| editor.tab_open(tab)));
            assert_eq!(
                editor.tab,
                WakeTab::Daily,
                "a new wake starts at 9:00 AM daily"
            );
            assert_eq!(
                state.save_wake("Morning".into(), "say hello".into(), cx),
                WakeSaved::Created
            );
            let draft = state.routine_mut("cw_1", "draft-1").unwrap();
            assert_eq!(
                (draft.name.as_str(), draft.instruction.as_str()),
                ("Morning", "say hello"),
                "what was typed goes to the server with it"
            );
        });
    }

    /// A slow server is asked for the computer's status one request at a time: ticks that come
    /// while one is out add nothing, and a refresh asked for meanwhile goes once, after the
    /// answer, so it never takes an answer that predates it. Without this the two-second poll
    /// piled five requests on a server taking eleven seconds each, slowing them all.
    #[test]
    fn the_computers_status_is_asked_one_request_at_a_time() {
        let mut state = AppState::default();
        assert!(state.begin_computer_refresh(), "the first goes");
        assert!(
            !state.begin_computer_refresh(),
            "a tick while it is out waits"
        );
        assert!(!state.begin_computer_refresh(), "and so does the next");
        assert!(
            state.settle_computer_refresh(),
            "the answer lands, and one more goes for what was asked meanwhile"
        );
        assert!(state.begin_computer_refresh(), "that one goes");
        assert!(
            !state.settle_computer_refresh(),
            "nothing was asked while it was out, so nothing follows it"
        );
        assert!(
            state.begin_computer_refresh(),
            "and the next tick goes again"
        );
    }

    // ---- A routine on a server that cannot do everything with one -------------------------

    /// The open bot and its routines, talking to `server`.
    fn routines_on(server: &wiremock::MockServer) -> AppState {
        let mut state = with_routines();
        state.opengrok = Some(OpenGrokClient::new(&server.uri()).expect("a URL that parses"));
        state
    }

    /// `server` answers `method path` with `answer`, and nothing else.
    async fn answers(
        method: &str,
        route: &str,
        answer: wiremock::ResponseTemplate,
    ) -> wiremock::MockServer {
        let server = wiremock::MockServer::start().await;
        wiremock::Mock::given(wiremock::matchers::method(method))
            .and(wiremock::matchers::path(route))
            .respond_with(answer)
            .mount(&server)
            .await;
        server
    }

    // ---- A routine a Bot changes in chat is on screen when its call answers ---------------------

    /// One of Ada's routines as `GET /schedules` lists it (opengrok-server #342, as recorded in
    /// `fixtures/wire/rest/GET__schedules/200-a_bot_runs_a_routine_by_its_id_and_its_history_names_the_bot.json`).
    fn adas_schedule(id: &str, name: &str) -> serde_json::Value {
        json!({"id": id, "coworkerId": "cw_1", "name": name, "cron": "0 0 9 * * MON-FRI",
               "prompt": "post the standup", "kind": "cron", "active": true,
               "nextDueMs": 1_790_000_000_000_i64,
               "runLimits": {"maxRounds": null, "maxComputerRounds": null, "maxWallMs": null},
               "lastRun": null, "tz": "UTC"})
    }

    /// The frames of one Bot turn that calls `tool` with `arguments`, which answers `ok` with
    /// `answered`, and says so; as the server streams a builtin's call (the recorded run in
    /// `fixtures/wire/rest/GET__ag-ui_threads__thread_id_/200-a_bot_runs_a_routine_by_its_id_and_its_history_names_the_bot.json`).
    fn a_turn_calling(tool: &str, arguments: &str, answered: &str) -> Vec<serde_json::Value> {
        vec![
            json!({"type": "RUN_STARTED", "threadId": "cw_1", "runId": "run_turn"}),
            json!({"type": "TOOL_CALL_START", "toolCallId": "call-routine", "toolCallName": tool}),
            json!({"type": "TOOL_CALL_ARGS", "toolCallId": "call-routine", "delta": arguments}),
            json!({"type": "TOOL_CALL_END", "toolCallId": "call-routine"}),
            json!({"type": "TOOL_CALL_RESULT", "toolCallId": "call-routine", "ok": true,
                   "content": answered}),
            json!({"type": "TEXT_MESSAGE_START", "messageId": "m_said", "role": "assistant"}),
            json!({"type": "TEXT_MESSAGE_CONTENT", "messageId": "m_said", "delta": "Done."}),
            json!({"type": "TEXT_MESSAGE_END", "messageId": "m_said"}),
            json!({"type": "RUN_FINISHED", "threadId": "cw_1", "runId": "run_turn"}),
        ]
    }

    /// A window signed in to `server` with Ada (`cw_1`) open on her thread, holding `routines` as
    /// her routines, and `server` answering every turn with `frames` and every read of Ada's
    /// routines with `listed`.
    fn adas_window(
        cx: &mut gpui_kit::TestAppContext,
        runtime: &tokio::runtime::Runtime,
        server: &wiremock::MockServer,
        frames: &[serde_json::Value],
        listed: serde_json::Value,
        routines: Vec<super::AgentRoutine>,
    ) -> gpui_kit::Entity<AppState> {
        use gpui_kit::AppContext as _;
        use wiremock::matchers::{method, path, query_param};
        let stream: String = frames
            .iter()
            .map(|frame| format!("data: {frame}\n\n"))
            .collect();
        let client = runtime.block_on(async {
            wiremock::Mock::given(method("POST"))
                .and(path("/ag-ui"))
                .respond_with(
                    wiremock::ResponseTemplate::new(200)
                        .insert_header("content-type", "text/event-stream")
                        .set_body_string(stream),
                )
                .mount(server)
                .await;
            wiremock::Mock::given(method("GET"))
                .and(path("/schedules"))
                .and(query_param("coworker", "cw_1"))
                .respond_with(wiremock::ResponseTemplate::new(200).set_body_json(listed))
                .mount(server)
                .await;
            client_signed_in_to(server).await
        });
        let mut state = signed_in_state();
        state.opengrok = Some(client);
        with_bot(&mut state, json!("gateway"));
        state.conversations.push(thread("cw_1", Vec::new()));
        state.active_conversation_id = Some("cw_1".into());
        state.routines.insert("cw_1".into(), routines);
        cx.new(|_| state)
    }

    /// A notice is written to the app's own database and read back from it after a restart. The
    /// write runs where the database can run (8 Oct 2026: it ran on a background thread with no
    /// Tokio context, and the app aborted the moment anything went wrong).
    #[gpui_kit::test]
    fn a_notice_is_kept_in_the_database_and_read_back(cx: &mut gpui_kit::TestAppContext) {
        use gpui_kit::AppContext as _;
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let db = runtime.block_on(test_db());
        let mut state = signed_in_state();
        state.database_service = Some(db.clone());
        let app = cx.new(|_| state);
        app.update(cx, |state, cx| {
            state.notify_error(Some("cw_1".into()), "Turn", "it broke", None, None, cx);
        });
        // A second window on the same database stands for a restart: it reads the notice back the
        // way the app does, so the write is seen only once it really landed.
        let reopened = cx.new(|_| {
            let mut state = signed_in_state();
            state.database_service = Some(db.clone());
            state
        });
        wait_for(cx, "written, and read back after a restart", |cx| {
            reopened.update(cx, |state, cx| {
                if state.notices.is_empty() {
                    state.load_notices(cx);
                }
            });
            cx.run_until_parked();
            reopened.read_with(cx, |state, _| {
                state.notices.len() == 1 && state.notices[0].said == "it broke"
            })
        });
    }

    /// A turn that fails leaves one quiet line in the chat and its whole sentence in its Bot's
    /// notifications, with where it was caught, and the toast says so (8 Oct 2026: the sentence
    /// was a red line in the chat that could not be dismissed or copied).
    #[gpui_kit::test]
    fn a_failed_turn_goes_to_its_bots_notifications_and_the_toast(
        cx: &mut gpui_kit::TestAppContext,
    ) {
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let server = runtime.block_on(wiremock::MockServer::start());
        let frames = vec![
            json!({"type": "RUN_STARTED", "threadId": "cw_1", "runId": "run_turn"}),
            json!({"type": "RUN_ERROR", "message": "upstream anthropic returned 400"}),
        ];
        let app = adas_window(cx, &runtime, &server, &frames, json!([]), Vec::new());
        app.update(cx, |state, cx| state.send_message("hello".into(), cx));
        wait_for(cx, "the failure is noticed", |cx| {
            app.read_with(cx, |state, _| !state.notices.is_empty())
        });
        app.read_with(cx, |state, _| {
            let notice = &state.notices[0];
            assert_eq!(notice.bot.as_deref(), Some("cw_1"));
            assert_eq!(notice.place, "Turn");
            assert!(
                notice.said.contains("upstream anthropic returned 400"),
                "{notice:?}"
            );
            assert!(notice.code.starts_with("src/state.rs:"), "{notice:?}");
            assert_eq!(
                state.toast.as_deref(),
                Some(notice.id.as_str()),
                "the toast shows it"
            );
            assert_eq!(state.unread_notices("cw_1"), 1, "the bell counts it");
        });
    }

    /// A Bot asked in chat makes a routine with `create_routine` (opengrok-server #316:
    /// `crates/opengrok-tools/src/routine.rs`), and the server has it the moment the call answers.
    /// The Routines list is read again then, once, and lists it, with nobody switching Bots and back
    /// for the list to be read.
    #[gpui_kit::test]
    fn a_routine_a_bot_makes_in_a_turn_is_listed_when_its_call_answers(
        cx: &mut gpui_kit::TestAppContext,
    ) {
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let server = runtime.block_on(wiremock::MockServer::start());
        let frames = a_turn_calling(
            "create_routine",
            r#"{"name":"Standup","prompt":"post the standup","when":{"cron":"0 9 * * MON-FRI"}}"#,
            r#"{"id":"sched_new","name":"Standup"}"#,
        );
        let listed = json!([adas_schedule("sched_new", "Standup")]);
        let app = adas_window(cx, &runtime, &server, &frames, listed, Vec::new());
        app.update(cx, |state, cx| {
            state.send_message("Make me a standup routine at 9 on weekdays".into(), cx)
        });
        wait_for(cx, "the Bot's new routine is listed", |cx| {
            app.read_with(cx, |state, _| {
                state
                    .coworker_routines("cw_1")
                    .iter()
                    .any(|routine| routine.id == "sched_new" && routine.name == "Standup")
            })
        });
        assert_eq!(asked_for(&runtime, &server, "/schedules"), 1);
    }

    /// A Bot running a routine (`run_routine`, opengrok-server #337, built in #342) starts a run
    /// the routine's history lists at once. With that routine open in the Computer pane, on its
    /// history, the list and the history are both read again when the call answers, and the
    /// history shows the Bot's run.
    #[gpui_kit::test]
    fn a_run_a_bot_starts_is_in_the_open_routines_history_when_its_call_answers(
        cx: &mut gpui_kit::TestAppContext,
    ) {
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let server = runtime.block_on(wiremock::MockServer::start());
        runtime.block_on(
            wiremock::Mock::given(wiremock::matchers::method("GET"))
                .and(wiremock::matchers::path("/schedules/sched_1/runs"))
                .respond_with(wiremock::ResponseTemplate::new(200).set_body_json(json!([{
                    "runId": "run_bot", "cause": "bot", "status": "ok",
                    "startedAtMs": 1_790_000_000_000_i64, "endedAtMs": 1_790_000_001_000_i64,
                    "by": {"coworkerId": "cw_1", "name": "Ada"}
                }])))
                .mount(&server),
        );
        let frames = a_turn_calling(
            "run_routine",
            r#"{"routine":"sched_1"}"#,
            r#"{"runId":"run_bot","threadId":"sched_1"}"#,
        );
        let standup = adas_schedule("sched_1", "Standup");
        let routine = super::routine_from_schedule(
            serde_json::from_value(standup.clone()).expect("a routine"),
        );
        let app = adas_window(
            cx,
            &runtime,
            &server,
            &frames,
            json!([standup]),
            vec![routine],
        );
        app.update(cx, |state, cx| {
            state.right_pane = super::RightPane::Computer;
            state.computer_view = super::ComputerView::Editor {
                id: Some("sched_1".into()),
            };
            state.routine_history_open = true;
            state.send_message("Run my standup now".into(), cx)
        });
        wait_for(cx, "the Bot's run is in the history", |cx| {
            app.read_with(cx, |state, _| {
                state.coworker_routines("cw_1").iter().any(|routine| {
                    routine.id == "sched_1"
                        && routine
                            .runs
                            .iter()
                            .any(|run| run.by.as_deref() == Some("Ada"))
                })
            })
        });
        assert_eq!(asked_for(&runtime, &server, "/schedules/sched_1/runs"), 1);
        wait_for(cx, "the list is read again too", |_| {
            asked_for(&runtime, &server, "/schedules") == 1
        });
    }

    /// A delete always asks first (opengrok-server #316), so its call is answered in the run that
    /// carries on after the person's yes, which this window follows through the replay route
    /// ([`AppState::follow_run`]). The call's first answer, `waiting for approval`, deleted nothing
    /// (`ok: false`, opengrok-tools `ToolResult::awaiting`) and the second did: the Routines list
    /// is read again once, then, and the routine is gone from it; and its panel, open in the
    /// Computer pane, closes back to the list, as the person's own delete closes it.
    #[gpui_kit::test]
    fn a_routine_a_bot_deletes_after_a_yes_leaves_the_list_when_its_call_answers(
        cx: &mut gpui_kit::TestAppContext,
    ) {
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let server = runtime.block_on(wiremock::MockServer::start());
        let events = json!([
            {"type": "RUN_STARTED", "threadId": "cw_1", "runId": "run_del"},
            {"type": "TOOL_CALL_START", "toolCallId": "call-routine",
             "toolCallName": "delete_routine"},
            {"type": "TOOL_CALL_ARGS", "toolCallId": "call-routine",
             "delta": r#"{"routine":"sched_1"}"#},
            {"type": "TOOL_CALL_END", "toolCallId": "call-routine"},
            {"type": "TOOL_CALL_RESULT", "toolCallId": "call-routine", "ok": false,
             "content": "waiting for approval: Delete the routine \"Standup\"? It stops for good."},
            {"type": "CUSTOM", "name": "run-awaiting-approval", "threadId": "cw_1",
             "runId": "run_del", "callId": "call-routine", "tool": "delete_routine",
             "arguments": {"routine": "sched_1"}, "reason": "policy-approval",
             "why": "Delete the routine \"Standup\"? It stops for good.",
             "summary": "Delete the routine sched_1"},
            {"type": "TOOL_CALL_RESULT", "toolCallId": "call-routine", "ok": true,
             "content": "deleted the routine Standup"},
            {"type": "RUN_FINISHED", "threadId": "cw_1", "runId": "run_del"}
        ]);
        runtime.block_on(
            wiremock::Mock::given(wiremock::matchers::method("GET"))
                .and(wiremock::matchers::path("/ag-ui/runs/run_del"))
                .respond_with(wiremock::ResponseTemplate::new(200).set_body_json(json!({
                    "runId": "run_del", "status": "finished",
                    "startedAtMs": 1_790_000_000_000_i64, "events": events
                })))
                .mount(&server),
        );
        let routine = super::routine_from_schedule(
            serde_json::from_value(adas_schedule("sched_1", "Standup")).expect("a routine"),
        );
        let app = adas_window(cx, &runtime, &server, &[], json!([]), vec![routine]);
        app.update(cx, |state, cx| {
            state.right_pane = super::RightPane::Computer;
            state.computer_view = super::ComputerView::Editor {
                id: Some("sched_1".into()),
            };
            state.follow_run("run_del".into(), Some("cw_1".into()), cx)
        });
        wait_for(cx, "the deleted routine leaves the list", |cx| {
            app.read_with(cx, |state, _| state.coworker_routines("cw_1").is_empty())
        });
        assert_eq!(asked_for(&runtime, &server, "/schedules"), 1);
        assert_eq!(
            app.read_with(cx, |state, _| state.computer_view.clone()),
            super::ComputerView::Overview,
            "its panel closes back to the list"
        );
    }

    /// Ada with her Standup routine open in the Computer pane, drawn in a window, against `server`,
    /// which answers every turn with `frames`, every read of her routines with `listed`, and every
    /// read of the routine's history with one run of the Bot's.
    fn adas_standup_open_in_a_window<'a>(
        cx: &'a mut gpui_kit::TestAppContext,
        runtime: &tokio::runtime::Runtime,
        server: &wiremock::MockServer,
        frames: &[serde_json::Value],
        listed: serde_json::Value,
    ) -> (
        gpui_kit::Entity<AppState>,
        gpui_kit::Entity<crate::components::computer::ComputerPane>,
        &'a mut gpui_kit::VisualTestContext,
    ) {
        cx.update(gpui_kit::init);
        runtime.block_on(
            wiremock::Mock::given(wiremock::matchers::method("GET"))
                .and(wiremock::matchers::path("/schedules/sched_1/runs"))
                .respond_with(wiremock::ResponseTemplate::new(200).set_body_json(json!([{
                    "runId": "run_bot", "cause": "bot", "status": "ok",
                    "startedAtMs": 1_790_000_000_000_i64, "endedAtMs": 1_790_000_001_000_i64,
                    "by": {"coworkerId": "cw_1", "name": "Ada"}
                }])))
                .mount(server),
        );
        let routine = super::routine_from_schedule(
            serde_json::from_value(adas_schedule("sched_1", "Standup")).expect("a routine"),
        );
        let app = adas_window(cx, runtime, server, frames, listed, vec![routine]);
        app.update(cx, |state, _| {
            state.right_pane = super::RightPane::Computer;
            state.computer_view = super::ComputerView::Editor {
                id: Some("sched_1".into()),
            };
        });
        let (pane, window) = cx.add_window_view({
            let app = app.clone();
            move |window, cx| crate::components::computer::ComputerPane::new(window, app, cx)
        });
        window.simulate_resize(gpui_kit::size(gpui_kit::px(320.), gpui_kit::px(2400.)));
        window.update(|window, cx| window.draw(cx).clear(cx));
        (app, pane, window)
    }

    /// The Standup routine as `update_routine` left it on the server: a new name and instruction.
    fn adas_standup_renamed() -> serde_json::Value {
        let mut renamed = adas_schedule("sched_1", "Daily standup");
        renamed["prompt"] = json!("post the standup in #team");
        renamed
    }

    /// A Bot renames a routine in chat with `update_routine` (opengrok-server #316:
    /// `crates/opengrok-tools/src/routine.rs`). When the call answers, the list is read again, once,
    /// and the routine's row takes the server's new name; its panel, open in the Computer pane with
    /// nothing typed in it, takes the new name and instruction into its fields.
    #[gpui_kit::test]
    fn a_routine_a_bot_renames_takes_its_new_name_on_its_row_and_in_its_open_panel(
        cx: &mut gpui_kit::TestAppContext,
    ) {
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let server = runtime.block_on(wiremock::MockServer::start());
        let frames = a_turn_calling(
            "update_routine",
            r#"{"routine":"sched_1","name":"Daily standup","prompt":"post the standup in #team"}"#,
            r#"{"id":"sched_1","name":"Daily standup"}"#,
        );
        let listed = json!([adas_standup_renamed()]);
        let (app, pane, window) =
            adas_standup_open_in_a_window(cx, &runtime, &server, &frames, listed);
        assert_eq!(
            pane.read_with(window, |pane, cx| pane.routine_fields(cx)),
            ("Standup".to_string(), "post the standup".to_string())
        );
        app.update(window, |state, cx| {
            state.send_message("Call my standup routine Daily standup".into(), cx)
        });
        wait_for(window, "the row takes the new name", |cx| {
            app.read_with(cx, |state, _| {
                state.coworker_routines("cw_1")[0].name == "Daily standup"
            })
        });
        window.update(|window, cx| window.draw(cx).clear(cx));
        assert_eq!(
            pane.read_with(window, |pane, cx| pane.routine_fields(cx)),
            (
                "Daily standup".to_string(),
                "post the standup in #team".to_string()
            ),
            "the open panel takes the server's copy"
        );
        assert_eq!(asked_for(&runtime, &server, "/schedules"), 1);
        wait_for(window, "the open routine's history is read again", |cx| {
            app.read_with(cx, |state, _| {
                !state.coworker_routines("cw_1")[0].runs.is_empty()
            })
        });
    }

    /// The same rename while the person is typing in the panel's Name field: what they typed stays
    /// in it, for their own Save or the next read to settle, and is never written over; the row in
    /// the list takes the server's new name, and the Instruction field, which they have not typed
    /// in, takes the server's new instruction.
    #[gpui_kit::test]
    fn a_field_the_person_is_typing_in_keeps_their_words_when_a_bot_changes_the_routine(
        cx: &mut gpui_kit::TestAppContext,
    ) {
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let server = runtime.block_on(wiremock::MockServer::start());
        let frames = a_turn_calling(
            "update_routine",
            r#"{"routine":"sched_1","name":"Daily standup","prompt":"post the standup in #team"}"#,
            r#"{"id":"sched_1","name":"Daily standup"}"#,
        );
        let listed = json!([adas_standup_renamed()]);
        let (app, pane, window) =
            adas_standup_open_in_a_window(cx, &runtime, &server, &frames, listed);
        let name = window.debug_bounds("routine-name").expect("the Name field");
        window.simulate_mouse_move(name.center(), None, gpui_kit::Modifiers::none());
        window.simulate_click(name.center(), gpui_kit::Modifiers::none());
        window.simulate_input(" for the team");
        let typed = pane.read_with(window, |pane, cx| pane.routine_fields(cx)).0;
        assert!(
            typed.contains(" for the team") && typed != "Standup",
            "typed into the field: {typed:?}"
        );

        app.update(window, |state, cx| {
            state.send_message("Call my standup routine Daily standup".into(), cx)
        });
        wait_for(window, "the row takes the new name", |cx| {
            app.read_with(cx, |state, _| {
                state.coworker_routines("cw_1")[0].name == "Daily standup"
            })
        });
        window.update(|window, cx| window.draw(cx).clear(cx));
        assert_eq!(
            pane.read_with(window, |pane, cx| pane.routine_fields(cx)),
            (typed, "post the standup in #team".to_string()),
            "the typed name stays; the instruction nobody typed in follows the server"
        );
        wait_for(window, "the open routine's history is read again", |cx| {
            app.read_with(cx, |state, _| {
                !state.coworker_routines("cw_1")[0].runs.is_empty()
            })
        });
    }

    /// A server from before routines kept a history answers `GET /schedules/{id}/runs` with an
    /// empty 404. The history says it cannot show the runs, in place of "No runs yet", and there
    /// is no red line over the editor about a read nobody asked for; nor is it asked again.
    #[tokio::test]
    async fn a_server_without_a_routines_history_says_so_in_the_history() {
        let server = answers(
            "GET",
            "/schedules/sch_1/runs",
            wiremock::ResponseTemplate::new(404),
        )
        .await;
        let mut state = routines_on(&server);
        let (client, read) = state
            .begin_routine_runs_read("cw_1", "sch_1")
            .expect("a routine the server has");
        let result = client.schedule_runs("sch_1").await;
        assert!(state.settle_routine_runs("cw_1", "sch_1", read, result));
        assert!(state.routine_routes_missing.runs);
        assert_eq!(state.computer_action_error, None, "not \"request failed\"");
        assert!(
            state.begin_routine_runs_read("cw_1", "sch_1").is_none(),
            "a server that has said it cannot is not asked again"
        );
    }

    /// A server from before routines could be changed answers `PATCH /schedules/{id}` with a
    /// 405. What the person typed stays on screen to read, the line says why, the routine goes
    /// back to the server's own values (which the fields follow), and from then on an edit is
    /// refused here the same way rather than sent again.
    #[tokio::test]
    async fn a_server_that_cannot_change_a_routine_keeps_what_was_typed_and_puts_its_own_back() {
        let server = answers(
            "PATCH",
            "/schedules/sch_1",
            wiremock::ResponseTemplate::new(405),
        )
        .await;
        let mut state = routines_on(&server);
        // Every minute, where the server has Sundays at nine, and a new name.
        if let Some(super::RoutineTrigger::Schedule { spec, .. }) = state
            .routine_mut("cw_1", "sch_1")
            .and_then(|row| row.triggers.first_mut())
        {
            *spec = super::ScheduleSpec::interval(1, super::ScheduleUnit::Minutes);
        }
        let (client, number, edit) = state
            .begin_routine_edit(
                "cw_1",
                "sch_1",
                "Daily".into(),
                "write the weekly report".into(),
            )
            .expect("an edit to send");
        assert_eq!(edit.cron.as_deref(), Some("* * * * *"));
        let result = client.edit_schedule("sch_1", &edit).await;
        assert_eq!(
            state.settle_routine_edit("cw_1", "sch_1", number, edit.clone(), result),
            super::AfterRoutineEdit::Nothing,
            "nothing to read back: the server has what it had"
        );

        assert!(state.routine_routes_missing.edit);
        assert_eq!(
            state.computer_action_error.as_deref(),
            Some(super::ROUTINE_EDIT_UNAVAILABLE)
        );
        assert_eq!(state.routine_unsaved.get("sch_1"), Some(&edit));
        assert_eq!(
            super::unsaved_lines(&edit),
            [
                ("Name", "Daily".to_string()),
                ("When", "Every 1 minute".to_string())
            ]
        );
        let row = state.routine_mut("cw_1", "sch_1").expect("the routine");
        assert_eq!(row.name, "Weekly", "the server's name is back");
        assert!(
            super::routine_edit(row).is_empty(),
            "and so is its schedule: nothing differs from what it has"
        );
        assert_eq!(
            state.routine_resync("sch_1"),
            1,
            "the fields follow it back"
        );
        assert_eq!(
            super::routine_notes(state.routine_routes_missing, true),
            [("cant-change", super::ROUTINE_EDIT_UNAVAILABLE)]
        );
        assert!(
            super::routine_notes(state.routine_routes_missing, false).is_empty(),
            "a draft is made by a route every server has"
        );

        state.computer_action_error = None;
        assert!(
            state
                .begin_routine_edit(
                    "cw_1",
                    "sch_1",
                    "Again".into(),
                    "write the weekly report".into()
                )
                .is_none(),
            "not sent again"
        );
        assert_eq!(
            state.computer_action_error.as_deref(),
            Some(super::ROUTINE_EDIT_UNAVAILABLE)
        );
        assert_eq!(
            state
                .routine_unsaved
                .get("sch_1")
                .and_then(|edit| edit.name.as_deref()),
            Some("Again")
        );
        assert_eq!(state.routine_mut("cw_1", "sch_1").unwrap().name, "Weekly");
        let mut sent = server
            .received_requests()
            .await
            .expect("the recorder is on");
        sent.retain(|request| request.method.as_str() == "PATCH");
        assert_eq!(sent.len(), 1, "one PATCH, the first");
    }

    /// A server from before routines could be run on demand answers `POST /schedules/{id}/run`
    /// with an empty 404. Test run says so and goes dead, and a run asked for after that is
    /// refused here in the same words rather than sent.
    #[tokio::test]
    async fn a_server_that_cannot_run_a_routine_on_demand_says_so_and_test_run_goes_dead() {
        let server = answers(
            "POST",
            "/schedules/sch_1/run",
            wiremock::ResponseTemplate::new(404),
        )
        .await;
        let mut state = routines_on(&server);
        let client = state
            .begin_routine_run("cw_1", "sch_1")
            .expect("a run to start");
        let result = client.run_schedule_now("sch_1").await;
        assert!(
            !state.settle_routine_run("cw_1", "sch_1", result),
            "no run started, so no history to read"
        );
        assert!(state.routine_routes_missing.run_now);
        assert_eq!(
            state.computer_action_error.as_deref(),
            Some(super::ROUTINE_RUN_UNAVAILABLE)
        );
        assert!(
            super::routine_notes(state.routine_routes_missing, false)
                .contains(&("cant-run", super::ROUTINE_RUN_UNAVAILABLE))
        );

        state.computer_action_error = None;
        assert!(state.begin_routine_run("cw_1", "sch_1").is_none());
        assert_eq!(
            state.computer_action_error.as_deref(),
            Some(super::ROUTINE_RUN_UNAVAILABLE)
        );
    }

    /// Any other refusal is said in the server's words, and one with no words in it as what the
    /// server answered: never the client's stand-in, "request failed". Neither marks a route as
    /// missing, so nothing goes dead over a routine that is gone or a server having a bad moment.
    #[tokio::test]
    async fn a_routine_refusal_is_the_servers_words_and_never_a_bare_request_failed() {
        let gone = answers(
            "POST",
            "/schedules/sch_1/run",
            wiremock::ResponseTemplate::new(404).set_body_string("no such schedule"),
        )
        .await;
        let mut state = routines_on(&gone);
        let client = state.begin_routine_run("cw_1", "sch_1").expect("a run");
        let result = client.run_schedule_now("sch_1").await;
        assert!(!state.settle_routine_run("cw_1", "sch_1", result));
        assert_eq!(
            state.computer_action_error.as_deref(),
            Some("No such schedule")
        );
        assert!(!state.routine_routes_missing.run_now);

        let silent = answers(
            "GET",
            "/schedules/sch_1/runs",
            wiremock::ResponseTemplate::new(500),
        )
        .await;
        let mut state = routines_on(&silent);
        let (client, read) = state
            .begin_routine_runs_read("cw_1", "sch_1")
            .expect("a read");
        let result = client.schedule_runs("sch_1").await;
        assert!(state.settle_routine_runs("cw_1", "sch_1", read, result));
        assert_eq!(
            state.computer_action_error.as_deref(),
            Some("The server answered 500 without saying why.")
        );
        assert!(!state.routine_routes_missing.runs);

        // Nobody answered at all.
        let mut state = with_routines();
        state.opengrok = Some(OpenGrokClient::new("http://127.0.0.1:9").expect("a URL"));
        let (client, read) = state
            .begin_routine_runs_read("cw_1", "sch_1")
            .expect("a read");
        let result = client.schedule_runs("sch_1").await;
        assert!(state.settle_routine_runs("cw_1", "sch_1", read, result));
        assert_eq!(
            state.computer_action_error.as_deref(),
            Some("Could not reach the server.")
        );
    }

    /// A firing the server skipped (opengrok-server #316: the Bot answers on its person's own
    /// plan, and no computer held the relay) is a line of the history with no run: it says the
    /// server's sentence, opens nothing, and is settled, so nothing reads it again.
    #[test]
    fn a_skipped_line_says_why_and_has_no_run_to_open() {
        let said = "Skipped: your computer was off, so your plan couldn't answer";
        let line: crate::opengrok::ScheduleRun = serde_json::from_value(serde_json::json!({
            "runId": null, "cause": "clock", "status": null, "startedAtMs": null,
            "endedAtMs": null, "at": 1_790_000_000_000i64, "state": "skipped",
            "skipped": "relay_offline", "reason": said
        }))
        .expect("a skipped line");
        let run = super::RoutineRun::from_server(line);
        assert_eq!(
            run.outcome,
            super::RunOutcome::Skipped {
                reason: said.into()
            }
        );
        assert_eq!(run.run_id(), None, "nothing to open");
        assert!(!run.unsettled(), "a skip is settled");
        assert_eq!(run.cause_label(), "Schedule");
        assert_eq!(
            run.started_at_ms, 1_790_000_000_000,
            "its time is when it was due"
        );
        assert!(!run.at.is_empty());
    }

    /// Run it now on a Bot whose own plan cannot answer (opengrok-server #316, #334, on main
    /// 8e7387f: no computer holds the person's relay) is the server's 409 with the skip's code. Its
    /// sentence goes on the routine's red line, nothing is shown as running, and the history is
    /// read again for the line the server kept, which says the same and opens nothing.
    #[tokio::test]
    async fn run_now_while_the_plan_cannot_answer_says_why_and_reads_the_skip_back() {
        let said = "Skipped: your computer was off, so your plan couldn't answer";
        let server = wiremock::MockServer::start().await;
        wiremock::Mock::given(wiremock::matchers::method("POST"))
            .and(wiremock::matchers::path("/schedules/sch_1/run"))
            .respond_with(
                wiremock::ResponseTemplate::new(409)
                    .set_body_json(serde_json::json!({ "error": said, "code": "relay_offline" })),
            )
            .mount(&server)
            .await;
        wiremock::Mock::given(wiremock::matchers::method("GET"))
            .and(wiremock::matchers::path("/schedules/sch_1/runs"))
            .respond_with(
                wiremock::ResponseTemplate::new(200).set_body_json(serde_json::json!([{
                    "runId": null, "cause": "manual", "status": null, "startedAtMs": null,
                    "endedAtMs": null, "at": 1_790_000_000_000i64, "state": "skipped",
                    "skipped": "relay_offline", "reason": said
                }])),
            )
            .mount(&server)
            .await;
        let mut state = routines_on(&server);
        let client = state
            .begin_routine_run("cw_1", "sch_1")
            .expect("a run to ask for");
        let result = client.run_schedule_now("sch_1").await;
        assert!(
            state.settle_routine_run("cw_1", "sch_1", result),
            "the history is read again for the skip"
        );
        assert_eq!(state.computer_action_error.as_deref(), Some(said));
        assert!(
            state.routine_mut("cw_1", "sch_1").unwrap().runs.is_empty(),
            "no run started, so none is shown running"
        );

        let (client, read) = state
            .begin_routine_runs_read("cw_1", "sch_1")
            .expect("a read");
        let result = client.schedule_runs("sch_1").await;
        assert!(state.settle_routine_runs("cw_1", "sch_1", read, result));
        assert_eq!(
            state.computer_action_error.as_deref(),
            Some(said),
            "the read raises nothing of its own"
        );
        let runs = &state.routine_mut("cw_1", "sch_1").unwrap().runs;
        assert_eq!(runs.len(), 1);
        assert_eq!(
            runs[0].outcome,
            super::RunOutcome::Skipped {
                reason: said.into()
            }
        );
        assert_eq!(runs[0].cause_label(), "Test run");
        assert_eq!(runs[0].run_id(), None);
    }

    /// The history the server recorded for a routine of a Bot on its person's plan, run now and
    /// then due while they switched the relay off and set no fallback (opengrok-server #332 (PR
    /// #338 at 66b9f7b)): two skipped lines, `skipped: "relay_disabled"` with the server's reason.
    fn relay_off_history() -> serde_json::Value {
        recorded_body(include_str!(
            "../fixtures/wire/rest/GET__schedules__id__runs/200-a_plan_bots_routine_is_skipped_while_the_relay_is_off_with_no_fallback.json"
        ))
    }

    /// A routine of a Bot on its person's plan, run now and then due while they switched the
    /// relay off with no fallback, is skipped each time (opengrok-server #332 (PR #338 at
    /// 66b9f7b), as recorded: Run it now is the 409 with `relay_disabled` beside the skip's
    /// sentence, and the history keeps a line for each, `skipped: "relay_disabled"` with its
    /// `reason`). Run it now says the server's sentence and reads the history again, and each
    /// skipped line, Test run's and the schedule's, says the server's reason and opens nothing.
    #[tokio::test]
    async fn a_routine_skipped_while_the_relay_is_off_says_the_servers_reason() {
        let said = "Skipped: Relay is off for your plan";
        let refused = recorded_body(include_str!(
            "../fixtures/wire/rest/POST__schedules__id__run/409-a_plan_bots_routine_is_skipped_while_the_relay_is_off_with_no_fallback.json"
        ));
        assert_eq!(
            refused,
            serde_json::json!({ "error": said, "code": "relay_disabled" })
        );
        let server = wiremock::MockServer::start().await;
        wiremock::Mock::given(wiremock::matchers::method("POST"))
            .and(wiremock::matchers::path("/schedules/sch_1/run"))
            .respond_with(wiremock::ResponseTemplate::new(409).set_body_json(refused))
            .mount(&server)
            .await;
        wiremock::Mock::given(wiremock::matchers::method("GET"))
            .and(wiremock::matchers::path("/schedules/sch_1/runs"))
            .respond_with(wiremock::ResponseTemplate::new(200).set_body_json(relay_off_history()))
            .mount(&server)
            .await;
        let mut state = routines_on(&server);
        let client = state
            .begin_routine_run("cw_1", "sch_1")
            .expect("a run to ask for");
        let result = client.run_schedule_now("sch_1").await;
        assert!(
            state.settle_routine_run("cw_1", "sch_1", result),
            "the history is read again for the skip"
        );
        assert_eq!(state.computer_action_error.as_deref(), Some(said));

        let (client, read) = state
            .begin_routine_runs_read("cw_1", "sch_1")
            .expect("a read");
        let result = client.schedule_runs("sch_1").await;
        assert!(state.settle_routine_runs("cw_1", "sch_1", read, result));
        let runs = &state.routine_mut("cw_1", "sch_1").unwrap().runs;
        let mut causes: Vec<String> = runs.iter().map(|run| run.cause_label()).collect();
        causes.sort_unstable();
        assert_eq!(causes, ["Schedule", "Test run"]);
        for run in runs {
            assert_eq!(
                run.outcome,
                super::RunOutcome::Skipped {
                    reason: said.into()
                }
            );
            assert_eq!(run.run_id(), None, "nothing to open");
        }
    }

    /// On a driver's tree, each line of that history is `routine-{id}-skipped-{atMs}`, by when it
    /// was due as the server recorded it, valued with the server's reason and in state `skipped`.
    #[cfg(feature = "agent")]
    #[test]
    fn a_routine_skipped_while_the_relay_is_off_is_on_a_drivers_tree_in_the_servers_words() {
        use crate::agent::{NativeChatHost, ids};
        use gpui_agent::prelude::AgentHost;
        let lines: Vec<crate::opengrok::ScheduleRun> =
            serde_json::from_value(relay_off_history()).expect("the recorded history");
        let due: Vec<i64> = lines.iter().filter_map(|line| line.at).collect();
        assert_eq!(due.len(), 2);
        let mut state = with_routines();
        state.account = Some(
            serde_json::from_value(serde_json::json!({ "id": "acc_1", "email": "a@example.com" }))
                .expect("an account"),
        );
        state.auth_status = super::AuthStatus::SignedIn;
        state.right_pane = super::RightPane::Computer;
        state.routine_mut("cw_1", "sch_1").unwrap().runs = lines
            .into_iter()
            .map(super::RoutineRun::from_server)
            .collect();
        let tree = NativeChatHost::from_app(&state).snapshot();
        for at_ms in due {
            let line = tree
                .find(&ids::routine_skipped("sch_1", at_ms))
                .expect("the skipped line");
            assert_eq!(
                line.value.as_deref(),
                Some("Skipped: Relay is off for your plan")
            );
            assert!(line.states.iter().any(|state| state == "skipped"));
        }
    }

    /// An edit the server takes is what the routine reads as from then on: its answer, in the
    /// server's six-field form, is the picker's every minute again, nothing is left to send, and a
    /// listing read later (the editor opened again from another Bot) says the same.
    #[tokio::test]
    async fn an_edit_the_server_takes_is_what_the_routine_reads_as_when_opened_again() {
        let saved = serde_json::json!({
            "id": "sch_1", "coworkerId": "cw_1", "kind": "cron", "cron": "0 * * * * *",
            "prompt": "write the weekly report", "name": "Weekly", "active": true
        });
        let server = answers(
            "PATCH",
            "/schedules/sch_1",
            wiremock::ResponseTemplate::new(200).set_body_json(saved.clone()),
        )
        .await;
        let mut state = routines_on(&server);
        if let Some(super::RoutineTrigger::Schedule { spec, .. }) = state
            .routine_mut("cw_1", "sch_1")
            .and_then(|row| row.triggers.first_mut())
        {
            *spec = super::ScheduleSpec::interval(1, super::ScheduleUnit::Minutes);
        }
        let (client, number, edit) = state
            .begin_routine_edit(
                "cw_1",
                "sch_1",
                "Weekly".into(),
                "write the weekly report".into(),
            )
            .expect("an edit to send");
        let result = client.edit_schedule("sch_1", &edit).await;
        assert_eq!(
            state.settle_routine_edit("cw_1", "sch_1", number, edit, result),
            super::AfterRoutineEdit::Nothing
        );
        let label = |routine: &super::AgentRoutine| routine.triggers[0].label();
        let row = state.routine_mut("cw_1", "sch_1").expect("the routine");
        assert_eq!(label(row), "Every 1 minute");
        assert!(super::routine_edit(row).is_empty(), "nothing left to send");
        assert_eq!(state.computer_action_error, None);
        assert!(state.routine_unsaved.is_empty());

        let listed = super::relisted(
            state.routines.get("cw_1").map(Vec::as_slice),
            vec![serde_json::from_value(saved).unwrap()],
        );
        assert_eq!(label(&listed[0]), "Every 1 minute");
    }

    // ---- The account's events stream (hexuria/nativechat #171, opengrok-server #348) --------

    use super::ThreadReread;
    use crate::opengrok::{AccountEvent, EventsNote, EventsTimings, RoutineChange, RunStartCause};

    /// Waits a test can sit through: the stream's own, shortened, with nothing taken off at random.
    fn quick_events() -> EventsTimings {
        EventsTimings {
            quiet: Duration::from_secs(5),
            first_wait: Duration::from_millis(50),
            longest_wait: Duration::from_millis(100),
            jitter: 0.0,
        }
    }

    /// What the account's events stream tells the window, as the window's own stream would.
    fn told(app: &gpui_kit::Entity<AppState>, cx: &mut gpui_kit::TestAppContext, note: EventsNote) {
        app.update(cx, |state, cx| {
            let generation = state.account_events_generation;
            assert!(state.take_events_note(generation, note, cx));
        });
    }

    fn hear(
        app: &gpui_kit::Entity<AppState>,
        cx: &mut gpui_kit::TestAppContext,
        event: AccountEvent,
    ) {
        told(app, cx, EventsNote::Event(event));
    }

    fn thread_changed(thread_id: &str) -> AccountEvent {
        changed_by(thread_id, None)
    }

    /// `thread.changed` for `thread_id`, made by the run `run_id`, or by none.
    fn changed_by(thread_id: &str, run_id: Option<&str>) -> AccountEvent {
        AccountEvent::ThreadChanged {
            thread_id: thread_id.into(),
            coworker_id: "cw_1".into(),
            run_id: run_id.map(str::to_string),
        }
    }

    /// A while in real time for the window to do what it would: long enough for a read it should
    /// not send to have reached the server.
    fn let_it_settle(cx: &mut gpui_kit::TestAppContext) {
        for _ in 0..30 {
            cx.run_until_parked();
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
    }

    /// One run of a thread as `GET /ag-ui/threads/{id}` replays it: the person's message its
    /// prompt held, then the answer, and its end unless it is still going.
    fn replayed(
        run_id: &str,
        status: &str,
        started_at_ms: i64,
        asked: (&str, &str),
        answer: &str,
    ) -> serde_json::Value {
        let mut events = vec![json!({"type": "RUN_STARTED", "runId": run_id, "threadId": "cw_1"})];
        events.extend(persons_frames(asked.0, asked.1));
        let said = format!("{run_id}-a");
        events.extend([
            json!({"type": "TEXT_MESSAGE_START", "messageId": said, "role": "assistant"}),
            json!({"type": "TEXT_MESSAGE_CONTENT", "messageId": said, "delta": answer}),
            json!({"type": "TEXT_MESSAGE_END", "messageId": said}),
        ]);
        if status != "running" {
            events.push(json!({"type": "RUN_FINISHED", "runId": run_id, "threadId": "cw_1"}));
        }
        json!({"runId": run_id, "status": status, "startedAtMs": started_at_ms,
               "updatedAtMs": started_at_ms, "events": events})
    }

    /// The server answers every read of `thread_id` with `runs`, after `delay`.
    async fn thread_reads(
        server: &wiremock::MockServer,
        thread_id: &str,
        runs: serde_json::Value,
        delay: Duration,
    ) {
        wiremock::Mock::given(wiremock::matchers::method("GET"))
            .and(wiremock::matchers::path(format!(
                "/ag-ui/threads/{thread_id}"
            )))
            .respond_with(
                wiremock::ResponseTemplate::new(200)
                    .set_body_json(json!({"threadId": thread_id, "runs": runs}))
                    .set_delay(delay),
            )
            .mount(server)
            .await;
    }

    /// Ada's thread on the server: the turn the window holds, "Hi Ada" answered "Hello." as
    /// `run_1`, and a turn the window never saw, started by the server, as `run_2`.
    fn adas_thread_with_a_new_turn() -> serde_json::Value {
        json!([
            replayed("run_1", "finished", 1_000, ("m_q1", "Hi Ada"), "Hello."),
            replayed(
                "run_2",
                "finished",
                2_000,
                ("m_q2", "Post the standup"),
                "Posted the standup."
            ),
        ])
    }

    /// A window signed in to `server`, Ada (`cw_1`) open on her thread, holding the turn her
    /// thread's `run_1` is.
    fn ada_open(
        cx: &mut gpui_kit::TestAppContext,
        runtime: &tokio::runtime::Runtime,
        server: &wiremock::MockServer,
    ) -> gpui_kit::Entity<AppState> {
        use gpui_kit::AppContext as _;
        let mut state = signed_in_state();
        state.opengrok = Some(runtime.block_on(client_signed_in_to(server)));
        with_bot(&mut state, json!("gateway"));
        state.conversations.push(thread(
            "cw_1",
            vec![
                at(message("m_q1", true, "Hi Ada"), 1_000),
                from_run("m_r1", "Hello.", "run_1", 1_100),
            ],
        ));
        state.active_conversation_id = Some("cw_1".into());
        cx.new(|_| state)
    }

    /// Every re-read the stream asked for has landed, both of its reads. A test that asked for
    /// one waits for this before it ends: a read still out when the test's runtime is gone has
    /// nothing to land on.
    fn rereads_landed(app: &gpui_kit::Entity<AppState>, cx: &mut gpui_kit::TestAppContext) -> bool {
        app.read_with(cx, |state, _| {
            state.thread_rereads.values().all(|reread| !reread.reading)
                && !state.routines_reread_in_flight
        })
    }

    /// The read the stream asked for in `thread_id`, as the window holds it. A note is dealt with
    /// where it is heard, so a test that has not let the window run since can say what became of
    /// it without waiting, in real time, to see whether a read follows: a machine slow enough to
    /// outrun the wait fails a test that was right.
    fn held_read(
        app: &gpui_kit::Entity<AppState>,
        cx: &mut gpui_kit::TestAppContext,
        thread_id: &str,
    ) -> Option<ThreadReread> {
        app.read_with(cx, |state, _| state.thread_rereads.get(thread_id).copied())
    }

    fn said(app: &gpui_kit::Entity<AppState>, cx: &mut gpui_kit::TestAppContext) -> Vec<String> {
        app.read_with(cx, |state, _| {
            state.conversations[0]
                .messages
                .iter()
                .map(|message| message.content.clone())
                .collect()
        })
    }

    /// A turn the server started in the open thread, which this window did not send (a routine's
    /// Test run, a Bot's `run_routine`, another device), is in the thread as soon as the account's
    /// events stream says the thread changed: it is read again once, and the person's message and
    /// the reply both show, with nobody leaving the thread and coming back (hexuria/nativechat#171,
    /// bug B). A thread nobody has open is not read: it is read when it is opened.
    #[gpui_kit::test]
    fn a_turn_the_server_started_shows_in_the_open_thread_when_the_stream_says_so(
        cx: &mut gpui_kit::TestAppContext,
    ) {
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let server = runtime.block_on(wiremock::MockServer::start());
        runtime.block_on(thread_reads(
            &server,
            "cw_1",
            adas_thread_with_a_new_turn(),
            Duration::ZERO,
        ));
        let app = ada_open(cx, &runtime, &server);
        hear(&app, cx, thread_changed("cw_2"));
        hear(&app, cx, thread_changed("cw_1"));
        wait_for(cx, "the server's turn is in the open thread", |cx| {
            said(&app, cx)
                == [
                    "Hi Ada",
                    "Hello.",
                    "Post the standup",
                    "Posted the standup.",
                ]
        });
        let_it_settle(cx);
        assert_eq!(asked_for(&runtime, &server, "/ag-ui/threads/cw_1"), 1);
        assert_eq!(asked_for(&runtime, &server, "/ag-ui/threads/cw_2"), 0);
    }

    /// Notes come in bursts (the server sends one at each commit, up to about two a second a
    /// thread, and a run sends several): the open thread is read once with one read out, and once
    /// more after it for every note that came meanwhile, never once a note.
    #[gpui_kit::test]
    fn a_burst_of_notes_reads_the_open_thread_once_and_once_more_after(
        cx: &mut gpui_kit::TestAppContext,
    ) {
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let server = runtime.block_on(wiremock::MockServer::start());
        runtime.block_on(thread_reads(
            &server,
            "cw_1",
            adas_thread_with_a_new_turn(),
            Duration::from_millis(300),
        ));
        let app = ada_open(cx, &runtime, &server);
        for _ in 0..5 {
            hear(&app, cx, thread_changed("cw_1"));
        }
        hear(
            &app,
            cx,
            AccountEvent::RunFinished {
                run_id: "run_2".into(),
                thread_id: "cw_1".into(),
                coworker_id: "cw_1".into(),
                routine_id: None,
                state: "ok".into(),
            },
        );
        wait_for(
            cx,
            "the thread is read again once the first read lands",
            |_| asked_for(&runtime, &server, "/ag-ui/threads/cw_1") == 2,
        );
        let_it_settle(cx);
        std::thread::sleep(std::time::Duration::from_millis(400));
        let_it_settle(cx);
        assert_eq!(asked_for(&runtime, &server, "/ag-ui/threads/cw_1"), 2);
        assert_eq!(
            said(&app, cx),
            [
                "Hi Ada",
                "Hello.",
                "Post the standup",
                "Posted the standup."
            ],
            "and the turn is in it once"
        );
    }

    /// While this window's own turn streams in the open thread, what the stream says about the
    /// thread waits: a read then could paint over the turn being watched. Once the turn's stream
    /// ends, the thread is read once, and both the turn and the server's are in it.
    ///
    /// Nothing here waits for a clock. The server answers the turn at once, and the note is heard
    /// before the window is let run, so the turn is streaming however quick the answer is: what
    /// became of the note is read off the window. This test once held the answer back for 700 ms
    /// and looked at the server after 300, and a runner slow enough to take longer than that
    /// found the turn over and the thread read, as it should have been.
    #[gpui_kit::test]
    fn notes_while_the_windows_own_turn_streams_wait_for_it_to_end(
        cx: &mut gpui_kit::TestAppContext,
    ) {
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let server = runtime.block_on(wiremock::MockServer::start());
        let frames: String = [
            json!({"type": "RUN_STARTED", "threadId": "cw_1", "runId": "run_own"}),
            json!({"type": "TEXT_MESSAGE_START", "messageId": "m_said", "role": "assistant"}),
            json!({"type": "TEXT_MESSAGE_CONTENT", "messageId": "m_said", "delta": "Sure."}),
            json!({"type": "TEXT_MESSAGE_END", "messageId": "m_said"}),
            json!({"type": "RUN_FINISHED", "threadId": "cw_1", "runId": "run_own"}),
        ]
        .iter()
        .map(|frame| format!("data: {frame}\n\n"))
        .collect();
        runtime.block_on(async {
            wiremock::Mock::given(wiremock::matchers::method("POST"))
                .and(wiremock::matchers::path("/ag-ui"))
                .respond_with(
                    wiremock::ResponseTemplate::new(200)
                        .insert_header("content-type", "text/event-stream")
                        .set_body_string(frames),
                )
                .mount(&server)
                .await;
            thread_reads(
                &server,
                "cw_1",
                adas_thread_with_a_new_turn(),
                Duration::ZERO,
            )
            .await;
        });
        let app = ada_open(cx, &runtime, &server);
        app.update(cx, |state, cx| {
            state.send_message("Anything new?".into(), cx)
        });
        hear(&app, cx, thread_changed("cw_1"));
        assert!(
            app.read_with(cx, |state, _| state.is_turn_in_flight()),
            "the turn is streaming"
        );
        assert_eq!(
            held_read(&app, cx, "cw_1"),
            Some(ThreadReread {
                reading: false,
                owed: true
            }),
            "nothing is read while the turn streams: the note waits for its end"
        );
        wait_for(cx, "the turn ends, and the thread is read", |cx| {
            app.read_with(cx, |state, _| !state.is_turn_in_flight())
                && asked_for(&runtime, &server, "/ag-ui/threads/cw_1") == 1
        });
        wait_for(cx, "the turn's reply and the server's turn", |cx| {
            let said = said(&app, cx);
            said.iter().any(|line| line == "Sure.")
                && said.iter().any(|line| line == "Posted the standup.")
        });
        let_it_settle(cx);
        assert_eq!(asked_for(&runtime, &server, "/ag-ui/threads/cw_1"), 1);
    }

    /// The stream tells every connection of the account about every run, this window's own among
    /// them: a run this window started, and watched down the stream it started it on, is no news,
    /// and reads nothing. Somebody else's run in the open thread does.
    #[gpui_kit::test]
    fn the_windows_own_runs_are_no_news(cx: &mut gpui_kit::TestAppContext) {
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let server = runtime.block_on(wiremock::MockServer::start());
        runtime.block_on(thread_reads(
            &server,
            "cw_1",
            adas_thread_with_a_new_turn(),
            Duration::ZERO,
        ));
        let app = ada_open(cx, &runtime, &server);
        app.update(cx, |state, _| state.note_own_run("run_mine"));
        let run = |run_id: &str, ended: bool| {
            if ended {
                AccountEvent::RunFinished {
                    run_id: run_id.into(),
                    thread_id: "cw_1".into(),
                    coworker_id: "cw_1".into(),
                    routine_id: None,
                    state: "ok".into(),
                }
            } else {
                AccountEvent::RunStarted {
                    run_id: run_id.into(),
                    thread_id: "cw_1".into(),
                    coworker_id: "cw_1".into(),
                    routine_id: None,
                    cause: RunStartCause::Chat,
                }
            }
        };
        hear(&app, cx, run("run_mine", false));
        hear(&app, cx, run("run_mine", true));
        let_it_settle(cx);
        assert_eq!(asked_for(&runtime, &server, "/ag-ui/threads/cw_1"), 0);
        hear(&app, cx, run("run_2", true));
        wait_for(cx, "somebody else's run is read", |_| {
            asked_for(&runtime, &server, "/ag-ui/threads/cw_1") == 1
        });
        wait_for(cx, "and the read lands", |cx| rereads_landed(&app, cx));
        let_it_settle(cx);
    }

    /// A change to the open thread made by a run the window watches itself, its own turn or a run
    /// it is following, is no news: the window is painting what that run wrote, so the thread is
    /// not read again for it, neither while the run goes nor once it has ended.
    #[gpui_kit::test]
    fn a_change_the_windows_own_run_made_reads_nothing(cx: &mut gpui_kit::TestAppContext) {
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let server = runtime.block_on(wiremock::MockServer::start());
        runtime.block_on(thread_reads(
            &server,
            "cw_1",
            adas_thread_with_a_new_turn(),
            Duration::ZERO,
        ));
        let app = ada_open(cx, &runtime, &server);
        app.update(cx, |state, _| {
            state.note_own_run("run_mine");
            state.turn_stream_began("cw_1", "run_mine");
        });
        hear(&app, cx, changed_by("cw_1", Some("run_mine")));
        app.update(cx, |state, cx| {
            state.turn_stream_ended("cw_1", "run_mine", cx)
        });
        hear(&app, cx, changed_by("cw_1", Some("run_mine")));
        app.update(cx, |state, _| {
            state.turn_stream_began("cw_1", "run_followed")
        });
        hear(&app, cx, changed_by("cw_1", Some("run_followed")));
        app.update(cx, |state, cx| {
            state.turn_stream_ended("cw_1", "run_followed", cx)
        });
        let_it_settle(cx);
        assert_eq!(asked_for(&runtime, &server, "/ag-ui/threads/cw_1"), 0);
    }

    /// A change no run made (`runId` null: a card the person settled, or notes the server merged
    /// that disagree), or one another run made, is read: while the window's own turn streams, once
    /// it has ended, in one read for both; and at once when nothing streams.
    #[gpui_kit::test]
    fn a_change_no_run_or_another_run_made_is_read(cx: &mut gpui_kit::TestAppContext) {
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let server = runtime.block_on(wiremock::MockServer::start());
        runtime.block_on(thread_reads(
            &server,
            "cw_1",
            adas_thread_with_a_new_turn(),
            Duration::ZERO,
        ));
        let app = ada_open(cx, &runtime, &server);
        app.update(cx, |state, _| {
            state.note_own_run("run_mine");
            state.turn_stream_began("cw_1", "run_mine");
        });
        hear(&app, cx, changed_by("cw_1", None));
        hear(&app, cx, changed_by("cw_1", Some("run_2")));
        let_it_settle(cx);
        assert_eq!(asked_for(&runtime, &server, "/ag-ui/threads/cw_1"), 0);
        app.update(cx, |state, cx| {
            state.turn_stream_ended("cw_1", "run_mine", cx)
        });
        wait_for(cx, "read once the turn has ended", |cx| {
            asked_for(&runtime, &server, "/ag-ui/threads/cw_1") == 1 && rereads_landed(&app, cx)
        });
        hear(&app, cx, changed_by("cw_1", Some("run_3")));
        wait_for(cx, "another run's change is read at once", |cx| {
            asked_for(&runtime, &server, "/ag-ui/threads/cw_1") == 2 && rereads_landed(&app, cx)
        });
        hear(&app, cx, changed_by("cw_1", None));
        wait_for(cx, "and one no run made", |cx| {
            asked_for(&runtime, &server, "/ag-ui/threads/cw_1") == 3 && rereads_landed(&app, cx)
        });
        let_it_settle(cx);
    }

    /// A run parked on a card has not ended, and the server sends only `thread.changed` for it,
    /// never `run.finished`. Nothing waits for one: a read the stream asked for while the window's
    /// own turn streamed, or while it followed a run, goes when that stream or that follow ends
    /// with the run parked.
    ///
    /// As in [`notes_while_the_windows_own_turn_streams_wait_for_it_to_end`], the note is heard
    /// before the window is let run, so the stream and the follow are open whatever the server
    /// has answered, and nothing waits for a clock to find out what became of it.
    #[gpui_kit::test]
    fn a_run_parked_on_a_card_lets_the_waiting_read_go_with_no_run_finished(
        cx: &mut gpui_kit::TestAppContext,
    ) {
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let server = runtime.block_on(wiremock::MockServer::start());
        let card = |run: &str| {
            json!({"type": "CUSTOM", "name": "run-awaiting-approval", "threadId": "cw_1",
                   "runId": run, "callId": format!("call-{run}"), "tool": "delete_routine",
                   "arguments": {"routine": "sched_1"}, "reason": "policy-approval",
                   "why": "Delete the routine \"Standup\"? It stops for good.",
                   "summary": "Delete the routine sched_1"})
        };
        let parked: String = [
            json!({"type": "RUN_STARTED", "threadId": "cw_1", "runId": "run_own"}),
            card("run_own"),
        ]
        .iter()
        .map(|frame| format!("data: {frame}\n\n"))
        .collect();
        let replay = |status: &str| {
            let mut events = vec![json!({"type": "RUN_STARTED", "runId": "run_park"})];
            if status == "awaiting-approval" {
                events.push(card("run_park"));
            }
            json!({"runId": "run_park", "status": status,
                   "startedAtMs": 1_790_000_000_000_i64, "events": events})
        };
        runtime.block_on(async {
            wiremock::Mock::given(wiremock::matchers::method("POST"))
                .and(wiremock::matchers::path("/ag-ui"))
                .respond_with(
                    wiremock::ResponseTemplate::new(200)
                        .insert_header("content-type", "text/event-stream")
                        .set_body_string(parked),
                )
                .mount(&server)
                .await;
            wiremock::Mock::given(wiremock::matchers::method("GET"))
                .and(wiremock::matchers::path("/ag-ui/runs/run_park"))
                .respond_with(wiremock::ResponseTemplate::new(200).set_body_json(replay("running")))
                .up_to_n_times(2)
                .mount(&server)
                .await;
            wiremock::Mock::given(wiremock::matchers::method("GET"))
                .and(wiremock::matchers::path("/ag-ui/runs/run_park"))
                .respond_with(
                    wiremock::ResponseTemplate::new(200).set_body_json(replay("awaiting-approval")),
                )
                .mount(&server)
                .await;
            thread_reads(
                &server,
                "cw_1",
                adas_thread_with_a_new_turn(),
                Duration::ZERO,
            )
            .await;
        });
        let app = ada_open(cx, &runtime, &server);
        app.update(cx, |state, cx| {
            state.send_message("Delete my standup".into(), cx)
        });
        hear(&app, cx, thread_changed("cw_1"));
        assert_eq!(
            held_read(&app, cx, "cw_1"),
            Some(ThreadReread {
                reading: false,
                owed: true
            }),
            "nothing is read while the turn streams: the note waits for its end"
        );
        wait_for(cx, "the turn parks, and the thread is read", |cx| {
            asked_for(&runtime, &server, "/ag-ui/threads/cw_1") == 1 && rereads_landed(&app, cx)
        });

        app.update(cx, |state, cx| {
            state.follow_run("run_park".into(), Some("cw_1".into()), cx)
        });
        hear(&app, cx, thread_changed("cw_1"));
        assert_eq!(
            held_read(&app, cx, "cw_1"),
            Some(ThreadReread {
                reading: false,
                owed: true
            }),
            "nothing is read while the run is followed: the note waits for the follow's end"
        );
        wait_for(cx, "the followed run parks, and the thread is read", |cx| {
            asked_for(&runtime, &server, "/ag-ui/threads/cw_1") == 2 && rereads_landed(&app, cx)
        });
        let_it_settle(cx);
    }

    /// A turn the open thread still holds, whose run nothing follows any more (its follow gave up
    /// on a long run), is brought to its end when the stream says the run ended, the way coming
    /// back to the thread brings it: from the run's own replay.
    #[gpui_kit::test]
    fn a_held_turn_whose_run_ends_unwatched_is_brought_to_its_end(
        cx: &mut gpui_kit::TestAppContext,
    ) {
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let server = runtime.block_on(wiremock::MockServer::start());
        let done = replayed(
            "run_7",
            "finished",
            2_000,
            ("m_q7", "Check the box"),
            "All done.",
        );
        runtime.block_on(async {
            wiremock::Mock::given(wiremock::matchers::method("GET"))
                .and(wiremock::matchers::path("/ag-ui/runs/run_7"))
                .respond_with(wiremock::ResponseTemplate::new(200).set_body_json(done.clone()))
                .mount(&server)
                .await;
            thread_reads(&server, "cw_1", json!([done]), Duration::ZERO).await;
        });
        let app = ada_open(cx, &runtime, &server);
        app.update(cx, |state, _| {
            let messages = &mut state.conversations[0].messages;
            messages.push(at(message("m_q7", true, "Check the box"), 1_900));
            messages.push(from_run("m_live", "Working on it", "run_7", 2_000));
            state.live_turns.insert(
                "cw_1".into(),
                LiveTurn {
                    run_id: "run_7".into(),
                    message_id: "m_live".into(),
                    persisting: false,
                },
            );
        });
        hear(
            &app,
            cx,
            AccountEvent::RunFinished {
                run_id: "run_7".into(),
                thread_id: "cw_1".into(),
                coworker_id: "cw_1".into(),
                routine_id: None,
                state: "ok".into(),
            },
        );
        wait_for(cx, "the held turn reads as it ended", |cx| {
            said(&app, cx).last().map(String::as_str) == Some("All done.")
        });
        assert!(asked_for(&runtime, &server, "/ag-ui/runs/run_7") >= 1);
        wait_for(cx, "the thread's own read lands", |cx| {
            rereads_landed(&app, cx)
        });
        let_it_settle(cx);
    }

    /// A run a Bot or the clock starts (or ends) in one of Ada's routines shows in that routine's
    /// open Run history at once (hexuria/nativechat#171, bug A): the stream's note names the
    /// routine, and its history is read again while its panel is open. With the panel shut, it is
    /// read when the panel opens. The routine's thread, not the open one, is not read.
    #[gpui_kit::test]
    fn a_run_in_a_routine_whose_panel_is_open_reads_its_history_again(
        cx: &mut gpui_kit::TestAppContext,
    ) {
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let server = runtime.block_on(wiremock::MockServer::start());
        runtime.block_on(
            wiremock::Mock::given(wiremock::matchers::method("GET"))
                .and(wiremock::matchers::path("/schedules/sched_1/runs"))
                .respond_with(wiremock::ResponseTemplate::new(200).set_body_json(json!([{
                    "runId": "run_bot", "cause": "bot", "status": "ok",
                    "startedAtMs": 1_790_000_000_000_i64, "endedAtMs": 1_790_000_001_000_i64,
                    "by": {"coworkerId": "cw_1", "name": "Ada"}
                }])))
                .mount(&server),
        );
        let standup = adas_schedule("sched_1", "Standup");
        let routine = super::routine_from_schedule(
            serde_json::from_value(standup.clone()).expect("a routine"),
        );
        let app = adas_window(cx, &runtime, &server, &[], json!([standup]), vec![routine]);
        app.update(cx, |state, _| {
            state.right_pane = super::RightPane::Computer;
            state.computer_view = super::ComputerView::Editor {
                id: Some("sched_1".into()),
            };
            state.routine_history_open = true;
        });
        let run = |ended: bool| {
            let (run_id, thread_id, coworker_id, routine_id) = (
                "run_bot".to_string(),
                "sched_1".to_string(),
                "cw_1".to_string(),
                Some("sched_1".to_string()),
            );
            if ended {
                AccountEvent::RunFinished {
                    run_id,
                    thread_id,
                    coworker_id,
                    routine_id,
                    state: "ok".into(),
                }
            } else {
                AccountEvent::RunStarted {
                    run_id,
                    thread_id,
                    coworker_id,
                    routine_id,
                    cause: RunStartCause::Bot,
                }
            }
        };
        hear(&app, cx, run(true));
        wait_for(cx, "the Bot's run is in the open history", |cx| {
            app.read_with(cx, |state, _| {
                state.coworker_routines("cw_1").iter().any(|routine| {
                    routine
                        .runs
                        .iter()
                        .any(|run| run.run_id() == Some("run_bot"))
                })
            })
        });
        app.update(cx, |state, _| state.right_pane = super::RightPane::Closed);
        hear(&app, cx, run(false));
        let_it_settle(cx);
        assert_eq!(asked_for(&runtime, &server, "/schedules/sched_1/runs"), 1);
        assert_eq!(asked_for(&runtime, &server, "/ag-ui/threads/sched_1"), 0);
    }

    /// A routine of the open Bot's made, renamed or deleted anywhere (a Bot of another Bot's, the
    /// web console, another device) is on the Routines list at once: the stream's note reads the
    /// list again by the road a Bot's own routine call takes, so a deleted routine's open panel
    /// closes back to the list, and a field being typed in keeps what is typed. Another Bot's
    /// routines are read when that Bot is opened.
    #[gpui_kit::test]
    fn a_routine_changed_elsewhere_is_on_the_open_bots_list_at_once(
        cx: &mut gpui_kit::TestAppContext,
    ) {
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let server = runtime.block_on(wiremock::MockServer::start());
        let app = adas_window(
            cx,
            &runtime,
            &server,
            &[],
            json!([adas_schedule("sched_new", "Standup")]),
            Vec::new(),
        );
        let changed = |coworker_id: &str, change| AccountEvent::RoutineChanged {
            routine_id: "sched_new".into(),
            coworker_id: coworker_id.into(),
            change,
        };
        hear(&app, cx, changed("cw_2", RoutineChange::Created));
        let_it_settle(cx);
        assert_eq!(
            asked_for(&runtime, &server, "/schedules"),
            0,
            "another Bot's"
        );
        hear(&app, cx, changed("cw_1", RoutineChange::Created));
        wait_for(cx, "the routine made elsewhere is listed", |cx| {
            app.read_with(cx, |state, _| {
                state
                    .coworker_routines("cw_1")
                    .iter()
                    .any(|routine| routine.id == "sched_new" && routine.name == "Standup")
            })
        });
        assert_eq!(asked_for(&runtime, &server, "/schedules"), 1);

        let server = runtime.block_on(wiremock::MockServer::start());
        let routine = super::routine_from_schedule(
            serde_json::from_value(adas_schedule("sched_1", "Standup")).expect("a routine"),
        );
        let app = adas_window(cx, &runtime, &server, &[], json!([]), vec![routine]);
        app.update(cx, |state, _| {
            state.right_pane = super::RightPane::Computer;
            state.computer_view = super::ComputerView::Editor {
                id: Some("sched_1".into()),
            };
        });
        hear(
            &app,
            cx,
            AccountEvent::RoutineChanged {
                routine_id: "sched_1".into(),
                coworker_id: "cw_1".into(),
                change: RoutineChange::Deleted,
            },
        );
        wait_for(cx, "the deleted routine's panel closes", |cx| {
            app.read_with(cx, |state, _| {
                state.coworker_routines("cw_1").is_empty()
                    && state.computer_view == super::ComputerView::Overview
            })
        });
    }

    /// Nothing says what the stream missed while it was not open, so every time it opens, and
    /// whenever the server could not resume it (`reset`), what it covers on screen is read again
    /// once: the open thread, the open Bot's Routines list, and the open routine's history.
    #[gpui_kit::test]
    fn the_stream_opening_and_a_reset_read_what_is_on_screen_again(
        cx: &mut gpui_kit::TestAppContext,
    ) {
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let server = runtime.block_on(wiremock::MockServer::start());
        runtime.block_on(async {
            thread_reads(
                &server,
                "cw_1",
                json!([replayed(
                    "run_1",
                    "finished",
                    1_000,
                    ("m_q1", "Hi Ada"),
                    "Hello."
                )]),
                Duration::ZERO,
            )
            .await;
            wiremock::Mock::given(wiremock::matchers::method("GET"))
                .and(wiremock::matchers::path("/schedules/sched_1/runs"))
                .respond_with(wiremock::ResponseTemplate::new(200).set_body_json(json!([])))
                .mount(&server)
                .await;
        });
        let standup = adas_schedule("sched_1", "Standup");
        let routine = super::routine_from_schedule(
            serde_json::from_value(standup.clone()).expect("a routine"),
        );
        let app = adas_window(cx, &runtime, &server, &[], json!([standup]), vec![routine]);
        app.update(cx, |state, _| {
            state.right_pane = super::RightPane::Computer;
            state.computer_view = super::ComputerView::Editor {
                id: Some("sched_1".into()),
            };
        });
        let (runtime, server) = (&runtime, &server);
        let read = |times: usize| {
            move |_: &mut gpui_kit::TestAppContext| {
                [
                    "/ag-ui/threads/cw_1",
                    "/schedules",
                    "/schedules/sched_1/runs",
                ]
                .iter()
                .all(|at| asked_for(runtime, server, at) == times)
            }
        };
        told(&app, cx, EventsNote::Opened);
        assert_eq!(
            app.read_with(cx, |state, _| state.events_stream),
            super::EventsStream::Connected
        );
        wait_for(cx, "the thread, the list and the history are read", read(1));
        hear(&app, cx, AccountEvent::Reset);
        wait_for(cx, "and read again after a reset", read(2));
        told(&app, cx, EventsNote::Lost);
        assert_eq!(
            app.read_with(cx, |state, _| state.events_stream),
            super::EventsStream::Reconnecting
        );
        wait_for(cx, "the reads land", |cx| rereads_landed(&app, cx));
        let_it_settle(cx);
    }

    /// The stream is opened with the session's bearer when somebody signs in, kept open (opened
    /// again after it drops), and stops when they sign out: nothing knocks on it for an account
    /// nobody is signed in as.
    #[gpui_kit::test]
    fn the_stream_starts_when_somebody_signs_in_and_stops_when_they_sign_out(
        cx: &mut gpui_kit::TestAppContext,
    ) {
        use base64::Engine as _;
        use gpui_kit::AppContext as _;
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let server = runtime.block_on(wiremock::MockServer::start());
        let part = |json: &str| base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(json);
        let token = format!(
            "{}.{}.not-a-signature",
            part(r#"{"alg":"HS256","typ":"JWT"}"#),
            part(r#"{"exp":4102444800}"#)
        );
        runtime.block_on(async {
            wiremock::Mock::given(wiremock::matchers::method("POST"))
                .and(wiremock::matchers::path("/auth/login"))
                .respond_with(
                    wiremock::ResponseTemplate::new(200)
                        .append_header("set-cookie", format!("og_access={token}; Path=/"))
                        .set_body_json(json!({})),
                )
                .mount(&server)
                .await;
            wiremock::Mock::given(wiremock::matchers::method("GET"))
                .and(wiremock::matchers::path("/account"))
                .respond_with(
                    wiremock::ResponseTemplate::new(200)
                        .set_body_json(json!({"id": "acc_1", "email": "ada@example.com"})),
                )
                .mount(&server)
                .await;
            // A stream that ends as soon as it opens, so a running one is opened again and again.
            wiremock::Mock::given(wiremock::matchers::method("GET"))
                .and(wiremock::matchers::path("/ag-ui/events"))
                .respond_with(
                    wiremock::ResponseTemplate::new(200).set_body_raw("", "text/event-stream"),
                )
                .mount(&server)
                .await;
        });
        let mut state = AppState::new();
        state.opengrok = Some(OpenGrokClient::new(&server.uri()).expect("a URL"));
        state.events_timings = quick_events();
        let app = cx.new(|_| state);
        let opened = || asked_for(&runtime, &server, "/ag-ui/events");
        let_it_settle(cx);
        assert_eq!(opened(), 0, "nobody is signed in");
        app.update(cx, |state, cx| {
            state.login("ada@example.com".into(), "pw".into(), cx)
        });
        wait_for(cx, "the stream is opened, and opened again", |_| {
            opened() >= 2
        });
        let first = runtime
            .block_on(server.received_requests())
            .expect("the recorder is on")
            .into_iter()
            .find(|request| request.url.path() == "/ag-ui/events")
            .expect("the stream");
        assert_eq!(
            first.headers.get("authorization").unwrap(),
            format!("Bearer {token}").as_str()
        );
        app.update(cx, |state, cx| state.logout(cx));
        assert_eq!(
            app.read_with(cx, |state, _| state.events_stream),
            super::EventsStream::Off
        );
        let_it_settle(cx);
        let after = opened();
        std::thread::sleep(std::time::Duration::from_millis(400));
        let_it_settle(cx);
        assert_eq!(opened(), after, "not opened again once signed out");
    }

    /// A stream the server refuses `401` is not knocked on again with the same session: the
    /// session's refresh is asked first, and when the server refuses that too, the window says the
    /// session is gone, as any other `401` makes it say, and the stream stops until somebody signs
    /// in again.
    #[gpui_kit::test]
    fn a_stream_refused_after_the_sessions_refresh_asks_for_a_sign_in(
        cx: &mut gpui_kit::TestAppContext,
    ) {
        let runtime = a_runtime_for_the_relay(cx);
        let _enter = runtime.enter();
        let server = runtime.block_on(wiremock::MockServer::start());
        runtime.block_on(async {
            wiremock::Mock::given(wiremock::matchers::method("GET"))
                .and(wiremock::matchers::path("/ag-ui/events"))
                .respond_with(
                    wiremock::ResponseTemplate::new(401)
                        .set_body_json(json!({"error": "session expired"})),
                )
                .mount(&server)
                .await;
            wiremock::Mock::given(wiremock::matchers::method("POST"))
                .and(wiremock::matchers::path("/auth/refresh"))
                .respond_with(
                    wiremock::ResponseTemplate::new(401)
                        .set_body_json(json!({"error": "session expired"})),
                )
                .mount(&server)
                .await;
        });
        let app = ada_open(cx, &runtime, &server);
        app.update(cx, |state, cx| {
            state.events_timings = quick_events();
            state.start_events_stream(cx);
        });
        wait_for(cx, "the window says the session is gone", |cx| {
            app.read_with(cx, |state, _| {
                state.is_session_expired() && state.events_stream == super::EventsStream::SignedOut
            })
        });
        assert!(
            asked_for(&runtime, &server, "/auth/refresh") >= 1,
            "refreshed first"
        );
        let opened = asked_for(&runtime, &server, "/ag-ui/events");
        std::thread::sleep(std::time::Duration::from_millis(300));
        let_it_settle(cx);
        assert_eq!(asked_for(&runtime, &server, "/ag-ui/events"), opened);
    }

    // ---- Stopping a turn --------------------------------------------------------------------

    /// A thread with a turn in flight in it, the way `send_opengrok_turn` leaves one: the row the
    /// run is filling in, the run registered against the thread, and the bot marked as working.
    fn mid_turn(reply: Message) -> AppState {
        let mut state = AppState::new();
        state.conversations.push(thread(
            "cw_1",
            vec![at(message("m_ask", true, "open youtube"), 10), reply],
        ));
        state.active_conversation_id = Some("cw_1".to_string());
        state.active_coworker_id = Some("cw_1".to_string());
        state.live_turns.insert("cw_1".to_string(), in_flight());
        state.begin_responding(Some("cw_1"), "Working");
        state
    }

    /// The composer's button is a stop button for exactly as long as there is something to stop,
    /// which is the whole of what it promises.
    #[test]
    fn the_button_is_a_stop_button_while_the_turn_runs_and_a_send_arrow_at_every_ending() {
        let mut state = mid_turn(at(message("m_live", false, ""), 20));
        assert!(
            state.is_turn_in_flight(),
            "the turn was sent and is registered against the thread"
        );

        // An ordinary ending: `persist_assistant_reply` marks the turn the moment it takes the
        // reply, and the thread stays registered only until that write lands.
        state.live_turns.get_mut("cw_1").unwrap().persisting = true;
        assert!(
            !state.is_turn_in_flight(),
            "the outcome is decided, so there is nothing left running to stop"
        );

        // A run that failed leaves the app's own words behind, which are never written down, so
        // the thread is let go on the spot instead.
        state.live_turns.insert("cw_1".to_string(), in_flight());
        state.release_live_turn("cw_1", "run_1");
        assert!(!state.is_turn_in_flight());

        // And a turn running in the thread next door is not this thread's to stop.
        state.live_turns.insert("cw_2".to_string(), in_flight());
        assert!(
            !state.is_turn_in_flight(),
            "the live turn is kept per thread, which is what makes it worth asking"
        );
        assert!(
            state.turn_to_stop().is_none(),
            "so a stop pressed here finds nothing, rather than stopping somebody else's turn"
        );
    }

    /// Clearing the working line is NOT an ending, and the composer is where the difference shows.
    ///
    /// THIS IS THE PAIR A PERSON REPORTED AS A BUG on 18 Sep 2026: they denied a command, no
    /// coworker was thinking any more — and the send button was still a stop button. The denial
    /// path had reached for `finish_responding` as though it ended the turn. It does not: it
    /// takes away the line that says somebody is working, and leaves the turn registered against
    /// the thread, which is the fact the button is drawn from.
    ///
    /// Both real endings do more than this — `persist_assistant_reply` marks the turn while the
    /// reply goes to disk, `release_live_turn` lets go of a turn with nothing to write down — so
    /// this test is here to say that the third thing, on its own, is neither.
    #[test]
    fn clearing_the_working_line_does_not_let_go_of_the_turn() {
        let mut state = mid_turn(at(message("m_live", false, ""), 20));
        assert_eq!(state.thread_status("cw_1"), Some("Working"));

        state.finish_responding(Some("cw_1"), false);
        assert_eq!(
            state.thread_status("cw_1"),
            None,
            "nothing looks busy in the thread any more"
        );
        assert!(
            state.is_turn_in_flight(),
            "but the turn is still this thread's, so the composer still offers to stop it — \
             which is exactly the pair that reads as a bug: no coworker working, and a stop \
             button over it"
        );

        // Waiting on a card is the one time the two are meant to differ, and it says so rather
        // than falling silent: the turn is genuinely still in flight, stopped on a person.
        state.finish_responding(Some("cw_1"), true);
        assert_eq!(state.thread_status("cw_1"), Some(WAITING_APPROVAL_STATUS));
        assert!(state.is_turn_in_flight());

        // And an ending is what lets the button go back to a send arrow.
        state.release_live_turn("cw_1", "run_1");
        assert!(!state.is_turn_in_flight());
    }

    #[test]
    fn finished_user_form_wait_drops_stop_and_keeps_waiting_chrome() {
        let spec = crate::opengrok::UserFormSpec::from_custom_event(&serde_json::json!({
            "type": "CUSTOM",
            "name": "run-awaiting-approval",
            "callId": "call-9",
            "entryId": "e_form",
            "reason": "user-form",
            "arguments": {
                "title": "Google account",
                "fields": [{"id": "email", "label": "Email", "type": "email", "required": true}]
            }
        }))
        .unwrap();
        let mut bot = message("m_live", false, "");
        bot.parts = vec![ChatPart::UserForm(spec)];
        let mut state = mid_turn(at(bot, 20));
        assert!(state.is_turn_in_flight());

        state.park_waiting_for_you("cw_1", "run_1");

        assert_eq!(
            state.visible_bot_status().as_deref(),
            Some(WAITING_FOR_YOU_STATUS)
        );
        assert_eq!(
            bot_status_line("Grok", WAITING_FOR_YOU_STATUS),
            "Waiting for you"
        );
        assert_eq!(bot_status_line("Grok", "Working"), "Grok is working");
        assert_eq!(
            bot_status_line("Vamos", crate::opengrok::WAKING_COMPUTER),
            "Waking Vamos's computer",
            "the wait for the box is named, not folded into working"
        );
        assert!(
            !state.is_turn_in_flight(),
            "server run is finished; composer is Send, not Stop"
        );
        assert!(state.turn_to_stop().is_none());
        assert!(
            !state.live_turns.contains_key("cw_1"),
            "do not keep a local live-turn past the run"
        );
        assert_eq!(state.open_user_forms().len(), 1);
    }

