    /// A cancel before the sqlite write lands is written down hidden, not as a live row.
    #[test]
    fn a_cancel_before_the_row_is_written_is_persisted_hidden() {
        let mut state = holding("m_held", "wait for it");
        state.hide_message_in_memory("m_held");
        let persist = state
            .user_message_persist("m_held")
            .expect("the bubble is still there");
        assert!(persist.hidden);
        assert_eq!(persist.content, "wait for it");
    }

    /// A Cancel or an Edit that lands while the row is being written meets no row to change.
    /// Once the write is done the row is the bubble as memory has it, not as it was when the
    /// write began.
    #[tokio::test]
    async fn a_row_written_while_its_hold_is_taken_back_ends_as_memory_does() {
        let db = test_db().await;
        db.ensure_session("s1", "Ada").await.expect("a session");
        let mut reads = 0;
        super::write_user_row(
            &db,
            "m_held",
            "s1",
            "wait for it".to_string(),
            None,
            SystemTime::UNIX_EPOCH,
            || {
                reads += 1;
                let moved = reads > 1;
                Some(super::UserMessagePersist {
                    content: if moved {
                        "the new words"
                    } else {
                        "wait for it"
                    }
                    .to_string(),
                    hidden: moved,
                })
            },
        )
        .await
        .expect("written");
        let rows = db.get_messages("s1").await.expect("the thread reopens");
        assert_eq!(rows[0].content, "the new words");
        assert!(
            rows[0].deleted_at.is_some(),
            "the row is hidden, as the bubble is"
        );
    }

    #[tokio::test]
    async fn an_edited_queued_row_reads_back_the_new_words() {
        let db = test_db().await;
        db.ensure_session("s1", "Ada").await.expect("a session");
        db.save_message(
            "m_held",
            "s1",
            "user",
            "wait for it",
            None,
            None,
            None,
            &[],
            None,
            false,
            SaveStamp::at(SystemTime::UNIX_EPOCH),
        )
        .await
        .expect("saved");
        db.update_message_content("m_held", "the new words")
            .await
            .expect("edited");
        let rows = db.get_messages("s1").await.expect("the thread reopens");
        assert_eq!(rows[0].content, "the new words");
    }

    fn pending_row(id: &str, bubble: &str, content: &str) -> crate::opengrok::PendingUserMessage {
        serde_json::from_value(serde_json::json!({
            "v": 1,
            "id": id,
            "threadId": "cw_1",
            "content": content,
            "clientMessageId": bubble,
            "status": "pending",
            "createdAtMs": 30,
            "updatedAtMs": 30
        }))
        .expect("pending row")
    }

    /// A follow-up another machine queued shows up here as a held bubble.
    #[test]
    fn hydrate_puts_a_server_pending_on_the_queue() {
        let mut state = mid_turn(at(message("m_live", false, ""), 20));
        state.fold_pending_snapshot(
            "cw_1",
            &[pending_row("pum_1", "msg_other", "from the laptop")],
        );
        assert!(state.is_send_queued("msg_other"));
        assert_eq!(
            state
                .queued_sends
                .get("cw_1")
                .and_then(|queue| queue.front())
                .map(|queued| queued.pending_id.as_deref()),
            Some(Some("pum_1"))
        );
        assert_eq!(bubble(&state, "msg_other").content, "from the laptop");
        assert!(!bubble(&state, "msg_other").hidden);
    }

    /// An enqueue that has not landed yet has no `pum_…`. Hydrate must not drop it.
    #[test]
    fn hydrate_keeps_a_local_hold_the_server_has_not_heard() {
        let mut state = holding("m_held", "wait for it");
        state.fold_pending_snapshot("cw_1", &[]);
        assert!(state.is_send_queued("m_held"));
        assert_eq!(
            state
                .queued_sends
                .get("cw_1")
                .and_then(|queue| queue.front())
                .and_then(|queued| queued.pending_id.as_deref()),
            None
        );
    }

    /// The queue is the order the person typed in. A hold whose enqueue has not landed stays
    /// where it was, not behind the ones the server already has.
    #[test]
    fn hydrate_keeps_the_order_the_holds_were_typed_in() {
        let mut state = holding("m_a", "first");
        state.conversations[0]
            .messages
            .push(at(message("m_b", true, "second"), 40));
        let mut b = super::held_message("m_b".into(), "second".into(), None, None, None, None);
        b.pending_id = Some("pum_b".into());
        state.queued_sends.get_mut("cw_1").unwrap().push_back(b);

        state.fold_pending_snapshot(
            "cw_1",
            &[
                pending_row("pum_b", "m_b", "second"),
                pending_row("pum_x", "m_x", "from the laptop"),
            ],
        );
        let order: Vec<&str> = state.queued_sends["cw_1"]
            .iter()
            .map(|queued| queued.message_id.as_str())
            .collect();
        assert_eq!(order, ["m_a", "m_b", "m_x"]);
    }

    /// A synced hold that vanished from the snapshot left the queue. The bubble stays:
    /// the row being gone is also what a drain on another machine looks like, and the
    /// answer may not be in this transcript yet.
    #[test]
    fn hydrate_keeps_the_bubble_when_a_synced_hold_vanishes() {
        let mut state = holding("m_held", "wait for it");
        state.queued_sends.get_mut("cw_1").unwrap()[0].pending_id = Some("pum_1".into());
        state.fold_pending_snapshot("cw_1", &[]);
        assert!(!state.is_send_queued("m_held"));
        assert!(
            !bubble(&state, "m_held").hidden,
            "the words stay until the answer arrives"
        );
    }

    /// The set of canceled ids only has to remember rows the server still has.
    #[test]
    fn a_cancel_tombstone_lasts_only_while_the_server_still_has_the_row() {
        let mut state = holding("m_held", "wait for it");
        state.queued_sends.get_mut("cw_1").unwrap()[0].pending_id = Some("pum_1".into());
        state.canceled_pending.insert("m_held".into());
        state.canceled_pending.insert("m_elsewhere".into());
        state.fold_pending_snapshot("cw_1", &[pending_row("pum_1", "m_held", "wait for it")]);
        assert!(
            state.canceled_pending.contains("m_held"),
            "the row is still on the server"
        );
        assert!(!state.is_send_queued("m_held"));
        state.fold_pending_snapshot("cw_1", &[]);
        assert!(
            !state.canceled_pending.contains("m_held"),
            "the row is gone"
        );
        assert!(state.canceled_pending.contains("m_elsewhere"));
    }

    /// A synced hold that vanished because it drained keeps the bubble: an assistant
    /// reply already sits after it.
    #[test]
    fn hydrate_leaves_a_drained_bubble_when_the_reply_is_already_here() {
        let mut state = holding("m_held", "wait for it");
        state.queued_sends.get_mut("cw_1").unwrap()[0].pending_id = Some("pum_1".into());
        state.conversations[0]
            .messages
            .push(at(message("m_reply", false, "done"), 40));
        state.fold_pending_snapshot("cw_1", &[]);
        assert!(!state.is_send_queued("m_held"));
        assert!(
            !bubble(&state, "m_held").hidden,
            "the send happened; only the hold is gone"
        );
    }

    /// Cancel this process, then a GET that raced the DELETE must not restore the bubble.
    #[test]
    fn hydrate_does_not_restore_a_hold_this_process_already_took_back() {
        let mut state = mid_turn(at(message("m_live", false, ""), 20));
        state.canceled_pending.insert("msg_other".into());
        state.fold_pending_snapshot(
            "cw_1",
            &[pending_row("pum_1", "msg_other", "from the laptop")],
        );
        assert!(!state.is_send_queued("msg_other"));
        assert!(
            state.conversations[0]
                .messages
                .iter()
                .all(|message| message.id != "msg_other"),
            "the tombstone skips grafting"
        );
    }

    /// Edited offline, a synced hold's row still has the old words. A hydrate must not put them
    /// back, and drain must not post the new words against that row before a PATCH lands.
    #[test]
    fn an_offline_edit_of_a_synced_hold_outlives_a_hydrate() {
        let mut state = holding("m_held", "wait for it");
        state.queued_sends.get_mut("cw_1").unwrap()[0].pending_id = Some("pum_1".into());
        assert!(matches!(
            state.begin_queued_edit("m_held", "the offline words".into()),
            super::QueuedEdit::Applied { .. }
        ));

        state.fold_pending_snapshot("cw_1", &[pending_row("pum_1", "m_held", "wait for it")]);
        assert_eq!(bubble(&state, "m_held").content, "the offline words");
        assert_eq!(state.queued_sends["cw_1"][0].content, "the offline words");
        go_idle(&mut state);
        assert!(
            state.pop_queued_send("cw_1").is_none(),
            "the row has the old words until the PATCH lands"
        );
    }

    /// Reconnecting sends the PATCH an offline edit owes, once, with drain held until it lands.
    #[test]
    fn coming_back_owes_the_offline_edit_its_patch() {
        let mut state = holding("m_held", "wait for it");
        state.queued_sends.get_mut("cw_1").unwrap()[0].pending_id = Some("pum_1".into());
        state.begin_queued_edit("m_held", "the offline words".into());
        assert_eq!(
            state.take_unsynced_edits(),
            [super::OwedPatch {
                thread_id: "cw_1".into(),
                pending_id: "pum_1".into(),
                message_id: "m_held".into(),
                content: "the offline words".into(),
            }]
        );
        assert!(state.pending_inflight.contains("m_held"));
        assert!(
            state.take_unsynced_edits().is_empty(),
            "one PATCH at a time"
        );
    }

    /// Canceled offline, then the app restarted: the DELETE never landed and the tombstone was
    /// memory. The bubble on disk is hidden, and that is the person's word: the hold is not
    /// put back, and the row is asked to go again.
    #[test]
    fn hydrate_does_not_restore_a_send_hidden_before_a_restart() {
        let mut state = mid_turn(at(message("m_live", false, ""), 20));
        let mut canceled = at(message("m_held", true, "wait for it"), 30);
        canceled.hidden = true;
        state.conversations[0].messages.push(canceled);

        let fold =
            state.fold_pending_snapshot("cw_1", &[pending_row("pum_1", "m_held", "wait for it")]);
        assert!(!state.is_send_queued("m_held"));
        assert!(bubble(&state, "m_held").hidden);
        assert_eq!(fold.cancel, ["pum_1"]);
    }

    /// Enqueue landed after the person canceled: give the `pum_…` back.
    #[test]
    fn bind_after_a_local_cancel_takes_the_row_back() {
        let mut state = AppState::new();
        state.canceled_pending.insert("msg_1".into());
        match state.bind_pending_id("msg_1", "pum_1".into(), "later") {
            super::BindPending::TakeBack { pending_id } => assert_eq!(pending_id, "pum_1"),
            other => panic!("expected TakeBack, got a bind: {other:?}"),
        }
    }

    #[test]
    fn bind_stores_the_pending_id_on_the_hold() {
        let mut state = holding("m_held", "wait for it");
        match state.bind_pending_id("m_held", "pum_1".into(), "wait for it") {
            super::BindPending::Bound => {}
            other => panic!("expected Bound, got {other:?}"),
        }
        assert_eq!(
            state.queued_sends.get("cw_1").unwrap()[0]
                .pending_id
                .as_deref(),
            Some("pum_1")
        );
    }

    #[test]
    fn bind_after_an_edit_asks_for_a_patch() {
        let mut state = holding("m_held", "wait for it");
        assert!(state.apply_queued_edit("m_held", "instead".into()));
        match state.bind_pending_id("m_held", "pum_1".into(), "wait for it") {
            super::BindPending::Patch {
                pending_id,
                content,
            } => {
                assert_eq!(pending_id, "pum_1");
                assert_eq!(content, "instead");
            }
            other => panic!("expected Patch, got {other:?}"),
        }
    }

    /// The PATCH bind sends is a mutation like any other: drain must not post the new words
    /// against the row that still has the old ones.
    #[test]
    fn drain_waits_for_the_patch_bind_sends() {
        let mut state = holding("m_held", "wait for it");
        assert!(state.apply_queued_edit("m_held", "instead".into()));
        assert!(matches!(
            state.bind_pending_id("m_held", "pum_1".into(), "wait for it"),
            super::BindPending::Patch { .. }
        ));
        go_idle(&mut state);
        assert!(state.pop_queued_send("cw_1").is_none());
        assert!(state.is_send_queued("m_held"));
    }

    #[test]
    fn reply_and_recipe_read_off_a_pending_row() {
        let row: crate::opengrok::PendingUserMessage = serde_json::from_value(serde_json::json!({
            "id": "pum_1",
            "content": "later",
            "replyTo": { "messageId": "m1", "preview": "hi", "isMe": true },
            "recipeId": "rec_1",
            "recipeValues": { "q": "x" },
            "skillId": "skl_1",
            "clientMessageId": "msg_1"
        }))
        .unwrap();
        let reply = super::reply_from_pending(row.reply_to.as_ref()).expect("reply");
        assert_eq!(reply.message_id, "m1");
        assert_eq!(reply.preview, "hi");
        assert!(reply.is_me);
        let recipe = super::recipe_from_pending(&row).expect("recipe");
        assert_eq!(recipe.id, "rec_1");
        assert_eq!(recipe.values.get("q").and_then(|v| v.as_str()), Some("x"));
    }

    fn pending_custom(
        op: &str,
        message: Option<serde_json::Value>,
    ) -> crate::opengrok::PendingCustom {
        let mut value = serde_json::json!({
            "v": 1,
            "op": op,
            "threadId": "cw_1",
        });
        if let Some(message) = message {
            value["message"] = message;
        }
        crate::opengrok::PendingCustom::from_agui(&serde_json::json!({
            "type": "CUSTOM",
            "name": "pending-user-message",
            "value": value,
        }))
        .expect("custom")
    }

    /// CUSTOM `created` / `snapshot` put a hold on the queue.
    #[test]
    fn a_created_custom_holds_the_bubble() {
        let mut state = mid_turn(at(message("m_live", false, ""), 20));
        state.apply_pending_custom(
            &pending_custom(
                "created",
                Some(serde_json::json!({
                    "id": "pum_1",
                    "threadId": "cw_1",
                    "content": "from the laptop",
                    "clientMessageId": "msg_other",
                })),
            ),
            None,
        );
        assert!(state.is_send_queued("msg_other"));
        assert_eq!(
            state.queued_sends.get("cw_1").unwrap()[0]
                .pending_id
                .as_deref(),
            Some("pum_1")
        );
        assert_eq!(bubble(&state, "msg_other").content, "from the laptop");
    }

    #[test]
    fn an_edited_custom_changes_the_hold() {
        let mut state = holding("m_held", "wait for it");
        state.queued_sends.get_mut("cw_1").unwrap()[0].pending_id = Some("pum_1".into());
        state.apply_pending_custom(
            &pending_custom(
                "edited",
                Some(serde_json::json!({
                    "id": "pum_1",
                    "content": "the new words",
                    "clientMessageId": "m_held",
                })),
            ),
            Some("m_held"),
        );
        assert_eq!(bubble(&state, "m_held").content, "the new words");
        assert_eq!(
            state.queued_sends.get("cw_1").unwrap()[0].content,
            "the new words"
        );
        assert!(state.pending_inflight.is_empty());
    }

    #[test]
    fn a_canceled_custom_without_a_message_still_takes_the_hold_off() {
        let mut state = holding("m_held", "wait for it");
        state.queued_sends.get_mut("cw_1").unwrap()[0].pending_id = Some("pum_1".into());
        state.apply_pending_custom(&pending_custom("canceled", None), Some("m_held"));
        assert!(!state.is_send_queued("m_held"));
        assert!(bubble(&state, "m_held").hidden);
        assert!(state.canceled_pending.contains("m_held"));
    }

    #[test]
    fn a_drained_custom_drops_the_hold_and_keeps_the_bubble() {
        let mut state = holding("m_held", "wait for it");
        state.queued_sends.get_mut("cw_1").unwrap()[0].pending_id = Some("pum_1".into());
        state.apply_pending_custom(
            &pending_custom(
                "drained",
                Some(serde_json::json!({
                    "id": "pum_1",
                    "content": "wait for it",
                    "clientMessageId": "m_held",
                    "status": "drained",
                })),
            ),
            Some("m_held"),
        );
        assert!(!state.is_send_queued("m_held"));
        assert!(!bubble(&state, "m_held").hidden);
    }

    #[test]
    fn drain_does_not_pop_a_hold_whose_delete_is_in_flight() {
        let mut state = holding("m_held", "wait for it");
        state.pending_inflight.insert("m_held".into());
        go_idle(&mut state);
        assert!(
            state.pop_queued_send("cw_1").is_none(),
            "FIFO: the front hold is being canceled or edited"
        );
        assert!(state.is_send_queued("m_held"));
        state.pending_inflight.remove("m_held");
        assert_eq!(state.pop_queued_send("cw_1").unwrap().message_id, "m_held");
    }

    #[test]
    fn hydrate_keeps_an_inflight_hold_instead_of_replacing_it() {
        let mut state = holding("m_held", "wait for it");
        state.queued_sends.get_mut("cw_1").unwrap()[0].pending_id = Some("pum_1".into());
        state.pending_inflight.insert("m_held".into());
        state.fold_pending_snapshot("cw_1", &[pending_row("pum_1", "m_held", "stale from GET")]);
        assert_eq!(
            state.queued_sends.get("cw_1").unwrap()[0].content,
            "wait for it"
        );
        assert!(!bubble(&state, "m_held").hidden);
    }

    #[test]
    fn hydrate_from_snapshot_events_matches_the_row_list() {
        let mut state = mid_turn(at(message("m_live", false, ""), 20));
        let events = vec![serde_json::json!({
            "type": "CUSTOM",
            "name": "pending-user-message",
            "value": {
                "v": 1,
                "op": "snapshot",
                "threadId": "cw_1",
                "message": {
                    "id": "pum_1",
                    "content": "from the event",
                    "clientMessageId": "msg_other"
                }
            }
        })];
        let rows = crate::opengrok::PendingCustom::snapshot_messages(&events);
        state.fold_pending_snapshot("cw_1", &rows);
        assert!(state.is_send_queued("msg_other"));
        assert_eq!(bubble(&state, "msg_other").content, "from the event");
    }

    /// A queued reply as POST /pending saved it: the toolbar's short preview, and no quote line.
    fn holding_reply_to_a_long_answer() -> (AppState, super::ReplyTo) {
        let quoted = "The build is green on main.\nEvery crate compiled, every test passed, \
                      and the deploy is waiting on you.";
        let mut state = mid_turn(at(message("m_bot", false, quoted), 20));
        let reply = super::ReplyTo {
            message_id: "m_bot".into(),
            preview: "The build is green on main. Every crate compiled, every test passed, an…"
                .into(),
            is_me: false,
        };
        let mut held = at(message("m_held", true, "ship it?"), 30);
        held.reply_to_id = Some(reply.message_id.clone());
        held.reply_preview = Some(reply.preview.clone());
        state.conversations[0].messages.push(held);
        let mut queued = super::held_message(
            "m_held".into(),
            "ship it?".into(),
            None,
            None,
            Some(reply.clone()),
            None,
        );
        queued.pending_id = Some("pum_1".into());
        state
            .queued_sends
            .entry("cw_1".into())
            .or_default()
            .push_back(queued);
        (state, reply)
    }

    /// 409 stale-pending-message: the row changed since this machine read it, and is still
    /// queued. The hold goes back to the front with the server's words and is sent once more;
    /// refused again, it stays queued and is not sent again.
    #[test]
    fn a_stale_refusal_puts_the_hold_back_with_the_servers_words() {
        let mut state = holding("m_held", "wait for it");
        state.queued_sends.get_mut("cw_1").unwrap()[0].pending_id = Some("pum_1".into());
        go_idle(&mut state);
        let held = state.pop_queued_send("cw_1").expect("drains");
        state.conversations[0]
            .messages
            .push(at(message("r_1", false, ""), 40));
        let edited = pending_custom(
            "edited",
            Some(serde_json::json!({
                "id": "pum_1",
                "content": "the laptop's words",
                "clientMessageId": "m_held",
                "status": "pending",
            })),
        );

        state.put_back_stale_hold("cw_1", "r_1", held, &edited);
        state.apply_pending_custom(&edited, Some("m_held"));
        assert_eq!(bubble(&state, "m_held").content, "the laptop's words");
        assert!(
            state.conversations[0]
                .messages
                .iter()
                .all(|message| message.id != "r_1"),
            "the refused turn leaves no reply bubble to carry an error"
        );
        let again = state.pop_queued_send("cw_1").expect("sent once more");
        assert_eq!(again.content, "the laptop's words");
        assert_eq!(again.pending_id.as_deref(), Some("pum_1"));

        state.put_back_stale_hold("cw_1", "r_2", again, &edited);
        state.apply_pending_custom(&edited, Some("m_held"));
        assert!(
            state.is_send_queued("m_held"),
            "refused twice, still queued"
        );
        assert!(
            state.pop_queued_send("cw_1").is_none(),
            "and not sent a third time"
        );
    }

    /// Parked means another machine's words were refused twice. Words the person types here
    /// are theirs, so the hold goes out again.
    #[test]
    fn editing_a_parked_hold_sends_it_again() {
        let mut state = holding("m_held", "wait for it");
        state.queued_sends.get_mut("cw_1").unwrap()[0].stale = super::StaleRefusal::Parked;
        go_idle(&mut state);
        assert!(state.pop_queued_send("cw_1").is_none(), "parked");

        assert!(matches!(
            state.begin_queued_edit("m_held", "my own words".into()),
            super::QueuedEdit::Applied { .. }
        ));
        let next = state.pop_queued_send("cw_1").expect("unparked by the edit");
        assert_eq!(next.content, "my own words");
    }

    /// A stale refusal naming a drained row: this run already spent it, so there is nothing to
    /// put back.
    #[test]
    fn a_stale_refusal_for_a_spent_row_leaves_the_hold_off() {
        let mut state = holding("m_held", "wait for it");
        state.queued_sends.get_mut("cw_1").unwrap()[0].pending_id = Some("pum_1".into());
        go_idle(&mut state);
        let held = state.pop_queued_send("cw_1").expect("drains");
        let drained = pending_custom(
            "drained",
            Some(serde_json::json!({
                "id": "pum_1",
                "content": "other words",
                "clientMessageId": "m_held",
                "status": "drained",
            })),
        );
        state.put_back_stale_hold("cw_1", "r_1", held, &drained);
        state.apply_pending_custom(&drained, Some("m_held"));
        assert!(!state.is_send_queued("m_held"));
        assert_eq!(bubble(&state, "m_held").content, "wait for it");
        assert!(!bubble(&state, "m_held").hidden);
    }

    /// OpenGrok compares the LAST user message with the row it drains. A hold still queued behind
    /// the one going is not part of its turn, and the one going is last even when its answer
    /// is painted after a later hold.
    #[test]
    fn a_drained_hold_is_the_last_user_message_of_its_turn() {
        let mut state = holding("m_a", "first");
        state.conversations[0]
            .messages
            .push(at(message("m_b", true, "second"), 40));
        let queue = state.queued_sends.get_mut("cw_1").unwrap();
        queue.push_back(super::held_message(
            "m_b".into(),
            "second".into(),
            None,
            None,
            None,
            None,
        ));
        queue[0].pending_id = Some("pum_a".into());
        queue[1].pending_id = Some("pum_b".into());
        go_idle(&mut state);

        let a = state.pop_queued_send("cw_1").expect("A drains first");
        let sent: Vec<String> = state
            .turn_history("cw_1", Some(&a))
            .into_iter()
            .map(|m| m.id)
            .collect();
        assert_eq!(sent, ["m_ask", "m_a"]);

        state.conversations[0]
            .messages
            .push(at(message("r_a", false, "done"), 50));
        let b = state.pop_queued_send("cw_1").expect("then B");
        let sent: Vec<String> = state
            .turn_history("cw_1", Some(&b))
            .into_iter()
            .map(|m| m.id)
            .collect();
        assert_eq!(sent, ["m_ask", "m_a", "r_a", "m_b"]);
    }

    /// OpenGrok drains a queued send only when the last user message is its row: the saved words
    /// exactly, and `replyTo` exactly as saved. The quote line is the server's to write.
    #[test]
    fn a_drained_reply_is_sent_as_its_pending_row() {
        let (mut state, reply) = holding_reply_to_a_long_answer();
        go_idle(&mut state);
        let next = state.pop_queued_send("cw_1").expect("the hold drains");
        let history = state.turn_history("cw_1", Some(&next));
        let sent = serde_json::to_value(history.last().expect("the hold")).unwrap();
        assert_eq!(
            sent,
            serde_json::json!({
                "id": "m_held",
                "role": "user",
                "content": "ship it?",
                "replyTo": {
                    "messageId": "m_bot",
                    "preview": "The build is green on main. Every crate compiled, every test passed, an…",
                    "isMe": false,
                },
            })
        );
        assert_eq!(
            sent["replyTo"],
            super::reply_json(&reply),
            "the replyTo POST /pending saved"
        );

        let mut never_posted = next.clone();
        never_posted.pending_id = None;
        let history = state.turn_history("cw_1", Some(&never_posted));
        assert_eq!(
            history.last().map(|m| m.content.as_str()),
            Some(
                "[Replying to your earlier message: \"The build is green on main.\nEvery crate \
                 compiled, every test passed, and the deploy is waiting on you.\"]\n\nship it?"
            ),
            "a hold no server heard of keeps the quote in its words, for a server that reads only those"
        );
    }

    /// Cold "hi": no open HITL, no Waiting, no parked run. The thread is idle.
    #[test]
    fn cold_composer_send_is_idle() {
        let mut state = AppState::new();
        state
            .conversations
            .push(thread("cw_1", vec![at(message("m_hi", true, "hi"), 10)]));
        state.active_conversation_id = Some("cw_1".to_string());
        state.active_coworker_id = Some("cw_1".to_string());
        assert!(!state.has_open_user_form("cw_1"));
        assert!(!state.has_open_approval("cw_1"));
        assert!(!state.has_hitl_to_interrupt("cw_1"));
        assert_eq!(state.busy_state("cw_1"), Busy::Idle);
    }

    /// The run finished and left the card (**Waiting for you**). A send is a
    /// steer: the card settles as Superseded, the Waiting chrome goes, the
    /// parked-run entry goes, and the thread reads idle — nothing to `/stop`.
    #[test]
    fn a_parked_steer_settles_every_card_and_clears_waiting() {
        let mut bot = message("m_live", false, "");
        bot.parts = vec![ChatPart::UserForm(parked_form())];
        let mut state = mid_turn(at(bot, 20));
        state.park_waiting_for_you("cw_1", "run_1");
        assert_eq!(state.thread_status("cw_1"), Some(WAITING_FOR_YOU_STATUS));
        assert_eq!(state.busy_state("cw_1"), Busy::Parked);

        state.settle_parked_cards("cw_1");
        assert!(!state.has_hitl_to_interrupt("cw_1"));
        assert_eq!(state.thread_status("cw_1"), None);
        assert_eq!(state.busy_state("cw_1"), Busy::Idle);
    }

    #[test]
    fn skip_clears_waiting_when_no_open_form_or_handoff_remains() {
        let spec = crate::opengrok::UserFormSpec::from_custom_event(&serde_json::json!({
            "type": "CUSTOM",
            "name": "run-awaiting-approval",
            "callId": "call-9",
            "entryId": "e_form",
            "reason": "user-form",
            "arguments": {
                "title": "Website login",
                "fields": [{"id": "email", "label": "Email", "type": "email", "required": true}]
            }
        }))
        .unwrap();
        let mut bot = message("m_live", false, "");
        bot.parts = vec![ChatPart::UserForm(spec)];
        let mut state = mid_turn(at(bot, 20));
        state.park_waiting_for_you("cw_1", "run_1");
        assert_eq!(state.thread_status("cw_1"), Some(WAITING_FOR_YOU_STATUS));

        state.paint_user_form_resolution("e_form", FormResolution::Skipped);
        state.set_computer_handoff("e_form", crate::opengrok::ComputerHandoffStatus::Skipped);
        state.user_form_handoff_done.insert("e_form".into());
        state.sync_waiting_chrome("cw_1");

        assert_eq!(
            state.thread_status("cw_1"),
            None,
            "Waiting for you must drop once Skip settles the last open card"
        );
        assert!(state.open_user_forms().is_empty());
        assert!(state.open_computer_handoffs().is_empty());
    }

    #[test]
    fn stacked_open_forms_stay_enabled_and_waiting_until_each_settles() {
        fn login(entry: &str, call: &str) -> crate::opengrok::UserFormSpec {
            crate::opengrok::UserFormSpec::from_custom_event(&serde_json::json!({
                "type": "CUSTOM",
                "name": "run-awaiting-approval",
                "callId": call,
                "entryId": entry,
                "reason": "user-form",
                "arguments": {
                    "title": "Website login",
                    "fields": [
                        {"id": "email", "label": "Email", "type": "email", "required": true},
                        {"id": "password", "label": "Password", "type": "password", "required": true}
                    ]
                }
            }))
            .unwrap()
        }
        let a = login("e_a", "call-a");
        let b = login("e_b", "call-b");
        let c = login("e_c", "call-c");
        assert!(a.can_post(true));
        assert!(
            b.can_post(false),
            "global verbs-off must not gray this card"
        );
        assert!(c.can_post(false));
        let mut bot = message("m_live", false, "");
        bot.parts = vec![
            ChatPart::UserForm(a),
            ChatPart::UserForm(b),
            ChatPart::UserForm(c),
        ];
        let mut state = mid_turn(at(bot, 20));
        state.user_form_verbs_available = false;
        state.park_waiting_for_you("cw_1", "run_1");
        assert_eq!(state.open_user_forms().len(), 3);
        for spec in state.open_user_forms() {
            assert!(
                spec.can_post(state.user_form_verbs_available),
                "{} must stay Continue-able",
                spec.entry_id
            );
            assert!(
                spec.can_dismiss(),
                "{} must stay Dismiss-able",
                spec.entry_id
            );
        }

        state.paint_user_form_resolution("e_a", FormResolution::Dismissed);
        state.sync_waiting_chrome("cw_1");
        assert_eq!(
            state.thread_status("cw_1"),
            Some(WAITING_FOR_YOU_STATUS),
            "Dismiss one of three must not blank Waiting"
        );
        let open = state.open_user_forms();
        assert_eq!(open.len(), 2);
        assert!(open.iter().all(|spec| spec.can_post(false)));
        assert!(open.iter().all(|spec| spec.entry_id != "e_a"));

        state.paint_user_form_resolution("e_b", FormResolution::Dismissed);
        state.paint_user_form_resolution("e_c", FormResolution::Dismissed);
        state.sync_waiting_chrome("cw_1");
        assert_eq!(
            state.thread_status("cw_1"),
            None,
            "Waiting clears only after the last open form settles"
        );
        assert!(state.open_user_forms().is_empty());
    }

    fn call_keyed_login(call: &str) -> crate::opengrok::UserFormSpec {
        crate::opengrok::UserFormSpec::from_custom_event(&serde_json::json!({
            "type": "CUSTOM",
            "name": "run-awaiting-approval",
            "callId": call,
            "reason": "user-form",
            "arguments": {
                "title": "Website login",
                "fields": [
                    {"id": "email", "label": "Email", "type": "email", "required": true}
                ]
            }
        }))
        .unwrap()
    }

    /// `user-form-dismiss-call-*` must settle the card locally. HTTP has no
    /// gateway `entryId`; restore must not snap the form back to live.
    #[test]
    fn call_keyed_dismiss_settles_locally_and_survives_restore() {
        let spec = call_keyed_login("call-9");
        assert_eq!(spec.card_key(), "call-9");
        assert!(spec.entry_id.is_empty());
        assert!(spec.can_dismiss());
        assert!(!spec.can_post(true), "Continue stays gated without entryId");
        let mut bot = message("m_live", false, "");
        bot.parts = vec![ChatPart::UserForm(spec)];
        let mut state = mid_turn(at(bot, 20));
        state.park_waiting_for_you("cw_1", "run_1");
        assert_eq!(state.open_user_forms().len(), 1);
        assert_eq!(state.thread_status("cw_1"), Some(WAITING_FOR_YOU_STATUS));

        state.paint_user_form_resolution("call-9", FormResolution::Dismissed);
        state.sync_waiting_chrome("cw_1");
        assert!(
            state.open_user_forms().is_empty(),
            "call-* Dismiss must settle that card"
        );
        assert_eq!(state.thread_status("cw_1"), None);

        state.restore_user_form("call-9");
        assert!(
            state.open_user_forms().is_empty(),
            "no-gateway restore must not revive call-*"
        );
        match &state.conversations[0].messages[1].parts[0] {
            ChatPart::UserForm(spec) => {
                assert_eq!(spec.effective_resolution(), Some(FormResolution::Dismissed));
            }
            other => panic!("expected user-form, got {other:?}"),
        }
    }

    /// Open the screen on a call-keyed card mints `computer-handoff-call-*`
    /// even without a gateway `entryId`.
    #[test]
    fn call_keyed_open_screen_mints_computer_handoff() {
        let spec = call_keyed_login("call-9");
        let mut bot = message("m_live", false, "");
        bot.parts = vec![ChatPart::UserForm(spec)];
        let mut state = mid_turn(at(bot, 20));
        state.set_computer_handoff(
            "call-9",
            crate::opengrok::ComputerHandoffStatus::ActionNeeded,
        );
        let handoffs = state.visible_computer_handoffs();
        assert_eq!(handoffs.len(), 1);
        assert_eq!(handoffs[0].card_key(), "call-9");
        assert_eq!(
            crate::opengrok::computer_handoff_card_id(handoffs[0].card_key()),
            "computer-handoff-call-9"
        );
        assert!(handoffs[0].live_computer_handoff());
        state
            .user_form_handoff_restore
            .insert("call-9".into(), None);
        state.restore_user_form("call-9");
        assert!(
            state
                .visible_computer_handoffs()
                .iter()
                .any(|spec| spec.card_key() == "call-9" && spec.live_computer_handoff()),
            "call-* Open the screen must keep computer-handoff-call-*"
        );
    }

    /// Stacked call-* Dismiss one; others stay enabled. After those settle,
    /// Skip both e_* siblings with nothing else pending clears Waiting.
    #[test]
    fn call_keyed_dismiss_one_then_skip_siblings_clears_waiting() {
        fn gateway_login(entry: &str, call: &str) -> crate::opengrok::UserFormSpec {
            crate::opengrok::UserFormSpec::from_custom_event(&serde_json::json!({
                "type": "CUSTOM",
                "name": "run-awaiting-approval",
                "callId": call,
                "entryId": entry,
                "reason": "user-form",
                "arguments": {
                    "title": "Website login",
                    "fields": [
                        {"id": "email", "label": "Email", "type": "email", "required": true}
                    ]
                }
            }))
            .unwrap()
        }
        let e_a = gateway_login("e_a", "call-a");
        let e_b = gateway_login("e_b", "call-b");
        let extra_x = call_keyed_login("call-x");
        let extra_y = call_keyed_login("call-y");
        assert!(extra_x.can_dismiss() && extra_y.can_dismiss());
        assert!(!extra_x.can_post(true) && !extra_y.can_post(true));
        let mut bot = message("m_live", false, "");
        bot.parts = vec![
            ChatPart::UserForm(e_a),
            ChatPart::UserForm(e_b),
            ChatPart::UserForm(extra_x),
            ChatPart::UserForm(extra_y),
        ];
        let mut state = mid_turn(at(bot, 20));
        state.park_waiting_for_you("cw_1", "run_1");
        assert_eq!(state.open_user_forms().len(), 4);

        state.paint_user_form_resolution("call-x", FormResolution::Dismissed);
        state.sync_waiting_chrome("cw_1");
        let open = state.open_user_forms();
        assert_eq!(open.len(), 3, "dismiss one call-* leaves the rest live");
        assert!(open.iter().all(|spec| spec.card_key() != "call-x"));
        assert!(open.iter().any(|spec| spec.card_key() == "call-y"));
        assert!(open.iter().any(|spec| spec.entry_id == "e_a"));
        assert!(open.iter().any(|spec| spec.entry_id == "e_b"));
        assert!(open.iter().all(|spec| spec.can_dismiss()));
        assert_eq!(state.thread_status("cw_1"), Some(WAITING_FOR_YOU_STATUS));

        state.paint_user_form_resolution("call-y", FormResolution::Dismissed);
        state.sync_waiting_chrome("cw_1");
        assert_eq!(state.open_user_forms().len(), 2);
        assert_eq!(state.thread_status("cw_1"), Some(WAITING_FOR_YOU_STATUS));

        for key in ["e_a", "e_b"] {
            state.paint_user_form_resolution(key, FormResolution::Skipped);
            state.set_computer_handoff(key, crate::opengrok::ComputerHandoffStatus::Skipped);
            state.user_form_handoff_done.insert(key.into());
        }
        state.sync_waiting_chrome("cw_1");
        assert!(state.open_user_forms().is_empty());
        assert!(state.open_computer_handoffs().is_empty());
        assert_eq!(
            state.thread_status("cw_1"),
            None,
            "Skip both e_* siblings with no other pending forms must clear Waiting"
        );
    }

    #[test]
    fn skip_without_sibling_id_queues_instead_of_posting_form_id() {
        let mut spec = crate::opengrok::UserFormSpec::parse(
            &serde_json::json!({
                "entryId": "e_form",
                "formRequest": {
                    "title": "Website login",
                    "fields": [{"id": "email", "label": "Email", "type": "email", "required": true}]
                }
            }),
            None,
        )
        .unwrap();
        spec.computer_handoff = Some(crate::opengrok::ComputerHandoffStatus::ActionNeeded);
        let mut bot = message("m1", false, "");
        bot.parts = vec![ChatPart::UserForm(spec)];
        let mut state = AppState::new();
        state.conversations.push(thread("cw_1", vec![bot]));
        state.active_conversation_id = Some("cw_1".into());
        state.park_waiting_for_you("cw_1", "run_1");

        state.paint_user_form_resolution("e_form", FormResolution::Skipped);
        state.set_computer_handoff("e_form", crate::opengrok::ComputerHandoffStatus::Skipped);
        state.user_form_handoff_done.insert("e_form".into());
        state.queue_pending_box_handoff(
            "e_form",
            "e_form",
            PendingBoxHandoff {
                resolution: crate::opengrok::BoxHandoffResolution::Declined,
                run_id: "run_1".into(),
                conversation_id: "cw_1".into(),
                agent_id: "cw_1".into(),
            },
        );
        state.sync_waiting_chrome("cw_1");
        assert_eq!(state.box_handoff_post_id("e_form", "e_form"), None);
        assert!(state.user_form_pending_resolves.contains_key("e_form"));
        assert_eq!(state.thread_status("cw_1"), None);

        if let ChatPart::UserForm(spec) = &mut state.conversations[0].messages[0].parts[0] {
            spec.handoff_entry_id = Some("e_hand".into());
        }
        assert_eq!(
            state.box_handoff_post_id("e_form", "e_form").as_deref(),
            Some("e_hand")
        );
        let pending = state.take_pending_box_handoff("e_form", "e_form").unwrap();
        assert_eq!(
            pending.resolution,
            crate::opengrok::BoxHandoffResolution::Declined
        );
        assert_ne!(pending.resolution.as_str(), "e_form");
    }

    #[test]
    fn egress_tunnel_is_host_and_box_ready() {
        let mut state = AppState::new();
        assert!(state.egress_tunnel_enabled, "Route traffic defaults ON");
        state.host_egress_tunnel_available = true;
        assert!(
            !state.egress_tunnel_available(),
            "host without a ready box is not a tunnel"
        );
        assert_eq!(
            state.route_traffic_surface(),
            RouteTrafficSurface::Hidden,
            "unprovisioned hides Route traffic"
        );
        state.coworker_computer = Some(
            serde_json::from_value(serde_json::json!({
                "agentId": "cw_1",
                "state": "running",
                "egress_tunnel": { "ready": true }
            }))
            .unwrap(),
        );
        assert!(state.egress_tunnel_available());
        state.coworker_computer = Some(
            serde_json::from_value(serde_json::json!({
                "agentId": "cw_1",
                "state": "running",
                "egress_tunnel": { "ready": false }
            }))
            .unwrap(),
        );
        assert!(!state.egress_tunnel_available());
        assert_eq!(state.route_traffic_surface(), RouteTrafficSurface::Hidden);
        state.host_egress_tunnel_available = false;
        state.coworker_computer = Some(
            serde_json::from_value(serde_json::json!({
                "agentId": "cw_1",
                "state": "running",
                "egress_tunnel": { "ready": true }
            }))
            .unwrap(),
        );
        assert!(
            !state.egress_tunnel_available(),
            "a ready box without host/env is not a Review-an-action tunnel"
        );
        assert_eq!(
            state.route_traffic_surface(),
            RouteTrafficSurface::BotPane,
            "provisioned unique box still shows dedicated chrome without host intent"
        );
        state.coworker_computer = Some(
            serde_json::from_value(serde_json::json!({
                "agentId": "cw_1",
                "state": "running",
                "egress_tunnel": { "url": "ws://127.0.0.1:8790" }
            }))
            .unwrap(),
        );
        state.host_egress_tunnel_available = true;
        assert!(
            state.egress_tunnel_available(),
            "box tunnel URL is ready for Route traffic"
        );
        state.coworker_computer = None;
        state.host_egress_tunnel_available = true;
        assert!(!state.egress_tunnel_available());
        assert_eq!(
            state.route_traffic_surface(),
            RouteTrafficSurface::Hidden,
            "host intent without a provisioned box does not paint Route traffic"
        );
        state.host_egress_tunnel_available = false;
        state.egress_tunnel_enabled = true;
        assert_eq!(state.route_traffic_surface(), RouteTrafficSurface::Hidden);
        state.coworker_computer = Some(
            serde_json::from_value(serde_json::json!({
                "agentId": "cw_1",
                "state": "running",
                "isEgressTunnelAvailable": true
            }))
            .unwrap(),
        );
        assert_eq!(
            state.route_traffic_surface(),
            RouteTrafficSurface::Hidden,
            "host isEgressTunnelAvailable is not box provisioned"
        );
    }

    /// A failed policy write re-marks the card as once-only; the run's answer landing
    /// afterwards must not promote it back to the standing wording.
    #[test]
    fn a_failed_policy_write_keeps_the_once_only_line() {
        // The failure wrote Denied; the late answer says Never: keep Denied.
        assert_eq!(
            settled_decision(Some(&ApprovalDecision::Denied), ApprovalDecision::Never),
            None
        );
        assert_eq!(
            settled_decision(Some(&ApprovalDecision::AllowOnce), ApprovalDecision::Always),
            None
        );
        // The ordinary order: the answer lands on a Sending card and is written as decided.
        assert_eq!(
            settled_decision(Some(&ApprovalDecision::Sending), ApprovalDecision::Never),
            Some(ApprovalDecision::Never)
        );
        assert_eq!(
            settled_decision(None, ApprovalDecision::Always),
            Some(ApprovalDecision::Always)
        );
        // A once-only answer is never blocked by an earlier once-only line.
        assert_eq!(
            settled_decision(Some(&ApprovalDecision::Denied), ApprovalDecision::Denied),
            Some(ApprovalDecision::Denied)
        );
        // And the fallback itself: a Never not kept still denied this call.
        assert_eq!(
            once_only_for(LocalExecMode::Never),
            ApprovalDecision::Denied
        );
        assert_eq!(
            once_only_for(LocalExecMode::Always),
            ApprovalDecision::AllowOnce
        );
    }

    /// A rule that was not kept leaves, where the card was, what the answer still did to this
    /// one call and that the rule was not kept: with the server's reason when it refused the
    /// rule, and no more than that when the write never reached it. The run's answer landing
    /// afterwards must not paint the standing wording back over that.
    #[test]
    fn a_rule_not_kept_leaves_the_once_only_answer_and_why() {
        let card = local_shell_card("ls | head");
        let refused = rule_not_kept(
            true,
            &OpenGrokError::from_server(Some(422), "an allow rule must be one plain command"),
        );
        assert!(refused.is_settled());
        assert_eq!(
            settled_decision(Some(&refused), ApprovalDecision::Always),
            None
        );
        assert_eq!(
            refused.outcome_line("Hexuria", &card).as_deref(),
            Some(
                "Hexuria can run commands on your computer this time. Always allow was not \
                 kept: an allow rule must be one plain command."
            )
        );
        let unreached = rule_not_kept(false, &OpenGrokError::from_server(Some(502), "Bad Gateway"));
        assert_eq!(
            settled_decision(Some(&unreached), ApprovalDecision::Never),
            None
        );
        assert_eq!(
            unreached.outcome_line("Hexuria", &card).as_deref(),
            Some("Hexuria was not allowed to run commands on your computer. Never was not kept.")
        );
    }

