    /// A card's rule is kept for this Mac or not at all. Another computer on the roster is never
    /// taken for it, even when it is the only one there.
    #[test]
    fn a_rule_is_kept_for_this_mac_and_no_other() {
        let mut state = AppState::new();
        let other = ConnectedComputer {
            machine_id: "mac_other".into(),
            label: "Other Mac".into(),
            mode: LocalExecMode::Ask,
            this_machine: false,
            online: true,
            relay_enabled: true,
            relaying: false,
            folded: Vec::new(),
        };
        state.computers = vec![other.clone()];
        assert_eq!(state.this_mac_id(), None);

        state.computers.push(ConnectedComputer {
            machine_id: "mac_here".into(),
            this_machine: true,
            ..other
        });
        assert_eq!(state.this_mac_id().as_deref(), Some("mac_here"));

        state.local_exec_machine_id = Some("mac_daemon".into());
        assert_eq!(state.this_mac_id().as_deref(), Some("mac_daemon"));
    }

    /// A listing of this Mac's policy as `GET /local-exec/policy` sends it.
    fn policy(allow: &[&str], deny: &[&str], inert: &[(&str, &str)]) -> LocalExecPolicy {
        let commands = |list: &[&str]| list.iter().map(|command| command.to_string()).collect();
        LocalExecPolicy {
            machine_id: "mac_here".into(),
            mode: "ask".into(),
            allow: commands(allow),
            deny: commands(deny),
            inert: inert
                .iter()
                .map(|(pattern, reason)| InertRule {
                    pattern: pattern.to_string(),
                    reason: reason.to_string(),
                })
                .collect(),
        }
    }

    fn rule(pattern: &str, inert: Option<&str>) -> LocalRuleRow {
        LocalRuleRow {
            pattern: pattern.into(),
            inert: inert.map(str::to_string),
        }
    }

    /// Settings lists this Mac's rules in the server's order, and an allow the server names in
    /// `inert` carries the server's reason, matched on the command exactly. A deny is never
    /// inert, even with the same command, and an `inert` entry that names no allow names
    /// nothing on the page.
    #[test]
    fn an_allow_the_gate_never_reads_carries_the_servers_reason() {
        let rules = LocalRules::listed(
            "mac_here".into(),
            &policy(
                &["ls -la", "sudo ls"],
                &["sudo ls"],
                &[
                    ("sudo ls", "sudo cannot be a standing allow"),
                    ("git push", "not a rule on this Mac"),
                ],
            ),
        );
        assert!(rules.listed);
        assert_eq!(rules.machine_id, "mac_here");
        assert_eq!(
            rules.allow,
            vec![
                rule("ls -la", None),
                rule("sudo ls", Some("sudo cannot be a standing allow")),
            ]
        );
        assert_eq!(rules.deny, vec![rule("sudo ls", None)]);
    }

    /// Two Removes in flight at once, with reads crossing them: a read that began before a
    /// delete answers after it, and a delete lands while the read the first one started is still
    /// out. Neither deleted row comes back, and one Remove never clears the other's "Removing…".
    #[test]
    fn two_removes_and_the_reads_between_them_never_bring_a_row_back() {
        let mut state = AppState::new();
        let first = state.next_rules_read();
        assert!(state.take_local_rules(
            first,
            "mac_here".into(),
            Ok(policy(&["ls -la", "pwd"], &[], &[])),
        ));
        let before_either = state.next_rules_read();
        let rules = state.local_rules.as_mut().unwrap();
        rules.removing.insert((RuleKind::Allow, "ls -la".into()));
        rules.removing.insert((RuleKind::Allow, "pwd".into()));
        let shown = |state: &AppState| -> Vec<String> {
            let rules = state.local_rules.as_ref().unwrap();
            rules
                .rows(RuleKind::Allow)
                .iter()
                .map(|row| row.pattern.clone())
                .collect()
        };
        let removing = |state: &AppState| state.local_rules.as_ref().unwrap().removing.len();

        // `ls -la` comes off; the other is still on its way.
        assert!(state.take_removal("mac_here", RuleKind::Allow, "ls -la", Ok(())));
        assert_eq!(shown(&state), ["pwd"]);
        assert_eq!(removing(&state), 1, "pwd is still being removed");
        let after_first = state.next_rules_read();

        // The read that began before either delete answers now, still listing both: dropped.
        assert!(!state.take_local_rules(
            before_either,
            "mac_here".into(),
            Ok(policy(&["ls -la", "pwd"], &[], &[])),
        ));
        assert_eq!(shown(&state), ["pwd"]);

        // `pwd` comes off before the first re-read answers.
        assert!(state.take_removal("mac_here", RuleKind::Allow, "pwd", Ok(())));
        assert!(shown(&state).is_empty());
        let after_second = state.next_rules_read();

        // The first re-read, taken before `pwd` went, answers late: dropped too.
        assert!(!state.take_local_rules(
            after_first,
            "mac_here".into(),
            Ok(policy(&["pwd"], &[], &[])),
        ));
        assert!(shown(&state).is_empty());

        // The newest read is what the lists are.
        assert!(state.take_local_rules(after_second, "mac_here".into(), Ok(policy(&[], &[], &[]))));
        assert!(shown(&state).is_empty());
        assert_eq!(removing(&state), 0);
    }

    /// A read answered after a newer one began is dropped whole. A read that failed empties the
    /// lists and says why, in the server's words when it gave some, rather than "no rules". What
    /// is on its way off, and why a Remove did not go through, stay with the machine and the
    /// rows they are about.
    #[test]
    fn a_read_of_this_macs_rules_is_taken_only_while_it_is_the_newest() {
        let mut state = AppState::new();
        state.local_rules_epoch = 2;
        assert!(!state.take_local_rules(1, "mac_here".into(), Ok(policy(&["ls -la"], &[], &[]))));
        assert_eq!(state.local_rules, None);

        assert!(state.take_local_rules(
            2,
            "mac_here".into(),
            Ok(policy(&["ls -la", "pwd"], &["rm -rf /tmp/x"], &[])),
        ));
        let rules = state.local_rules.as_mut().unwrap();
        rules.removing.insert((RuleKind::Allow, "ls -la".into()));
        rules
            .not_removed
            .insert((RuleKind::Allow, "pwd".into()), "Not removed.".into());
        rules.not_removed.insert(
            (RuleKind::Deny, "rm -rf /tmp/x".into()),
            "Not removed.".into(),
        );

        // Read again with the deny gone (taken off from somewhere else): its note goes with it.
        assert!(state.take_local_rules(
            2,
            "mac_here".into(),
            Ok(policy(&["ls -la", "pwd"], &[], &[])),
        ));
        let rules = state.local_rules.as_ref().unwrap();
        assert!(rules.is_removing(RuleKind::Allow, "ls -la"));
        assert_eq!(
            rules.not_removed(RuleKind::Allow, "pwd"),
            Some("Not removed.")
        );
        assert_eq!(rules.not_removed(RuleKind::Deny, "rm -rf /tmp/x"), None);

        assert!(state.take_local_rules(
            2,
            "mac_here".into(),
            Err(OpenGrokError::from_server(
                Some(403),
                "that machine is not yours"
            )),
        ));
        let rules = state.local_rules.as_ref().unwrap();
        assert!(rules.is_empty());
        assert!(
            !rules.listed,
            "a list that could not be read is not an empty one"
        );
        assert_eq!(
            rules.error.as_deref(),
            Some("This Mac's rules could not be read: that machine is not yours.")
        );
        assert!(
            rules.is_removing(RuleKind::Allow, "ls -la"),
            "that Remove is still with the server"
        );

        // Another machine's lists start with nothing of this one's.
        assert!(state.take_local_rules(2, "mac_new".into(), Ok(policy(&[], &[], &[]))));
        let rules = state.local_rules.as_ref().unwrap();
        assert_eq!(rules.machine_id, "mac_new");
        assert!(rules.listed && rules.error.is_none());
        assert!(rules.removing.is_empty() && rules.not_removed.is_empty());
    }

    /// A Remove the server answered takes that rule off the page (every row of it, as the
    /// server deletes by exact match) and asks for the lists again. One that did not go through
    /// leaves the row where it was with why under it, in the server's words when they are a
    /// line of plain text, and asks for nothing.
    #[test]
    fn a_removed_rule_goes_and_one_not_removed_stays_saying_why() {
        let mut state = AppState::new();
        state.local_rules = Some(LocalRules::listed(
            "mac_here".into(),
            &policy(&["ls -la", "pwd", "ls -la"], &["rm -rf /tmp/x"], &[]),
        ));
        let press = |state: &mut AppState, kind: RuleKind, pattern: &str| {
            let rules = state.local_rules.as_mut().unwrap();
            rules.removing.insert((kind, pattern.to_string()));
        };

        press(&mut state, RuleKind::Allow, "ls -la");
        assert!(state.take_removal("mac_here", RuleKind::Allow, "ls -la", Ok(())));
        let rules = state.local_rules.as_ref().unwrap();
        assert_eq!(rules.allow, vec![rule("pwd", None)]);
        assert!(!rules.is_removing(RuleKind::Allow, "ls -la"));

        press(&mut state, RuleKind::Deny, "rm -rf /tmp/x");
        assert!(!state.take_removal(
            "mac_here",
            RuleKind::Deny,
            "rm -rf /tmp/x",
            Err(OpenGrokError::from_server(
                Some(500),
                "could not remove the rule"
            )),
        ));
        let rules = state.local_rules.as_ref().unwrap();
        assert_eq!(rules.deny, vec![rule("rm -rf /tmp/x", None)]);
        assert!(!rules.is_removing(RuleKind::Deny, "rm -rf /tmp/x"));
        assert_eq!(
            rules.not_removed(RuleKind::Deny, "rm -rf /tmp/x"),
            Some("Not removed: could not remove the rule.")
        );

        // What stands in front of the server answering with a page of its own is no reason.
        press(&mut state, RuleKind::Allow, "pwd");
        assert!(!state.take_removal(
            "mac_here",
            RuleKind::Allow,
            "pwd",
            Err(OpenGrokError::from_server(
                Some(500),
                "<html><body>Internal Server Error</body></html>"
            )),
        ));
        assert_eq!(
            state
                .local_rules
                .as_ref()
                .unwrap()
                .not_removed(RuleKind::Allow, "pwd"),
            Some("Not removed.")
        );
    }

    /// The server's reason is given when it refused and said why. A server out of reach, or a
    /// session that has gone, is said by the pill and the banner, and here is only that it did
    /// not happen.
    #[test]
    fn a_rules_failure_gives_a_reason_only_when_the_server_gave_one() {
        assert_eq!(
            rules_refusal(
                "Not removed",
                &OpenGrokError::from_server(Some(500), "could not remove the rule")
            ),
            "Not removed: could not remove the rule."
        );
        assert_eq!(
            rules_refusal(
                "Not removed",
                &OpenGrokError::from_server(Some(502), "Bad Gateway")
            ),
            "Not removed."
        );
        assert_eq!(
            rules_refusal(
                "Not removed",
                &OpenGrokError::signed_out("the session has ended")
            ),
            "Not removed."
        );
    }

    /// This Mac's rules are drawn under this Mac's row and nowhere else: not before the roster
    /// has a row for this Mac, not under a row that is not this Mac's, and not when they were
    /// read for a machine this Mac no longer is.
    #[test]
    fn this_macs_rules_show_only_under_this_macs_own_row() {
        let mut state = AppState::new();
        state.local_rules = Some(LocalRules::listed(
            "mac_here".into(),
            &policy(&["ls -la"], &[], &[]),
        ));
        assert!(state.this_mac_rules().is_none(), "no roster yet");

        let not_this_mac = ConnectedComputer {
            machine_id: "mac_here".into(),
            label: "A Mac".into(),
            mode: LocalExecMode::Ask,
            this_machine: false,
            online: true,
            relay_enabled: true,
            relaying: false,
            folded: Vec::new(),
        };
        state.computers = vec![not_this_mac.clone()];
        assert!(state.this_mac_rules().is_none());

        state.computers = vec![ConnectedComputer {
            this_machine: true,
            ..not_this_mac.clone()
        }];
        assert_eq!(
            state
                .this_mac_rules()
                .map(|rules| rules.machine_id.as_str()),
            Some("mac_here")
        );

        state.computers = vec![ConnectedComputer {
            machine_id: "mac_new".into(),
            this_machine: true,
            ..not_this_mac
        }];
        assert!(
            state.this_mac_rules().is_none(),
            "read for the machine this Mac used to be"
        );
    }

    /// A driver reads this Mac's rules off Settings → Computer, as a person does, and off no
    /// other page.
    #[cfg(feature = "agent")]
    #[test]
    fn a_driver_reads_this_macs_rules_off_settings_computer() {
        use crate::agent::{NativeChatHost, ids};
        use gpui_agent::prelude::AgentHost;
        let mut state = AppState::new();
        state.auth_status = super::AuthStatus::SignedIn;
        state.account = serde_json::from_value(serde_json::json!({
            "id": "acct_1",
            "email": "ada@example.com"
        }))
        .ok();
        state.coworkers.push(bob());
        state.computers = vec![ConnectedComputer {
            machine_id: "mac_here".into(),
            label: "NativeChat on this Mac".into(),
            mode: LocalExecMode::Ask,
            this_machine: true,
            online: true,
            relay_enabled: true,
            relaying: false,
            folded: Vec::new(),
        }];
        state.local_rules = Some(LocalRules::listed(
            "mac_here".into(),
            &policy(&["ls -la"], &["rm -rf /tmp/x"], &[]),
        ));
        let deny = |state: &AppState| {
            NativeChatHost::from_app(state)
                .snapshot()
                .find(&ids::local_rule(RuleKind::Deny, 0))
                .and_then(|node| node.value.clone())
        };
        assert_eq!(deny(&state), None, "Settings is not open on Computer");

        state.is_app_settings_open = true;
        state.app_settings_tab = super::AppSettingsTab::Computer;
        assert_eq!(deny(&state).as_deref(), Some("rm -rf /tmp/x"));

        // Closed with Computer still the selected tab: the commands leave the snapshot with it.
        state.is_app_settings_open = false;
        assert_eq!(deny(&state), None, "Settings closed on the Computer tab");

        // Open on another tab: not there either.
        state.is_app_settings_open = true;
        state.app_settings_tab = super::AppSettingsTab::General;
        assert_eq!(deny(&state), None, "Settings open on General");
    }

    /// The line a card is left with when the policy write for `mode` fails with `error` while
    /// the card is still sending its answer.
    fn not_kept_line(mode: LocalExecMode, error: &OpenGrokError) -> Option<String> {
        policy_not_kept(Some(&ApprovalDecision::Sending), mode, error)
            .expect("a sending card is re-marked")
            .outcome_line("Vamos", &tunnel_card())
    }

    /// A member who answers Always or Never on the tunnel's card for the organization's shared
    /// computer is refused with a 403. The call still went through once, and the card says so,
    /// then says whose choice the standing one is, rather than quietly reading as a once.
    #[test]
    fn a_member_refused_the_computers_choice_is_told_why() {
        let refused =
            OpenGrokError::from_server(Some(403), "only the organization's admin may do that");
        // The write fails while the answer is still on its way.
        let always = policy_not_kept(
            Some(&ApprovalDecision::Sending),
            LocalExecMode::Always,
            &refused,
        )
        .expect("re-marked");
        assert_eq!(
            always.outcome_line("Vamos", &tunnel_card()).as_deref(),
            Some(
                "Vamos may use your network this time. Only the organization's admin can make \
                 that choice for its shared computer."
            )
        );
        // The answer landed first and the card already read as the standing choice.
        let never = policy_not_kept(
            Some(&ApprovalDecision::Never),
            LocalExecMode::Never,
            &refused,
        )
        .expect("re-marked");
        assert_eq!(
            never.outcome_line("Vamos", &tunnel_card()).as_deref(),
            Some(
                "Vamos was not allowed to use your network this time. Only the organization's \
                 admin can make that choice for its shared computer."
            )
        );
        // The run's answer landing afterwards must not put the standing line back over it.
        assert_eq!(
            settled_decision(Some(&always), ApprovalDecision::Always),
            None
        );
        assert_eq!(
            settled_decision(Some(&never), ApprovalDecision::Never),
            None
        );
    }

    /// Any other refusal is given in the server's own words, the 403 of an account in no
    /// organization among them, as one short line of plain text. The server out of reach, or a
    /// session that has gone, leaves the once-only line and nothing more, as before.
    #[test]
    fn a_refused_policy_write_gives_the_servers_reason_and_nothing_else_does() {
        let storage = OpenGrokError::from_server(Some(500), "storage failed");
        assert_eq!(
            not_kept_line(LocalExecMode::Always, &storage).as_deref(),
            Some(
                "Vamos may use your network this time. The choice for every time was not kept: \
                 storage failed."
            )
        );
        let no_org = OpenGrokError::from_server(Some(403), "you are not in an organization");
        assert_eq!(
            not_kept_line(LocalExecMode::Always, &no_org).as_deref(),
            Some(
                "Vamos may use your network this time. The choice for every time was not kept: \
                 you are not in an organization."
            )
        );
        // A proxy's error page is not a reason; the line says only that the choice was not kept.
        let page = OpenGrokError::from_server(
            Some(413),
            "<html>\n<head><title>413 Request Entity Too Large</title></head>\n</html>",
        );
        assert_eq!(
            not_kept_line(LocalExecMode::Never, &page).as_deref(),
            Some(
                "Vamos was not allowed to use your network this time. The choice for every time \
                 was not kept."
            )
        );
        let rambling = OpenGrokError::from_server(
            Some(429),
            format!("slow down {}\nsecond line", "x".repeat(400)),
        );
        let line = not_kept_line(LocalExecMode::Always, &rambling).expect("a line");
        assert!(!line.contains("second line"), "{line}");
        assert!(line.ends_with("x…"), "{line}");
        assert!(line.chars().count() < 260, "{line}");

        let unreached = OpenGrokError::from_server(Some(502), "Bad Gateway");
        assert_eq!(
            policy_not_kept(
                Some(&ApprovalDecision::Sending),
                LocalExecMode::Always,
                &unreached
            ),
            Some(ApprovalDecision::AllowOnce)
        );
        let gone = OpenGrokError::signed_out("sign in first");
        assert_eq!(
            policy_not_kept(Some(&ApprovalDecision::Never), LocalExecMode::Never, &gone),
            Some(ApprovalDecision::Denied)
        );
    }

    /// The run's answer and the policy write land in either order. A card whose answer failed
    /// keeps saying so when the write fails after it: the call never went through, so "may use
    /// your network this time" would be untrue. A card that is gone, or that a later message
    /// closed, is left alone too.
    #[test]
    fn a_failed_answer_is_not_turned_into_a_once_by_the_policy_write() {
        let refused =
            OpenGrokError::from_server(Some(403), "only the organization's admin may do that");
        let failed = ApprovalDecision::Failed("the run could not be answered".into());
        assert_eq!(
            policy_not_kept(Some(&failed), LocalExecMode::Always, &refused),
            None
        );
        assert_eq!(
            policy_not_kept(
                Some(&ApprovalDecision::Superseded),
                LocalExecMode::Always,
                &refused
            ),
            None
        );
        assert_eq!(policy_not_kept(None, LocalExecMode::Never, &refused), None);
        // Either order with an answer that landed ends on the same line.
        let write_first = policy_not_kept(
            Some(&ApprovalDecision::Sending),
            LocalExecMode::Always,
            &refused,
        )
        .expect("re-marked");
        assert_eq!(
            settled_decision(Some(&write_first), ApprovalDecision::Always),
            None
        );
        let answer_first = policy_not_kept(
            Some(&ApprovalDecision::Always),
            LocalExecMode::Always,
            &refused,
        );
        assert_eq!(answer_first, Some(write_first));
    }

    /// Always on the tunnel's card is kept for the card's own bot: the one whose live turn
    /// raised it, else the one its thread names, and never the bot that happens to be open. A
    /// card with neither keeps nothing, says "Sending…" like any other answer, and settles as
    /// the once it was when the run has the answer.
    #[test]
    fn a_tunnel_cards_standing_answer_is_kept_only_for_its_own_bot() {
        let mut state = AppState::new();
        state.active_conversation_id = Some("cw_open".into());
        let tunnel = tunnel_card();
        assert_eq!(state.card_bot(&tunnel).as_deref(), Some("cw_1"));
        assert_eq!(
            egress_answer(
                &tunnel,
                LocalExecResolution::Always,
                state.card_bot(&tunnel),
                ApprovalDecision::Always
            ),
            (
                Some(("cw_1".to_string(), LocalExecMode::Always)),
                ApprovalDecision::Always
            )
        );

        let mut unnamed = tunnel_card();
        unnamed.thread_id = None;
        assert_eq!(state.card_bot(&unnamed), None, "not the open bot");
        let (write, settles) = egress_answer(
            &unnamed,
            LocalExecResolution::Never,
            state.card_bot(&unnamed),
            ApprovalDecision::Never,
        );
        assert_eq!(write, None);
        assert_eq!(settles, ApprovalDecision::Denied);
        // Nothing is written over "Sending…" at the click; the once lands with the answer.
        assert_eq!(
            settled_decision(Some(&ApprovalDecision::Sending), settles),
            Some(ApprovalDecision::Denied)
        );

        // A run still live in a thread is that thread's card, whatever the card says.
        state.live_turns.insert(
            "cw_live".to_string(),
            LiveTurn {
                run_id: unnamed.run_id.clone(),
                message_id: "m_live".to_string(),
                persisting: false,
            },
        );
        assert_eq!(state.card_bot(&unnamed).as_deref(), Some("cw_live"));

        // A judge's card and a once write nothing.
        let mut judge = tunnel_card();
        judge.why = "Ask first: the page is a bank.".into();
        assert_eq!(
            egress_answer(
                &judge,
                LocalExecResolution::Always,
                Some("cw_1".into()),
                ApprovalDecision::Always
            ),
            (None, ApprovalDecision::Always)
        );
        assert_eq!(
            egress_answer(
                &tunnel,
                LocalExecResolution::AllowOnce,
                Some("cw_1".into()),
                ApprovalDecision::AllowOnce
            ),
            (None, ApprovalDecision::AllowOnce)
        );
    }

    /// The network choice follows Route traffic's surface, and only exists when the server
    /// sent one.
    #[test]
    fn egress_policy_sits_where_route_traffic_sits_and_only_when_sent() {
        fn computer(extra: serde_json::Value) -> crate::opengrok::CoworkerComputer {
            let mut body = serde_json::json!({
                "agentId": "cw_1",
                "state": "running",
                "boxId": "box_1",
                "egress_tunnel": { "ready": true }
            });
            if let (serde_json::Value::Object(map), Some(obj)) = (extra, body.as_object_mut()) {
                obj.extend(map);
            }
            serde_json::from_value(body).unwrap()
        }
        let mut state = AppState::new();
        state.active_coworker_id = Some("cw_1".into());
        state.coworker_computer = Some(computer(serde_json::json!({ "shareScope": "dedicated" })));
        assert!(state.show_route_traffic_on_bot_pane());
        assert_eq!(
            state.egress_policy(),
            None,
            "an older server sends no policy"
        );
        assert!(!state.show_egress_policy_on_bot_pane());

        state.coworker_computer = Some(computer(serde_json::json!({
            "shareScope": "dedicated",
            "egressPolicy": "ask"
        })));
        assert_eq!(state.egress_policy(), Some(LocalExecMode::Ask));
        assert!(state.show_egress_policy_on_bot_pane());
        assert!(!state.show_egress_policy_in_user_settings());

        state.coworker_computer = Some(computer(serde_json::json!({
            "shareScope": "user",
            "egressPolicy": "never"
        })));
        assert_eq!(state.egress_policy(), Some(LocalExecMode::Never));
        assert!(
            state.show_egress_policy_on_bot_pane(),
            "the agent monitor has the network rule for every computer, shared or not (#175)"
        );
        assert!(
            state.show_egress_policy_in_user_settings(),
            "and Settings → Computer keeps its own"
        );

        state.coworker_computer = Some(computer(serde_json::json!({
            "shareScope": "org",
            "egressPolicy": "bypass"
        })));
        assert!(state.show_egress_policy_on_bot_pane());
        assert!(state.show_egress_policy_in_user_settings());
        state.coworker_computer = Some(computer(serde_json::json!({
            "shareScope": "group",
            "egressPolicy": "ask"
        })));
        assert!(state.show_egress_policy_on_bot_pane());
        assert!(!state.show_egress_policy_in_user_settings());
    }

    #[test]
    fn route_traffic_surface_follows_share_scope() {
        fn computer(extra: serde_json::Value) -> crate::opengrok::CoworkerComputer {
            let mut body = serde_json::json!({
                "agentId": "cw_1",
                "state": "running",
                "boxId": "box_1",
                "egress_tunnel": { "ready": true }
            });
            if let serde_json::Value::Object(map) = extra
                && let Some(obj) = body.as_object_mut()
            {
                obj.extend(map);
            }
            serde_json::from_value(body).unwrap()
        }
        fn coworker(id: &str, box_id: &str) -> Coworker {
            serde_json::from_value(serde_json::json!({
                "id": id,
                "name": id,
                "boxId": box_id
            }))
            .unwrap()
        }

        let mut state = AppState::new();
        state.active_coworker_id = Some("cw_1".into());
        state.coworkers = vec![coworker("cw_1", "box_1")];
        state.coworker_computer = Some(computer(serde_json::json!({
            "shareScope": "dedicated"
        })));
        assert!(state.show_route_traffic_on_bot_pane());
        assert!(!state.show_route_traffic_in_user_settings());

        state.coworker_computer = Some(computer(serde_json::json!({
            "shareScope": "user"
        })));
        assert!(
            state.show_route_traffic_on_bot_pane(),
            "the agent monitor has the reroute for every computer, whoever it is shared with (#175)"
        );
        assert!(
            state.show_route_traffic_in_user_settings(),
            "and Settings → Computer keeps its own"
        );

        state.coworker_computer = Some(computer(serde_json::json!({
            "shareScope": "group",
            "groupId": "grp_1"
        })));
        assert_eq!(
            state.route_traffic_surface(),
            RouteTrafficSurface::BotPane,
            "a group's computer is the group's own: its pane"
        );

        state.coworker_computer = Some(computer(serde_json::json!({
            "shareScope": "org"
        })));
        assert_eq!(
            state.route_traffic_surface(),
            RouteTrafficSurface::UserSettings,
            "an org's computer is shared: Settings → Computer"
        );
        assert!(
            state.show_route_traffic_on_bot_pane(),
            "and the agent monitor's, as every computer's is"
        );
        assert!(state.computer_is_org_shared());

        state.coworker_computer = Some(computer(serde_json::json!({
            "shareScope": "user",
            "egress_tunnel": { "ready": false }
        })));
        assert!(
            state.show_route_traffic_on_bot_pane() && !state.show_route_traffic_in_user_settings(),
            "the monitor keeps the host-wide reroute even while this box has no tunnel"
        );

        state.coworker_computer = Some(computer(serde_json::json!({})));
        state.coworkers = vec![coworker("cw_1", "box_1"), coworker("cw_2", "box_1")];
        assert!(
            state.show_route_traffic_in_user_settings(),
            "missing shareScope + shared boxId is user-level Settings too"
        );
        assert!(
            state.show_route_traffic_on_bot_pane(),
            "and still the agent monitor's"
        );

        state.coworkers = vec![coworker("cw_1", "box_1"), coworker("cw_2", "box_2")];
        assert!(
            state.show_route_traffic_on_bot_pane(),
            "missing shareScope + unique box is dedicated pane chrome"
        );
    }

    /// Nothing is in flight, so a stop is a question with the answer "there is nothing to stop".
    /// The button is not a stop button then, but a keystroke or a driver can still ask.
    #[test]
    fn a_stop_with_no_turn_in_flight_finds_nothing_rather_than_failing() {
        let mut state = AppState::new();
        assert!(state.turn_to_stop().is_none(), "no thread is even open yet");

        state.conversations.push(thread("cw_1", Vec::new()));
        state.active_conversation_id = Some("cw_1".to_string());
        assert!(
            state.turn_to_stop().is_none(),
            "an open thread that has never been asked anything"
        );

        let mut settled = in_flight();
        settled.persisting = true;
        state.live_turns.insert("cw_1".to_string(), settled);
        assert!(
            state.turn_to_stop().is_none(),
            "a turn already on its way to disk is registered, but nothing is running under it"
        );
    }

    /// The loop the person filmed, stopped: the bubble the run had been filling in keeps what it
    /// had said, and the app says what happened to the rest of it.
    #[test]
    fn a_stop_keeps_what_the_turn_had_said_and_says_that_it_was_stopped() {
        let mut live = at(message("m_live", false, "Opening YouTube on my box."), 20);
        live.run_id = Some("run_1".to_string());
        live.parts = vec![ChatPart::Text("Opening YouTube on my box.".to_string())];
        let mut state = mid_turn(live);

        let kept = state.end_stopped_turn("cw_1", &in_flight());
        assert_eq!(
            kept.as_ref().map(|(content, _)| content.as_str()),
            Some("Opening YouTube on my box."),
            "a turn cut short is still a turn that happened, and what it said goes to disk"
        );

        let messages = &state.conversations[0].messages;
        assert_eq!(
            ids(messages)[..2],
            ["m_ask", "m_live"],
            "the message that asked and the reply that had begun are both still there"
        );
        let note = messages.last().unwrap();
        assert_eq!(note.content, STOPPED_TURN_NOTE);
        assert!(
            is_status_line(&note.content),
            "which is how the feed knows to paint it as a line rather than as speech, and how \
             `persist_assistant_reply` knows never to write it down"
        );
        assert!(
            note.run_id.is_none(),
            "it came out of no run, so a reconcile cannot mistake it for the run's own reply"
        );
        assert!(
            agui_messages(messages)
                .iter()
                .all(|sent| sent.content != STOPPED_TURN_NOTE),
            "and the coworker is never told the app's account of the turn as if it were its own"
        );

        assert!(
            !state.is_turn_in_flight(),
            "the button is a send arrow again at once, not after the reply reaches the database"
        );
        assert!(
            state.visible_bot_status().is_none(),
            "and the working line is gone"
        );
        assert!(!state.is_active_bot_responding());
    }

    /// A stop pressed before the coworker managed to say anything. There is nothing to write
    /// down, so the thread is let go here — and an empty bubble left standing over the note
    /// would read as an answer still on its way.
    #[test]
    fn a_stop_before_the_turn_said_anything_leaves_no_empty_bubble_behind() {
        let mut state = mid_turn(at(message("m_live", false, ""), 20));

        let kept = state.end_stopped_turn("cw_1", &in_flight());
        assert!(kept.is_none());

        let messages = &state.conversations[0].messages;
        assert_eq!(messages.len(), 2);
        assert_eq!(ids(messages)[0], "m_ask");
        assert_eq!(messages[1].content, STOPPED_TURN_NOTE);
        assert!(
            !state.live_turns.contains_key("cw_1"),
            "nothing is going to the database, so nothing would let the thread go later"
        );
        assert!(!state.is_turn_in_flight());
    }

    /// A turn that only took pictures said nothing, but it did something, and the pictures are of
    /// things that really happened to the box.
    #[test]
    fn a_stop_keeps_a_turn_that_had_only_taken_pictures() {
        let mut live = at(message("m_live", false, ""), 20);
        live.parts = vec![screenshot(
            "c1",
            "the box's screen",
            b"png-one",
            (1280, 800),
        )];
        let mut state = mid_turn(live);

        let kept = state.end_stopped_turn("cw_1", &in_flight());
        assert_eq!(
            kept.map(|(_, parts)| parts.len()),
            Some(1),
            "the row is kept, pictures and all"
        );
        assert!(
            state.conversations[0]
                .messages
                .iter()
                .any(|message| message.id == "m_live")
        );
    }

    // ---- A working line per thread ----------------------------------------------------------

    /// Two threads, each with a turn in it, the way `send_opengrok_turn` leaves them: the run
    /// registered against the thread and the thread's own working line lit.
    fn two_bots_working() -> AppState {
        let mut state = AppState::new();
        state.conversations.push(thread("cw_1", Vec::new()));
        state.conversations.push(thread("cw_2", Vec::new()));
        state.active_conversation_id = Some("cw_1".to_string());
        state.active_coworker_id = Some("cw_1".to_string());
        state.live_turns.insert("cw_1".to_string(), in_flight());
        state.begin_responding(Some("cw_1"), "Thinking");
        // The second bot is started while the first is still going, which is the whole of the
        // case: a turn now survives being switched away from, so leaving one running and asking
        // another for something is the ordinary thing to do.
        state.live_turns.insert("cw_2".to_string(), in_flight());
        state.begin_responding(Some("cw_2"), "Running commands");
        state
    }

    /// Reading another thread, as switching bots does.
    fn open_thread(state: &mut AppState, id: &str) {
        state.active_conversation_id = Some(id.to_string());
        state.active_coworker_id = Some(id.to_string());
    }

    /// The label a person reads is the label of the thread they are reading. Starting a second
    /// bot used to take the one field there was, so the first bot's line went dark while its run
    /// was still going.
    #[test]
    fn two_turns_in_flight_each_keep_their_own_working_line() {
        let mut state = two_bots_working();
        assert_eq!(
            state.visible_bot_status().as_deref(),
            Some("Thinking"),
            "the open thread's line is still the open thread's own"
        );
        assert!(state.is_active_bot_responding());

        open_thread(&mut state, "cw_2");
        assert_eq!(
            state.visible_bot_status().as_deref(),
            Some("Running commands"),
            "and the other thread's line is the other thread's own"
        );
        assert!(state.is_active_bot_responding());
    }

    /// Coming back to a bot that never stopped working. Its line is where it was left, and the
    /// bot next door is undisturbed by the visit.
    ///
    /// This is the sequence from the report: start a turn on one bot, start another on a second,
    /// then go back. The line used to be gone on the way back, and putting it back — which is
    /// what re-attaching to the run does — used to take it from the second bot.
    #[test]
    fn returning_to_a_running_thread_shows_that_threads_status_and_not_the_other_ones() {
        let mut state = two_bots_working();
        open_thread(&mut state, "cw_2");
        open_thread(&mut state, "cw_1");
        assert_eq!(
            state.visible_bot_status().as_deref(),
            Some("Thinking"),
            "the line is there the moment the thread is open again, not a round trip later"
        );
        assert!(
            state.is_turn_in_flight(),
            "and it agrees with the button beside it, which has always read the live turn"
        );

        // What re-attaching to the run does once the server says it is still going.
        state.begin_responding(Some("cw_1"), "Working");
        open_thread(&mut state, "cw_2");
        assert_eq!(
            state.visible_bot_status().as_deref(),
            Some("Running commands"),
            "and the bot that was left running was never touched by the visit"
        );
    }

    /// A frame belongs to the thread it came out of. It used to be checked against a single
    /// app-wide owner, so every frame of the first bot's turn was thrown away from the moment a
    /// second bot started one — the turn went on, and the app stopped hearing about it.
    #[test]
    fn a_frame_lands_on_its_own_thread_while_another_bot_is_working() {
        let mut state = two_bots_working();
        state.apply_turn_status(
            Some("cw_1"),
            ActivityTick::Set(BotActivity {
                label: "Opening youtube.com".into(),
            }),
        );
        assert_eq!(
            state.visible_bot_status().as_deref(),
            Some("Opening youtube.com"),
            "the frame was applied rather than discarded"
        );

        open_thread(&mut state, "cw_2");
        assert_eq!(
            state.visible_bot_status().as_deref(),
            Some("Running commands"),
            "and it was not painted into the thread that happened to start a turn last"
        );
    }

    /// One turn ending says nothing about the other. The clear used to be app-wide, so whichever
    /// bot finished first put the light out on the one still working.
    #[test]
    fn ending_one_threads_turn_leaves_the_other_threads_line_alone() {
        let mut state = two_bots_working();
        state.finish_responding(Some("cw_1"), false);
        assert_eq!(
            state.visible_bot_status(),
            None,
            "the thread whose turn ended has no working line"
        );
        assert!(!state.is_active_bot_responding());

        open_thread(&mut state, "cw_2");
        assert_eq!(
            state.visible_bot_status().as_deref(),
            Some("Running commands"),
            "and the bot still working still says so"
        );
        assert!(state.is_active_bot_responding());
    }

    /// A turn that has stopped to ask for permission is waiting on a person rather than working,
    /// and that is true of one thread at a time like everything else here.
    #[test]
    fn a_thread_waiting_for_an_answer_says_so_without_ending_the_other_turn() {
        let mut state = two_bots_working();
        state.finish_responding(Some("cw_1"), true);
        assert_eq!(
            state.visible_bot_status().as_deref(),
            Some(WAITING_APPROVAL_STATUS)
        );
        assert!(
            !state.is_active_bot_responding(),
            "nothing is running under it: the card is the person's to answer"
        );

        open_thread(&mut state, "cw_2");
        assert_eq!(
            state.visible_bot_status().as_deref(),
            Some("Running commands")
        );
        assert!(state.is_active_bot_responding());
    }

    // ---- A card the MCP door raised ---------------------------------------------------------

    fn queued(thread_id: &str, call_id: &str, tool: &str) -> QueuedApproval {
        QueuedApproval {
            run_id: "run_mcp".into(),
            thread_id: thread_id.into(),
            call_id: call_id.into(),
            tool: tool.into(),
            arguments: serde_json::json!({ "path": "/etc/hosts" }),
            reason: Some("policy-approval".into()),
            why: Some("Reading a file outside the workspace.".into()),
        }
    }

    /// #144: the approvals queue lists a form's park too (`reason: user-form`, recorded in
    /// `fixtures/wire/rest/GET__ag-ui_approvals/200-a_chat_turns_card_is_placed_by_its_coworker.json`).
    /// The form card is what asks the person for it; an Allow / Deny card for
    /// `request_user_form` beside it asks nothing anyone can answer.
    #[test]
    fn a_forms_park_in_the_approvals_queue_is_not_a_permission_card() {
        let recorded: serde_json::Value = serde_json::from_str(include_str!(
            "../fixtures/wire/rest/GET__ag-ui_approvals/200-a_chat_turns_card_is_placed_by_its_coworker.json"
        ))
        .expect("the recording");
        let queue: Vec<QueuedApproval> =
            serde_json::from_value(recorded["body"].clone()).expect("the queue");
        let form = queue[0].clone();
        assert_eq!(form.reason.as_deref(), Some("user-form"));

        let mut state = AppState::new();
        let coworker = form.thread_id.clone();
        state.conversations.push(thread(
            &coworker,
            vec![at(message("m_said", false, "Let me sign in."), 10)],
        ));
        state.attach_queued_approval(form);

        assert!(
            !state.conversations[0].messages.iter().any(|message| message
                .parts
                .iter()
                .any(|part| matches!(part, ChatPart::Approval(_)))),
            "no permission card for a form's park"
        );
        assert!(
            state.approval_decisions.is_empty(),
            "nothing pending to answer"
        );

        // A real permission card in the same queue still comes through.
        state.attach_queued_approval(queued(&coworker, "call_9", "read_file"));
        assert!(matches!(
            state.conversations[0].messages[0].parts.as_slice(),
            [ChatPart::Approval(spec)] if spec.call_id == "call_9"
        ));
    }

    /// The door files its cards under a thread of its own, `mcp-{coworker}`. There is no
    /// conversation by that name and there should not be one: the card goes to the coworker.
    #[test]
    fn a_card_filed_under_an_mcp_thread_is_grafted_onto_its_coworkers_thread() {
        let mut state = AppState::new();
        state.conversations.push(thread(
            "cw_1",
            vec![at(message("m_said", false, "Done."), 10)],
        ));

        state.attach_queued_approval(queued("mcp-cw_1", "call_9", "read_file"));

        let parts = &state.conversations[0].messages[0].parts;
        assert!(
            matches!(parts.as_slice(), [ChatPart::Approval(spec)] if spec.call_id == "call_9"),
            "the coworker's thread is holding the card, not a thread named after the door"
        );
        assert_eq!(state.conversations.len(), 1, "no `mcp-cw_1` conversation");
    }

    /// The card knows where it came from, so answering it puts the working line on the thread
    /// it was grafted onto rather than on whatever happens to be open.
    #[test]
    fn a_queued_card_carries_the_thread_it_was_filed_under() {
        let spec = spec_from_queued(&queued("mcp-cw_1", "call_9", "read_file"));
        assert_eq!(spec.thread_id.as_deref(), Some("mcp-cw_1"));
        assert_eq!(spec.conversation_id(), Some("cw_1"));
        assert!(spec.is_mcp());

        let chat = spec_from_queued(&queued("cw_1", "call_1", USER_MACHINE_SHELL));
        assert_eq!(chat.conversation_id(), Some("cw_1"));
        assert!(!chat.is_mcp());
    }

    /// The queue says why it stopped, and the card says it back. Only a server
    /// that sends neither gets the sentence the app used to make up.
    #[test]
    fn a_queued_card_reads_back_the_reason_the_server_sent() {
        let told = spec_from_queued(&queued("mcp-cw_1", "call_9", "read_file"));
        assert_eq!(told.reason, "policy-approval");
        assert_eq!(told.why, "Reading a file outside the workspace.");

        let mut silent = queued("cw_1", "call_1", USER_MACHINE_SHELL);
        silent.reason = None;
        silent.why = Some("   ".into());
        let spec = spec_from_queued(&silent);
        assert_eq!(spec.reason, "exec-consent");
        assert_eq!(spec.why, "your machine's owner must approve this command");
    }

    /// A card rebuilt off the queue after a relaunch says what the call would do, the same way
    /// the stream's card does, from the tool and its arguments alone, as a queue from a server
    /// before opengrok-server #263 carries them.
    #[test]
    fn a_queued_card_says_what_the_call_would_do() {
        let read = spec_from_queued(&queued("mcp-cw_1", "call_9", "read_file"));
        assert_eq!(read.summary, "Read /etc/hosts on the agent's own box");
        let mut click = queued("cw_1", "call_1", "computer");
        click.arguments = serde_json::json!({"action": "click", "coordinate": [120, 40]});
        assert_eq!(
            spec_from_queued(&click).summary,
            "Click at (120, 40) on the agent's own screen"
        );
        let shell = spec_from_queued(&queued("cw_1", "call_2", USER_MACHINE_SHELL));
        assert_eq!(shell.summary, "");
    }

    /// The card the door raised is answered from the coworker's thread, and the line it leaves
    /// behind is about the call, not about this Mac.
    #[test]
    fn an_answered_mcp_card_says_which_call_was_let_through() {
        let mut state = AppState::new();
        state.conversations.push(thread(
            "cw_1",
            vec![at(message("m_said", false, "Done."), 10)],
        ));
        state.attach_queued_approval(queued("mcp-cw_1", "call_9", "read_file"));
        let spec = match &state.conversations[0].messages[0].parts[0] {
            ChatPart::Approval(spec) => spec.clone(),
            other => panic!("the card is the part on the row: {other:?}"),
        };

        state
            .approval_decisions
            .insert("call_9".into(), ApprovalDecision::AllowOnce);
        assert_eq!(
            state.approval_status_line(&spec, "Hexuria").as_deref(),
            Some("Hexuria may run read_file once.")
        );

        state
            .approval_decisions
            .insert("call_9".into(), ApprovalDecision::Denied);
        assert_eq!(
            state.approval_status_line(&spec, "Hexuria").as_deref(),
            Some("Hexuria was told no.")
        );
    }

    // ---- Reaching the gateway, and the list that depends on it ------------------------------

    fn catalogue(ids: &[&str], note: Option<&str>) -> ModelCatalogue {
        ModelCatalogue {
            models: ids
                .iter()
                .map(|id| ModelEntry {
                    id: (*id).to_string(),
                    source: None,
                    via: None,
                    ..Default::default()
                })
                .collect(),
            note: note.map(str::to_string),
            local_proxy: None,
        }
    }

    /// A `/models` answer with both doors in it: the gateway's routes, the plan's models, the
    /// gateway's note and opencodex's health, as the server lists them.
    fn both_doors(
        gateway: &[&str],
        plan: &[&str],
        note: Option<&str>,
        proxy_healthy: Option<bool>,
    ) -> ModelCatalogue {
        let entry = |id: &&str, source: &str| ModelEntry {
            id: (*id).to_string(),
            source: Some(source.to_string()),
            via: None,
            ..Default::default()
        };
        ModelCatalogue {
            models: gateway
                .iter()
                .map(|id| entry(id, "gateway"))
                .chain(plan.iter().map(|id| entry(id, "local_proxy")))
                .collect(),
            note: note.map(str::to_string),
            local_proxy: proxy_healthy.map(|healthy| crate::opengrok::LocalProxyStatus {
                healthy,
                relay_connected: false,
            }),
        }
    }

    fn model_ids(catalogue: &ModelCatalogue) -> Vec<&str> {
        catalogue.models.iter().map(|m| m.id.as_str()).collect()
    }

    /// `/models` answers for two machines at once, and each door's list is kept apart: the
    /// gateway going leaves its routes in the Bot's Model field while the plan's models come
    /// back fresh, and opencodex going leaves the plan's models in the picker while the
    /// gateway's come back fresh. An empty plan list is taken when opencodex answered, or when
    /// no proxy address is kept at all, since nothing is missing then.
    #[test]
    fn one_door_down_does_not_empty_the_other_doors_list() {
        let gateway_down = "the gateway could not be reached: error sending request";
        let mut held = ModelCatalogue::default();
        apply_catalogue(
            &mut held,
            both_doors(
                &["oag/cheap", "oag/fast"],
                &["gpt-5-codex"],
                None,
                Some(true),
            ),
        );
        assert_eq!(model_ids(&held), ["oag/cheap", "oag/fast", "gpt-5-codex"]);

        // The gateway goes; opencodex still lists the plan's models, and a new one.
        let note = apply_catalogue(
            &mut held,
            both_doors(
                &[],
                &["gpt-5-codex", "grok-4"],
                Some(gateway_down),
                Some(true),
            ),
        );
        assert!(reads_as_gateway_unreachable(note.as_deref().unwrap()));
        assert_eq!(
            model_ids(&held),
            ["oag/cheap", "oag/fast", "gpt-5-codex", "grok-4"],
            "the Bot's Model field keeps its routes"
        );
        assert_eq!(held.note.as_deref(), Some(gateway_down));

        // opencodex goes; the gateway is back with a new route.
        let note = apply_catalogue(
            &mut held,
            both_doors(&["oag/cheap", "oag/new"], &[], None, Some(false)),
        );
        assert_eq!(note, None);
        assert_eq!(
            model_ids(&held),
            ["oag/cheap", "oag/new", "gpt-5-codex", "grok-4"],
            "the picker keeps the plan's models while opencodex is down"
        );
        assert_eq!(
            held.local_proxy,
            Some(crate::opengrok::LocalProxyStatus {
                healthy: false,
                relay_connected: false,
            }),
            "and says it is down"
        );

        // opencodex answers and serves nothing a plan may use: that is the answer.
        apply_catalogue(&mut held, both_doors(&["oag/cheap"], &[], None, Some(true)));
        assert_eq!(model_ids(&held), ["oag/cheap"]);

        // No proxy address kept: no plan models, and nothing is missing.
        apply_catalogue(
            &mut held,
            both_doors(&["oag/cheap"], &["gpt-5-codex"], None, Some(true)),
        );
        apply_catalogue(&mut held, both_doors(&["oag/cheap"], &[], None, None));
        assert_eq!(model_ids(&held), ["oag/cheap"]);
        assert_eq!(held.local_proxy, None);
    }

    /// The plan's models come two ways with the Mac relay, and each list is kept by the same rule,
    /// apart: no Mac holding the relay leaves the Mac's models in its picker while the server's
    /// own opencodex answers fresh, and opencodex down on the server's machine says nothing of
    /// the Mac's. Each way's list holds only that way's models, held to the allowlist: each is
    /// the pickers' Subscription group while the account's way to the plan is that way.
    #[test]
    fn the_macs_models_are_kept_apart_from_the_servers_machines() {
        let listed = |here: &[&str], mac: &[&str], healthy: bool, relay: bool| {
            let entry = |id: &&str, via: &str| ModelEntry {
                id: (*id).to_string(),
                source: Some("local_proxy".into()),
                via: Some(via.into()),
                ..Default::default()
            };
            ModelCatalogue {
                models: here
                    .iter()
                    .map(|id| entry(id, "loopback"))
                    .chain(mac.iter().map(|id| entry(id, "mac")))
                    .collect(),
                note: None,
                local_proxy: Some(crate::opengrok::LocalProxyStatus {
                    healthy,
                    relay_connected: relay,
                }),
            }
        };
        let mut state = AppState::new();
        apply_catalogue(
            &mut state.model_catalogue,
            listed(&["gpt-5-codex"], &["grok-4", "claude-opus"], true, true),
        );
        assert_eq!(
            state.plan_models(crate::opengrok::Via::Loopback),
            ["gpt-5-codex"]
        );
        assert_eq!(
            state.plan_models(crate::opengrok::Via::Mac),
            ["grok-4"],
            "the allowlist holds for the Mac too"
        );

        // No Mac holds the relay: its models stay, while the server's machine's come back fresh.
        apply_catalogue(
            &mut state.model_catalogue,
            listed(&["gpt-5-codex", "o3"], &[], true, false),
        );
        assert_eq!(
            state.plan_models(crate::opengrok::Via::Loopback),
            ["gpt-5-codex", "o3"]
        );
        assert_eq!(state.plan_models(crate::opengrok::Via::Mac), ["grok-4"]);

        // opencodex down on the server's machine: its models stay, and the Mac's are the Mac's.
        apply_catalogue(
            &mut state.model_catalogue,
            listed(&[], &["gpt-5.5"], false, true),
        );
        assert_eq!(
            state.plan_models(crate::opengrok::Via::Loopback),
            ["gpt-5-codex", "o3"]
        );
        assert_eq!(state.plan_models(crate::opengrok::Via::Mac), ["gpt-5.5"]);

        // A Mac answering that lists nothing: that is the answer.
        apply_catalogue(&mut state.model_catalogue, listed(&[], &[], false, true));
        assert!(state.plan_models(crate::opengrok::Via::Mac).is_empty());
    }

    /// A Bot on the person's plan names the account's way to it on every turn: through the
    /// person's Mac where that is the account's way, on the server's own machine where that is,
    /// named with its way to a server that knows the relay, and as the bare word to one from
    /// before it, the only word that one reads. A Bot on the server's keys names them whatever
    /// the account's way, and a Bot that follows the account's door names nothing.
    #[test]
    fn a_bot_on_the_plan_names_the_accounts_way_to_it() {
        use crate::opengrok::{RelayRead, Via};
        let relayed = |via: &str| InferenceSource {
            via: Some(via.into()),
            relay: Some(RelayRead {
                connected: true,
                machine_id: Some("mac_1".into()),
                machine_label: Some("NativeChat on studio".into()),
                local_model: Some("grok-4".into()),
            }),
            ..kept(InferenceKind::Gateway, Some("gpt-5-codex"))
        };
        let on = |source: serde_json::Value| {
            let mut state = signed_in_state();
            state.coworkers = vec![
                serde_json::from_value(json!({
                    "id": "cw_1", "name": "Ada", "model": "gpt-5-codex", "source": source
                }))
                .expect("a row"),
            ];
            state.active_coworker_id = Some("cw_1".into());
            state
        };
        let mut state = on(json!("local_proxy"));
        read_as(&mut state, relayed("mac"));
        assert_eq!(
            serde_json::to_value(state.turn_inference_source(None)).unwrap(),
            json!({"kind": "local_proxy", "via": "mac"})
        );
        read_as(&mut state, relayed("loopback"));
        assert_eq!(
            state.turn_inference_source(None),
            Some(TurnSource::plan(Some(Via::Loopback)))
        );
        // A server from before the relay: the bare word, the only one it reads.
        read_as(
            &mut state,
            kept(InferenceKind::Gateway, Some("gpt-5-codex")),
        );
        assert_eq!(
            serde_json::to_value(state.turn_inference_source(None)).unwrap(),
            json!("local_proxy")
        );
        // The account's setting not read yet: the plan, by the server's own way to it.
        let state = on(json!("local_proxy"));
        assert_eq!(
            state.turn_inference_source(None),
            Some(TurnSource::plan(None))
        );

        let mut state = on(json!("gateway"));
        read_as(&mut state, relayed("mac"));
        assert_eq!(state.turn_inference_source(None), Some(TurnSource::GATEWAY));
        let mut state = on(serde_json::Value::Null);
        read_as(&mut state, relayed("mac"));
        assert_eq!(
            state.turn_inference_source(None),
            None,
            "the account's door, left to the server"
        );
    }

    /// The "share my logins with all my Bots" switch is the account's: after a sign-out the next
    /// person does not see it on, or as being set, until the server says so for them, and an
    /// answer asked before the sign-out is told it is no longer wanted.
    #[test]
    fn signing_out_forgets_the_logins_switch() {
        let mut state = AppState::new();
        state.logins_for_all_bots = Some(true);
        state.logins_for_all_bots_changing = true;
        let asked = state.logins_for_all_bots_generation;

        state.forget_account();

        assert_eq!(state.logins_for_all_bots, None);
        assert!(!state.logins_for_all_bots_changing);
        assert_ne!(state.logins_for_all_bots_generation, asked);
    }

    /// Only the newest read of `/models` lands. Several are asked in a row and need not answer
    /// in order: an older one landing last is dropped, and so is one that lands after a
    /// sign-out, which also forgets the plan's models and keeps the gateway's.
    #[test]
    fn only_the_newest_models_read_lands() {
        let mut state = AppState::new();
        state.opengrok = Some(OpenGrokClient::new("http://127.0.0.1:9").expect("a URL"));
        let (_, older) = state.begin_models_read().expect("a read");
        let (_, newer) = state.begin_models_read().expect("a read");
        assert!(newer > older);
        let fresh = both_doors(&["oag/new"], &["gpt-5-codex"], None, Some(true));
        let stale = both_doors(&["oag/old"], &[], None, Some(true));
        assert!(
            state.take_models(newer, Ok(fresh)).is_some(),
            "the newer one lands"
        );
        assert!(
            state.take_models(older, Ok(stale)).is_none(),
            "the older one, landing last, is dropped"
        );
        assert_eq!(
            model_ids(&state.model_catalogue),
            ["oag/new", "gpt-5-codex"]
        );

        let (_, before_sign_out) = state.begin_models_read().expect("a read");
        state.forget_account();
        assert!(
            state
                .take_models(
                    before_sign_out,
                    Ok(both_doors(&["oag/x"], &["m"], None, None))
                )
                .is_none(),
            "an answer asked as someone who has signed out"
        );
        assert_eq!(
            model_ids(&state.model_catalogue),
            ["oag/new"],
            "the plan's models were the account's; the gateway's routes are the deployment's"
        );
        assert_eq!(state.model_catalogue.local_proxy, None);
    }

    /// The whole of the reported bug, on the data: the gateway goes, the Model field keeps what
    /// it had and says why it may be stale, and the answer that arrives once the gateway is back
    /// refills it.
    #[test]
    fn a_gateway_outage_does_not_empty_the_model_list_and_coming_back_refills_it() {
        let mut held = ModelCatalogue::default();

        let note = apply_catalogue(&mut held, catalogue(&["xai/grok-4.6", "oag/auto"], None));
        assert_eq!(note, None);
        assert_eq!(held.models.len(), 2);

        // `/models` never fails: a gateway it cannot reach answers 200, empty, with the reason.
        let down = catalogue(
            &[],
            Some(
                "the gateway could not be reached: error sending request for url \
                 (http://127.0.0.1:29080/v1/models)",
            ),
        );
        let note = apply_catalogue(&mut held, down);
        assert_eq!(
            held.models.len(),
            2,
            "the list the app already has is still a list it can offer"
        );
        assert!(reads_as_gateway_unreachable(
            note.as_deref().expect("the server said why")
        ));
        assert!(
            held.note.is_some(),
            "and the field can say why it may be stale"
        );

        let note = apply_catalogue(
            &mut held,
            catalogue(&["xai/grok-4.6", "oag/auto", "new"], None),
        );
        assert_eq!(note, None, "nothing left to explain");
        assert_eq!(held.models.len(), 3, "the newer list is taken");
        assert_eq!(held.note, None);
    }

    /// An empty answer with nothing to explain it is a real answer — this key routes nowhere —
    /// and holding a stale list against it would be the app inventing models.
    #[test]
    fn an_empty_answer_with_no_reason_is_taken_as_the_answer() {
        let mut held = catalogue(&["xai/grok-4.6"], None);
        let note = apply_catalogue(&mut held, catalogue(&[], None));
        assert_eq!(note, None);
        assert!(held.models.is_empty());
    }

    /// A gateway that answered and had nothing to offer is not a gateway out of reach: the note
    /// belongs on the field, but nothing is worth retrying.
    #[test]
    fn a_gateway_that_answers_with_no_models_is_not_a_gateway_to_wait_for() {
        let mut held = ModelCatalogue::default();
        let note = apply_catalogue(
            &mut held,
            catalogue(
                &[],
                Some(
                    "the gateway advertises no models on this key's route — a pin can still be \
                     typed by hand",
                ),
            ),
        );
        assert!(!reads_as_gateway_unreachable(
            note.as_deref().expect("a note")
        ));
        assert!(held.note.is_some(), "the field still says what happened");
    }

    /// The app's own account of a turn that never left is one of its status lines: painted, not
    /// saved, and never handed to the model as something the coworker said.
    #[test]
    fn a_turn_that_never_left_is_a_status_line_and_not_the_coworkers_words() {
        assert!(is_status_line(TURN_UNREACHED_NOTE));
        let sent = agui_messages(&[
            message("m1", true, "open youtube"),
            message("m2", false, TURN_UNREACHED_NOTE),
        ]);
        assert_eq!(
            sent.iter().map(|m| m.content.as_str()).collect::<Vec<_>>(),
            vec!["open youtube"]
        );
    }

    /// Only the thread's last turn is offered again. An older one has messages after it, and
    /// re-running the thread from there would answer the newest message instead.
    #[test]
    fn the_turn_offered_again_is_the_last_one_and_only_while_nothing_is_running() {
        let mut state = AppState::new();
        state.conversations.push(thread(
            "cw_1",
            vec![
                at(message("m_ask", true, "open youtube"), 10),
                at(message("m_failed", false, TURN_UNREACHED_NOTE), 20),
            ],
        ));
        state.active_conversation_id = Some("cw_1".to_string());
        assert_eq!(state.retryable_turn().as_deref(), Some("m_failed"));

        state.live_turns.insert("cw_1".to_string(), in_flight());
        assert_eq!(
            state.retryable_turn(),
            None,
            "a thread already running a turn has nothing to send again"
        );
        state.live_turns.remove("cw_1");

        state.conversations[0]
            .messages
            .push(at(message("m_next", true, "never mind"), 30));
        assert_eq!(
            state.retryable_turn(),
            None,
            "the thread has moved on, and the turn to run is not the old one"
        );
    }

    /// A run the server refused is a verdict, and it keeps the red line with the server's own
    /// sentence in it. Only a turn that never left gets the quiet line that can be answered.
    #[test]
    fn a_refused_run_still_says_why_where_a_turn_that_never_left_does_not() {
        let refused = format!("{RUN_ERROR_PREFIX}the model gateway refused: 402 spend cap");
        assert!(is_status_line(&refused));
        assert_ne!(refused, TURN_UNREACHED_NOTE);
        assert!(
            !TURN_UNREACHED_NOTE.starts_with(RUN_ERROR_PREFIX),
            "which is what keeps it out of the colour of a failure"
        );
    }

    /// The three endings a turn can have that are not the coworker speaking read as three
    /// different things, and the signed-out one is the newest of them.
    ///
    /// It was a red line with the server's sentence in it — "this turn does not say whose spend
    /// it is" — which read as a verdict about the turn and sent somebody looking at spend
    /// limits. It is now its own quiet line, distinct from the wire's, because the thing to do
    /// about it is different and the sentence is where a person learns that.
    #[test]
    fn a_turn_that_was_not_sent_says_so_without_naming_a_machine_or_a_verdict() {
        assert!(is_status_line(TURN_SIGNED_OUT_NOTE));
        assert!(
            !TURN_SIGNED_OUT_NOTE.starts_with(RUN_ERROR_PREFIX),
            "nothing about the run went wrong, so it is not painted as a failure"
        );
        assert_ne!(
            TURN_SIGNED_OUT_NOTE, TURN_UNREACHED_NOTE,
            "one is fixed by waiting and one is fixed by signing in"
        );
        assert!(
            !TURN_SIGNED_OUT_NOTE.contains("go through"),
            "which would send somebody to look at a network that is working"
        );

        // And, like every other line the app writes itself, it is never handed back to the model
        // as something the coworker said.
        let sent = agui_messages(&[
            message("m1", true, "open youtube"),
            message("m2", false, TURN_SIGNED_OUT_NOTE),
        ]);
        assert_eq!(
            sent.iter().map(|m| m.content.as_str()).collect::<Vec<_>>(),
            vec!["open youtube"]
        );
    }

    /// Both turns that never left are offered again, and nothing else is.
    ///
    /// A turn that was not sent ran nothing and decided nothing, so sending it after signing in
    /// does nothing twice — which is the whole reason it can be offered at all.
    #[test]
    fn a_turn_the_app_never_sent_is_offered_again_once_there_is_a_session() {
        assert!(is_unsent_turn_note(TURN_SIGNED_OUT_NOTE));
        assert!(is_unsent_turn_note(TURN_UNREACHED_NOTE));
        assert!(
            !is_unsent_turn_note(&format!("{RUN_ERROR_PREFIX}the model gateway refused")),
            "a run that happened and was refused is not a run to repeat"
        );
        assert!(!is_unsent_turn_note(STOPPED_TURN_NOTE));

        let mut state = AppState::new();
        state.conversations.push(thread(
            "cw_1",
            vec![
                at(message("m_ask", true, "open youtube"), 10),
                at(message("m_unsent", false, TURN_SIGNED_OUT_NOTE), 20),
            ],
        ));
        state.active_conversation_id = Some("cw_1".to_string());
        assert_eq!(state.retryable_turn().as_deref(), Some("m_unsent"));

        // Not while the app is still signed out, though: it would send nothing, and a button
        // that does nothing under a banner explaining why is worse than no button.
        state.session.note(Failure::SignedOut);
        assert_eq!(state.retryable_turn(), None);
        state.session.signed_in();
        assert_eq!(state.retryable_turn().as_deref(), Some("m_unsent"));
    }

    /// With no session, a turn is not attempted.
    ///
    /// Two ways of knowing and the app takes either: nothing in the jar to sign the turn with,
    /// or a `401` already heard back. The first is the one that was missing — the roster was on
    /// screen, the composer took the message, and the turn went out with no credential on it.
    #[test]
    fn a_turn_is_not_attempted_while_the_app_has_no_session() {
        let mut state = AppState::new();
        state.opengrok =
            Some(OpenGrokClient::new("http://127.0.0.1:1/").expect("a URL that parses"));
        assert!(
            !state.can_send_turn(),
            "an empty jar is an answer the app already has, without spending a round trip on it"
        );
        assert_eq!(
            state.session_banner(),
            None,
            "though it has not been told yet, so there is nothing on screen about it"
        );

        // Being told is what puts it on screen, and it stays there: no retry loop can help.
        state.session.note(Failure::SignedOut);
        assert!(state.is_session_expired());
        assert!(state.session_banner().is_some());
        assert!(!state.can_send_turn());

        // And a machine out of reach must not do any of that. Signing in cannot fix a router.
        let mut wire = AppState::new();
        wire.session
            .note(crate::opengrok::OpenGrokError::from_server(Some(502), "Bad Gateway").failure());
        assert!(!wire.is_session_expired());
        assert_eq!(wire.session_banner(), None);
    }

    /// Signing in clears it, and so does signing out on purpose.
    #[test]
    fn signing_in_clears_the_signed_out_state() {
        let mut state = AppState::new();
        state.session.note(Failure::SignedOut);
        assert!(state.is_session_expired());

        state.session.signed_in();
        assert!(!state.is_session_expired());
        assert_eq!(state.session_banner(), None);
        assert!(
            state.session.may_send(true),
            "and turns can be sent again the moment there is something to send them with"
        );
    }

